window.READER_DATA={"title": "Yakan Kayfa Nadu", "slug": "yakan-kayfa-nadu", "pages": [{"n": 1, "paras": ["فتحي يكن", "كيف ندعو إلى الإسلام", "مؤسسة الرسالة"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0001.png"}, {"n": 2, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0002.png"}, {"n": 3, "paras": ["جميع الحقوق محفوظة الطبعة الحادية عشر", "١٤٠٨ ه - ١٩٨٨ م الطبعة الثالثة عشر", "١٤١١ ه - ١٩٩١ م", "مؤسسة الرسالة مؤسسة الرسالة بيروت - شارع سوريا - بناية صمدي وصالحة للطباعة والنشر والتوزيع هاتف ٢١٩٠٢٩ - ٨١٥١١٢ ص.ب ٧٤٦٠ برقياً: بيوشران", "دار الأيمان للطباعة والنشر والتوزيع - طرابلس - لبنان هاتف: ٤٤٠٢٩٠ - ٦٢٩٢٨٨ - ص.ب ٥٧٨ - برقياً: رضاكو"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0003.png"}, {"n": 4, "paras": ["فتحي يكن", "كيف ندعو إلى الإسلام ؟", "مؤسسة الرسالة دار الإيمان"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0004.png"}, {"n": 5, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0005.png"}, {"n": 6, "paras": ["موضوعات الكتاب", "* المقدمة ٧", "- في مبدأ الدعوة الى الاسلام ٩", "- دعاة على هامش الدعوة ١١", "- وجوب الدعوة الى الاسلام ١٤", "- في الدعوة الى الاسلام ١٩", "- كيف ندعو الى الاسلام ٢١", "- اسلوب الدعوة ومخاطبة الناس ٢٧", "- الاتصال الفردي المباشر ٣١", "- من عوامل النجاح ٣٩", "- في الموضوعات التي يحسن طرحها ٤٧", "- نقد الواقع القائم ٤٩", "- نقد الاتجاهات المعاصرة ٦٩", "- اثبات الحاجة الى الاسلام ٨٧", "- اثبات ان الاسلام منهج حياة ٨٩", "- مصادر المنهج الاسلامي ٩١", "- خصائص المنهج الاسلامي ١٠٣", "- الخطوط الكبرى للمنهج الاسلامي ١٠٩", "- العناصر الاساسية لبحث الايمان بالله واثبات وجوده ١١٥", "- التنظيم الحركي ضرورة ١٦٣", "ه"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0006.png"}, {"n": 7, "paras": ["هذا الكتاب هو \"الرسالة القشيرية\" للإمام أبي القاسم القشيري، وهو من أمهات كتب التصوف الإسلامي.", "يحتوي هذا الكتاب على مجموعة من الأبواب التي تتناول مفاهيم التصوف، وأحوال الصوفية، ومقاماتهم، وآدابهم، مع الاستشهاد بالآيات القرآنية والأحاديث النبوية وأقوال المشايخ.", "يُعد هذا الكتاب مرجعاً أساسياً لكل من أراد فهم المنهج الصوفي القائم على الكتاب والسنة، حيث يجمع بين العلم والعمل، وبين الظاهر والباطن.", "وقد اعتنى العلماء بهذا الكتاب شرحاً وتدريساً، لما له من أثر كبير في تهذيب النفوس وتزكية القلوب."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0007.png"}, {"n": 8, "paras": ["بسم الله الرحمن الرحيم", "المقدمة", "العاملون في الحقل الاسلامي بامس الحاجة اليوم الى منهج ( تبليغ ) يتقيدون به ، والى منطلقات فكرية وحركية يصدرون عنها في نطاق دعوة الناس الى الاسلام ... والى ان يكون كل ذلك من الدقة والوضوح بحيث تتحقق معها الرؤيا لابعاد الطريق وخصائصه ومواصفاته فلا يخبطون بعدها خبط عشواء ، أو يسيئون الى الاسلام وهم يحسبون انهم يحسنون صنعا .", "ولذلك فهم بحاجة الى منهج يحدد لهم طريق الدعوة الى الله ، وكيفية مخاطبة الناس واقناعهم .. كما يحدد الموضوعات التي يحسن طرحها عليهم وتبسيطها لهم .", "هذا المنهج يتألف - في نظري - من اربعة مباحث :", "المبحث الأول :", "ويدور حول فرضية الدعوة الى الله .. وان الايمان بالاسلام يقتضي العمل له، والدعوة اليه ، والجهاد في سبيله.", "V"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0008.png"}, {"n": 9, "paras": ["وان ذلك يقتضي قيام تجمع حركي . وان العمل الفردي لن يأتي بواقع اسلامي أو يحقق مجتمعا اسلاميا ...", "المبحث الثاني : وهو عبارة عن عرض للاسلوب الذي يحسن اتباعه في دعوة الناس الى الاسلام .. وان على الدعاة ان يخاطبوا الناس من حيث تقدر استجابتهم ، وان يخاطبوهم على قدر عقولهم .. وان تكون سياستهم في ذلك الدراية والحكمة والصبر ..", "المبحث الثالث : وهو عبارة عن عرض سريع للخطوط الكبرى التي يقوم عليها المنهج الاسلامي سواء في نطاق العقيدة ام في نطاق الشريعة .. وهذه تشكل بمجموعها الموضوعات التي يحسن طرحها على بساط البحث أمام العناصر المراد دعوتها ..", "المبحث الرابع : وأما المبحث الرابع والاخير فهو عبارة عن تأكيد ضرورة قيام عمل جماعي حركي للاسلام .. وانه - اي العمل الجماعي الحركي - هو الطريق الذي انتهجه الرسول صلى الله عليه وسلم في بناء الجماعة الاسلامية الاولى .. وان كل عمل فردي للاسلام مآله الى الضياع ما لم يرتبط بتنظيم حركي .. وان هذا كله يفرض على المؤمنين بالاسلام ان يقيموا تنظيما حركيا او ان ينضووا في تنظيم حركي قائم . وانني اذ اتقدم بهذه الرسالة الى اخواني الدعاة في كل مكان أسأل الله عز وجل ان يكتب الاجر ويمحو الوزر ويحقق النفع .", "وان الله لهادي الذين آمنوا الى صراط مستقيم المؤلف"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0009.png"}, {"n": 10, "paras": ["المبحث الأول", "في مبدأ الدعوة الى الاسلام", "• دعاة على هامش الدعوة", "• فرضية الدعوة الى الاسلام"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0010.png"}, {"n": 11, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0011.png"}, {"n": 12, "paras": ["دُعَاةٌ عَلَى هَامِشِ الدَّعْوَةِ", "كثيرون من دعاة الاسلام في هذا العصر غير متفهمين تماما لطبيعة الاهداف التي يعملون لها، ولا بعد الطريق التي يسيرون فيها ، ولحقيقة المتطلبات التي يحتاجها العمل الاسلامي من حياتهم ووقتهم وتفكيرهم ، ومن انفسهم واموالهم . وهذا ما يجعلهم في كثير من الاحيان امثلة غير حسنة لما يدعون الناس اليه ، ونماذج غير صالحة لما يأمرون الناس به . وبالتالي يجعلهم في حياة الحركة الاسلامية عبئا ثقيلا ، واوزارا تعيق سيرها وتحول دون انطلاقها ..", "ان فريقا من هؤلاء يظنون ان تكاليف العمل الاسلامي تسقط عن كواهلهم اذا هم اصدروا كتابا ، او كتبوا مقالا ، او ألقوا محاضرة . واخرين يعتقدون ان مجرد انتسابهم الى حركة اسلامية وحضورهم اجتماعاتها ، ودورانهم في فلكها هو غاية الغايات ومنتهى الامنيات ؟", "ان هؤلاء وأولئك - لا شك - يعيشون على هامش العمل الاسلامي ، ولم يدخلوا في الواقع ميدانه الاصيل او يعيشوا اجواءه الحقيقية .."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0012.png"}, {"n": 13, "paras": ["ان المفهوم الصحيح لتكاليف العمل الاسلامي ينبغي ان يرسخ في اذهان العاملين انهم مدعوون لشيء يسمى ( التضحية ) .. التضحية التي تتجاوزها في معناها حدود اصنافها واوصافها .. والتي تعني تقديم مصلحة الاسلام على كل مصلحة .. والتي تعني كذلك الدوران في رحى الاسلام كائنا ما كانت الظروف ومهما غدت التضحيات ..", "قد رشحوك لامر لو فطنت له فارباً بنفسك ان ترعى مع الهمل", "ان ( العمل للاسلام ) يعني العمل على هدم ( المجتمع الجاهلي ) في كل ركن من اركانه واقامة « المجتمع الاسلامي» في كل شأن من شؤونه .. يعني استئصال الجاهلية كلها .. سواء كانت جاهلية افكار ام جاهلية نظم او جاهلية اخلاق .. ويعني كذلك مواجهة دعاة هذه الجاهلية والمدافعين عنها ، ويعني اخيرا اقامة حكم الله في الارض وهدم حكم الطاغوت ..", "ان طريقا كهذا الطريق الصعب الشاق .. وان اهدافا كهذه الاهداف الضخمة الكبيرة .. وان تكاليف كهذه التكاليف كهذه التكاليف الجسيمة الثقيلة .. ينوء بحملها ضعفاء الايمان ، ولا يستطيع التصدي لها الا من وقف حياته للجهاد في سبيل الله ، والا من كان الله ورسوله احب اليه مما سواهما - والا من استخلص نفسه من الشغف بمتاع الدنيا وشهواتها والاقبال على مفاتنها ومغرياتها ( واما من خاف مقام ربه ونهى النفس عن الهوى فان الجنة هي المأوى ) .", "ان شرف العمل للاسلام لا يستحقه دعي بلسانه ، او متشذق ببيانه ، انما يستحقه الذين يعيشون للاسلام ويموتون من اجله لا تلهيهم تجارة ولا بيع عن ذكر الله والجهاد في سبيله « يقاتلون في سبيل الله فيقتلون ويقتلون .. وعدا عليه حقا في التوارة والانجيل والقرآن » ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0013.png"}, {"n": 14, "paras": ["ومن اوفى بعهده من الله .. فاستبشروا ببيعكم الذي بايعتم به . وذلك هو الفوز العظيم . ان طريق الجنة ايها الدعاة وعر وشاق ، وان سلعة الله غالية لا ينالها الا من دفع الثمن وسدد الحساب .. وصدق رسول الله صلى الله عليه وسلم حيث يقول « من خاف ادلج .. ومن ادلج بلغ المنزل . الا ان سلعة الله غالية ، الا ان سلعة الله الجنة » . (١)", "قال شداد بن الهاد : جاء رجل من الاعراب الى النبي صلى الله عليه وسلم فامن به واتبعه . فقال : اهاجر معك . فأوصى به بعض اصحابه . فلما كانت غزوة خيبر غنم رسول الله صلى الله عليه وسلم شيئا فقسمه وقسم للاعرابي . فقال الاعرابي للرسول : ما على هذا اتبعتك .. ولكن اتبعتك على ان ارمى ها هنا - واشار الى حلقه بسهم - فأموت فأدخل الجنة . فقال : ان تصدق الله ليصدقك الله . ثم نهضوا الى قتال العدو . فأتي به وهو مقتول . فقال الرسول صلى الله عليه وسلم : أهو هو ؟ قالوا نعم . قال ( صدق الله فصدقه ) .", "هذا هو طريق الجنة يا دعاة الاسلام .. عمل متواصل ، وجهاد مستمر ، وحرص على الشهادة « والذين جاهدوا فينا لنهدينهم سبلنا ، وان الله لمع المحسنين » .", "(١) رواه الترمذي والحاكم ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0014.png"}, {"n": 15, "paras": ["وجوب الدعوة إلى الإسلام", "دعوة الناس إلى الاسلام ، وامرهم بالمعروف ، ونهيهم عن المنكر ، واجب اسلامي يجدر بالعاملين في الحقل الاسلامي ان ينهضوا به ويولوه حقه من جهدهم وتفكيرهم ووقتهم . بل ان هذا الواجب بالذات هو المهمة الاصيلة الاساسية لكل داعية .. والقرآن الكريم حض على القيام بهذا الواجب في العديد من آياته منها قوله تعالى ( ولتكن منكم أمة يدعون إلى الخير ويأمرون بالمعروف وينهون عن المنكر واولئك هم المفلحون ) وقوله ( ومن احسن قولا ممن دعا الى الله وعمل صالحا وقال انني من المسلمين ) وقوله ( فلذلك فادع واستقم كما امرت ولا تتبع اهواءهم ) وقوله ( وادع الى ربك انك لعلى هدى مستقيم ) وقوله ( يا ايها الرسول ابلغ ما انزل اليك من ربك وان لم تفعل فما بلغت رسالته ) . والسنة المطهرة تذخر بما روي عن الرسول صلى الله عليه وسلم من احاديث في شأن النهوض بواجب الدعوة الى الله ومكافحة المنكرات ، نذكر منها على سبيل المثال ، قوله صلى الله عليه وسلم ( من رأى منكم منكرا فليغيره بيده فان لم يستطع فبلسانه ، فان لم يستطع فبقلبه وذلك اضعف"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0015.png"}, {"n": 16, "paras": ["الايمان وليس وراء خردل من ايمان ) (۱) وقوله ( يا ايها الناس ، ان الله يقول لكم ، مروا بالمعروف وانهوا عن المنكر قبل ان تدعوا فلا اجيب لكم ، وتسألوني فلا اعطيكم ، وتستنصروني فلا انصركم ) (۲) وقوله ( من كتم علما مما ينفع الله به الناس في امر الدين ألجمه الله يوم القيامة بلجام من نار ) (۳) وقوله ( ما بال قوم لا يفقهون جيرانهم ولا يعلمونهم ولا يعظونهم ولا يأمرونهم ولا ينهوهم . وما بال اقوام لا يتعلمون من جيرانهم ولا يتفقهون ، ولا يتعظون ، والله ليعلمن قوم جيرانهم ويفقهونهم ويعظونهم ويأمرونهم وينهوهم ، وليتعلمن قوم من جيرانهم ويتفقهون ويتعظون او لاعاجلنهم بالعقاب ) . (٤)", "ما لا يتم الواجب الا به فهو واجب", "ثم ان دعوة الناس الى الاسلام واقناعهم به وتهيئتهم للنزول عند اصوله واحكامه ، من الوسائل التي يتحقق بها اقامة المجتمع الاسلامي واستئناف الحياة الاسلامية .. فاذا كان تحقق المجتمع المسلم واجبا بذاته ، فتصبح - بالتالي - كل وسيلة لاقامته وايجاده واجبا هي الاخرى .. بل ان الامر ابعد من هذا - كذلك - اذ ان الاسلام اليوم ليس له دولة تحتكم اليه في شؤونها وتصدر عنه في جميع تصرفاتها .. فاحكام الاسلام معطلة .. فاذا كان الاحتكام الى شرعة الله فريضة اسلامية ، وكان تحقيق هذه الفريضة", "(۱) رواه مسلم .", "(۲) رواه الترمذي وقال حديث حسن .", "(۳) رواه ابن ماجه .", "(٤) رواه الطبراني في الكبير ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0016.png"}, {"n": 17, "paras": ["مرهونا بوجود دولة ، يصبح بالتالي العمل لاقامة الدولة الاسلامية - ومن أهم وسائله الدعوة الى الله - فريضة عين على كل مسلم حتى يتحقق وجود هذه الدولة ، كما يصبح المتخلفون عن ذلك ( آثمين ) شرعا ، ولا يرفع الاثم عنهم سوى نهوضهم بتبعات الدعوة الى الاسلام واسهامهم الفعلي - في حدود طاقاتهم وامكانياتهم - بتهيئة كل الاسباب والوسائل لاقامة دولة الاسلام .", "العمل عنوان الايمان وثمرته", "والايمان نفسه ، ما لم يدفع الى العمل الدائب في سبيل نشر المبادىء التي تحقق بها الايمان فهو ليس بايمان .. فالايمان قناعة عقل ، واطمئنان قلب ، وجهاد نفس ( ولنبلونكم حتى نعلم المجاهدين منكم والصابرين ونبلوا اخباركم ) وصدق الرسول صلى الله عليه وسلم حيث يقول ( ليس الايمان بالتمني ولكن ما وقر في القلب وصدقه العمل ) (١) .", "هذا وليعلم دعاة الاسلام ان اول مراتب العمل تزكية النفس واستخلاصها من عيوبها وانحرافاتها ، ثم التواصي بالحق والصبر والدعوة الى الله والجهاد في سبيله .", "فدعاة الاسلام مطالبون ببذل قصارى جهدهم للقيام بتكاليف الدعوة ، وتبليغها الى الناس ، وتبسيطها لهم ، بحسب مستوياتهم من الفهم والادراك . وهذه هي الامانة التي أؤتمنوا عليها ليكونوا ورثة الانبياء .. ثم ليسمعوا قول الرسول الاعظم صلى الله عليه وسلم ( ما من نبي بعثه الله في امة", "(١) رواه الديلمي في مسند الفردوس ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0017.png"}, {"n": 18, "paras": ["قبلي ، الا كان له من امته حواريون واصحاب ، يأخذون بسنته ، ويقتدون بأمره . ثم انها تخلف من بعدهم خلوف ، يقولون ما لا يفعلون ، ويفعلون ما لا يؤمرون ، فمن جاهدهم بيده فهو مؤمن ، ومن جاهدهم بلسانه ، فهو مؤمن ، ومن جاهدهم بقلبه فهو مؤمن . وليس وراء ذلك من الايمان حبة خردل ) (١) . الله احق ان تخشوه", "وقد يتحاشى بعض الدعاة احيانا الكلام في موطن تجب فيه النصيحة ، او تنفع معه الكلمة الجريئة الحقة ، خوفا من ان يجر ذلك عليهم سخط الناس واذاهم .. وهذا التصرف بدون شك ثمرة من ثمرات الجبن والخوف ، وهما صفتان ينبغي أن لا تعرفا طريقهما الى قلب مؤمن .", "فالله احق ان نخشاه ، والله احق ان نخافه ، وليكن حرصنا دائما وأبدا على رضاه ، وان أسخط الناس اجمعين . ( اللهم ان لم يكن بك غضب علي فلا ابالي ) .", "لقد فرض على دعاة الاسلام ان يحملوا مواريث النبوة، وان يضطلعوا بأعبائها .. ولقد كان من اهم مواريث النبوة، مواجهة الجاهلية في شتى صورها واشكالها ، ومجاهدة المنكر، مهما كانت صولته وجولته ، مصداقا لقول الله تعالى ( وقل الحق من ربكم فمن شاء فليؤمن ومن شاء فليكفر ) وروي عن عبادة بن الصامت انه قال ، ( بايعنا رسول الله صلى", "(١) رواه مسلم ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0018.png"}, {"n": 19, "paras": ["الله عليه وسلم ان نقول الحق اينما كنا لا نخاف في الله لومة لائم ) (۱) . فليحذر دعاة الاسلام من ان يكونوا جبناء في موطن الشجاعة ، خائفين في موطن النصح ، وليصغوا الى ما رواه أبو داود والترمذي عن عبد الله بن مسعود رضي الله عنه عن رسول الله صلى الله عليه وسلم انه قال ( ان اول ما دخل النقص على بني اسرائيل ، كان الرجل يلقى الرجل فيقول : يا هذا اتق الله ودع ما تصنع ، فانه لا يحل لك . ثم يلقاه من الغد فلا يمنعه ذلك ان يكون اكيله وشريبه وقعيده . فلما فعلوا ذلك ضرب الله قلوب بعضهم ببعض ) ثم قال ( لعن الذين كفروا من بني اسرائيل على لسان داود وعيسى بن مريم ، ذلك بما عصوا وكانوا يعتدون ، كانوا لا يتناهون عن منكر فعلوه لبئس ما كانوا يفعلون ) .", "(۱) رواه ابو داود والترمذي وقال حديث حسن ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0019.png"}, {"n": 20, "paras": ["المبحث الثاني في الدعوة إلى الإسلام .", "• كيف ندعو إلى الإسلام", "• أسلوب الدعوة ومخاطبة الناس", "• الاتصال الفردي المباشر", "• عوامل نجاح الداعية"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0020.png"}, {"n": 21, "paras": ["هذا الكتاب لا يحتوي على أي نص عربي."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0021.png"}, {"n": 22, "paras": ["كيف ندعو إلى الإسلام ؟", "من طبيعة الدعوة الاسلامية انها موجهة للناس - كل الناس - على اختلاف اعمارهم وطبقاتهم وثقافاتهم وبيئاتهم وميولهم واتجاهاتهم .. وهذا يفرض على الدعاة ان يكونوا حكماء بارعين في نقل ارائهم ومفاهيمهم الى هذه الاصناف الشتى من الناس . وبالتالي يوجب عليهم ان يعرفوا من اين تؤكل الكتف .. والداعية الموفق الناجح هو الذي يعطي كل انسان ما يلزمه من افكار وتوجيهات ، ويحاول ان يقنعه بالفكرة ويجذبه الى الحركة بالاسلوب الذي يؤثر فيه، وهذا سر قوله صلى الله عليه وسلم ( نحن معاشر الانبياء امرنا ان ننزل الناس منازلهم ونكلمهم على قدر عقولهم ) (١) .", "تعرف الى الشخص قبل دعوته", "واذا كانت المسألة هكذا فانه يصبح من واجب الداعية ان يتعرف الى الشخص الذي يود دعوته الى الاسلام .. يتعرف", "(١) رواه أبو داوود ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0022.png"}, {"n": 23, "paras": ["الى افكاره ومفاهيمه وتصوراته ويكتشف علله ومشكلاته .. وهو بذلك سيصل حتما الى معرفة المنافذ التي يمكن ان ينفذ من خلالها الى نفسه . وهذا من شأنه ان يوفر للداعية التشخيص والمعالجة الناجحين وبالتالي يكسب القاءاته وتوجيهاته وايحاءاته فاعلية التأثير والتفاعل .", "من اين تبدأ ... وكيف", "ان من ابرز الاسئلة التي تواجه الداعية في مجال احتكاكه بالعناصر الجديدة ومحاولة اقناعها بالفكرة الاسلامية هي كيف يبدأ دعوته ومن اين تكون البداية ؟ .. والحقيقة ان الاصابة في تحديد نقطة البدء توفر على الداعية كثيرا من الوقت وتسهل عملية الاقناع والجذب .. وفي كثير من الاحيان يكون فشل الداعية في اجتذاب العناصر الجديدة الى الدعوة مرده الى سوء تقديره لنقطة البدء وسوء تشخيصه للعلة المراد تطييبها - فيبدأ من حيث ينبغي ان ينتهي ، او ينتهي من حيث ينبغي ان يبدأ . وصدق رسول الله صلى الله عليه عليه وسلم حيث يقول ( ما احد يحدث قوما بحديث لا تبلغه عقولهم الا كان فتنة على بعضهم ) .", "مشروع منهج قياسي", "ولهذا كان لا بد من منهج قياسي واضح تحدد بواسطته نقطة البداية ، ويعرف بواسطته الداعية - كل داعية - كيف يبدأ ومن اين ..", "ففي اللقاءات الاولى ينبغي ان يحرص الداعية على تقييم"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0023.png"}, {"n": 24, "paras": ["العنصر المراد دعوته الى الاسلام .. فاذا تم له ذلك أصبح بمقدوره مقارنته بالانموذج القياسي وتحديد موضعه منه والطور الذي يقابله فيه ، ومن ثم متابعته من هذا الموضع بالذات وفق المنهج المحدد لذلك ..", "وفي اعتقادي ان الانموذج القياسي ينبغي ان تحدد مواصفاته واطواره على الشكل التالي :", "اولا : طور بناء العقيدة أي ايجاد الفكر الصحيح عن الكون والانسان والحياة .. ومن شرائطه تحقق الايمان بالله وسائر اركان الايمان الخمسة . وهذا الطور يعتبر الطور الاساسي في تكوين الشخصية الاسلامية لانه القاعدة التي تتمخض عنها سائر الاطوار ، ولانه العقدة الكبرى التي بحلها تحل سائر العقد ..", "- ومن شرائط هذا الطور كذلك تحقق الايمان بالاسلام وانه المنهج المبرأ من عوامل العجز البشري ، لانه من لدن عليم خبير قوي قدير . وانه المنهج الشامل المتكامل ، المنبثق عن فلسفة كونية اصيلة مستقلة الجذور . وان المناهج الاخرى باطلة اساسا لانها بشرية المصدر . وبشريتها هذه تجعلها قاصرة عاجزة محكومة بمؤثرات الهوى .", "- وهذا يقتضيه دراسة الفكرة الاسلامية دراسة مركزة واعيد ودراسة الاتجاهات والمذاهب الاخرى ليعمل على نقضها وكشف عيوبها ومثالبها", "من النظرية الى التطبيق", "ثانيا : والطور الثاني الذي ينبغي نقل العنصر الجديد اليه ، اذا حسن ايمانه ورسخت عقيدته وتكامل فهمه عن"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0024.png"}, {"n": 25, "paras": ["الاسلام ، هو طور التطبيق ، اي طور تجسيد النظريات الايمانية سلوكا اسلاميا صحيحا .. وهذا معنى قوله صلى الله عليه وسلم ( ليس الايمان بالتمني ولا بالتحلي ، ولكن هو ما وقر في القلب وصدقه العمل ) .", "ان طبيعة الاسلوب الذي تعتمده مناهج التربية في الاسلام لبناء الشخصية الاسلامية ، انما تقوم اساسا على تركيز دعائم العقيدة ، وتعميق اصولها في النفس الانسانية، قبل صدور التكاليف العبادية والتشريعية والتوجيهية اليها وليس العكس قطعا ..", "ذلك ان الاخلاق والعبادات والمعاملات الاسلامية هي مظهر من مظاهر الوجود العقيدي واثر من اثاره .. وبقدر ما يكون هذا متينا راسخا بقدر ما يتحقق التوافق والتلازم بين المظهر والجوهر ، اي بين المعتقدات والتصرفات ..", "ومما يؤكد كل هذا ان التكاليف العبادية والاحكام الشرعية انما جاء ترتيبها من النزول بعد الفروغ من تركيز التصور العقيدي وتثبيت اصوله وقواعده ..", "ولذلك كان من مقتضيات هذا الطور دعوة المرء الى اخذ نفسه بما يوافق عقيدته وينسجم انسجاما كليا مع التشريعات المنبثقة عن هذه العقيدة .. وهذا يقتضيه النزول عند احكام الاسلام واوامره في كل شؤونه ، وصياغة حياته وفق المنهج الرباني سواء في نطاق العبادة او السلوك او التصرف . ومن مقتضياته كذلك جعل الاسلام المقياس الذي ينبغي الصدور عنه والرجوع اليه في كافة شؤون الحياة .."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0025.png"}, {"n": 26, "paras": ["من التطبيق الى الانتظام", "ثالثا : والطور الثالث الذي ينبغي ان يوجه من رسخت عقيدته وتكامل فهمه وحسن عمله هو طور الانخراط في العمل الحركي للاسلام . والادلة القرانية والنبوية في وجوب العمل الجماعي للاسلام كثيرة وصريحة . ذلك ان الفرد لوحده لا يقوى على النهوض بمسؤولية الدعوة ومتطلباتها ، ومواجهة الواقع الجاهلي وتقويضه ، ومن ثم اقامة المجتمع الاسلامي وايجاد الدولة الاسلامية واستئناف الحياة الاسلامية واستئناف الحياة الاسلامية .. ان كل هذه المقاصد وما تتطلبه من جهود وامكانيات تفرض اشتراكه في تنظيم حركي واندماجه فيه وتلاحمه معه ...", "ومن شرائط هذا التطور تأدية اركان الاسلام وتحري السنة الصحيحة .. والتورع عن الشبهات .. واجتناب المحرمات .. ومراقبة الله عز وجل في كل صغيرة وكبيرة .", "ومن شرائط هذا الطور كذلك قيام المرء بواجب اصلاح اهله وزملائه والمقربين منه .. وعليه ان يدرك ان صلاحه هو لا يعذره عند الله من اصلاح الاخرين .. وان عليه ان يقوم بواجب الامر بالمعروف والنهي عن المنكر ولو كان وحيدا ليس له سند ..", "فالايمان ينبغي ان يدفع المرء لقول كلمة الحق لا يخشى في ذلك لوما ولا إيذاء . وأجدني في غنى عن تقديم شواهد"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0026.png"}, {"n": 27, "paras": ["شرعية على ما اقول لكثرة ما ورد منها في كتاب الله تعالى وسنة رسوله صلى الله عليه وسلم ..", "هذه هي الاطوار الرئيسية التي تؤلف بترابطها وتلاحمها خطا قياسيا يمكن اعتماده او الاستفادة منه في نطاق الدعوة الى الله .", "وبامكان الاخوة جميعا الاستفادة من هذا النهج في تحديد ملامح الطريق التي ينبغي ان يسلكوها اثناء دعوتهم الناس الى الاسلام كفكرة وحركة . والله الهادي الى سواء السبيل « ولان يهدي الله بك رجلا واحدا خير لك من الدنيا وما فيها » (وقل اعملوا فسيرى الله عملكم ورسوله والمؤمنون ثم تردون الى عالم الغيب والشهادة فينبئكم بما كنتم تعملون) .."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0027.png"}, {"n": 28, "paras": ["أسلوب الدعوة ومخاطبة الناس", "ينبغي ان يفهم مما تقدم ان الطريق لدعوة الناس الى الاسلام ، ولفتهم اليه ، واحد لا ثان له وهو طريق الاقناع العقيدي الذي يبدأ باثبات وجود الله وينتهي باثبات ان الاسلام منهج حياة وان العمل لاستئناف الحياة الاسلامية واقامة الحكم الاسلامي واجب على كل مسلم ..", "والمقصود هنا بطريق الدعوة ، المدخل الذي يمكن ان يدخل منه الداعية الى نفس المدعو حتى يتمكن من اقناعه بالفكرة وجذبه الى الحركة ..", "ونحن حيال هذا الموضوع وامثاله ينبغي ان نصدر عن احكام شرعية نعتبرها اساسا لنهجنا وتصرفاتنا ، حتى لا يغدو العمل الاسلامي اعتباطيا عفويا تتحكم فيه العواطف والاهواء والاجتهادات الشخصية ، وتخرجه بالتالي عن الحدود والقيود التي وضعها الشرع صيانة له من العوج والانحراف .", "بديهي جدا ان الناس اليوم بحاجة الى ما يلفتهم الى الاسلام اولا . يشعرهم بوجوده كمنهج حياة ، كامامة ، كقيادة"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0028.png"}, {"n": 29, "paras": ["كريادة وسط التيارات والقوى العالمية المتصارعة . وبديهي كذلك ايضا ان عملية اللفت هذه خطوة تمهيدية تسبق عملية الاقناع بل هي اشبه بخطوة اولية لتحضير عقول الناس ونفوسهم للتلقي والانفعال .", "وهدي الاسلام في هذا الموضوع يظهر بوضوح حين تتبع الاسلوب القرآني والنبوي في دعوة الناس الى الاسلام ..", "فمن الاساليب التي اعتمدها القرآن الكريم مرارا وتكرارا في سبيل لفت المشركين الى آياته البينات - وقد كانوا يضعون اصابعهم في اذانهم لدى سماعها - تصديره فواتح السور بحروف متقطعة كان لها اكبر الاثر في اثارة حفيظة المشركين واستدراجهم للانصات والتلقي .", "ولم تكن الاساليب التي اتبعها الرسول صلى الله عليه عليه وسلم في دعوة الناس الى الاسلام ولفتهم اليه الا تفسيرا عمليا للتوجيه الرباني الكريم بقوله تعالى ( ادع الى سبيل ربك بالحكمة والموعظة الحسنة ) وقوله ( ومن يؤت الحكمة فقد اوتي خيرا كثيرا ) لقد كان من حكمة الرسول صلى الله عليه عليه وسلم اتباع اسلوب الزجر النفسي غير المباشر حين جاءه شاب يطلب منه السماح له بالزنى ( الحادث ثابت في كتب السنة ) .. وكان من حكمته صلى الله عليه وسلم في هداية القلوب ولفتها الى الاسلام ، قوله لمن جاء يسأله على الاسلام وتكاليفه : ( لا تكذب ) .. كما كان من حكمته في مخاطبة الناس على حسب عقولهم ، وبالاقدار التي تؤثر فيهم، قيامه بمعجزة تحريك الشجرة ( التي وردت في كتب السيرة والسنة ) كدليل على صدق نبوته امام اعرابي جاء يسأله معجزة .."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0029.png"}, {"n": 30, "paras": ["ولهذا كان من الحكمة في اسلوب دعوة الناس الى الاسلام ولفتهم اليه مخاطبتهم من حيث يستجيبون ، وبالاسلوب الذي به ينفعلون .. فالناس يتباينون في كل شيء .. يتباينون في ذكائهم وعلمهم ، كما يتباينون في امزجتهم ومشاعرهم . ثم انهم يختلفون في افكارهم وتصوراتهم كما يختلفون في ميولهم واتجاهاتهم . كن هذا مما يفرض على الدعوة وعلى الداعية تخير المدخل الاكثر مناسبة الى نفوسهم ، والاسلوب الاكثر ملاءمة الى عقولهم . ان المفاتيح التي يمكن بها لفت الناس الى الاسلام كمقدمة لاقناعهم به كثيرة ومتعددة ولا يمكن احصاؤها او حصرها . فقد يكون مفتاح ذلك احيانا حلا يقدمه الداعية لمشكلة معيشية او خدمة او قضية يتبناها . وقد يكون المفتاح كذلك موقفا سياسيا تقفه الحركة يلفت الناس الى الاسلام ويرشحه عندهم كاتجاه - على الاقل - يستأهل الدراسة والتفكير . كما يمكن ان يكون مفتاح ذلك - كذلك - زيارة هادفة لصديق ، أو حديثا في مسجد أو حوارا في ندوة ، أو مقالا في كتاب او صحيفة . وهكذا .. تتكاثر الاساليب التي يمكن بها لفت الناس الى الاسلام وتحضير عقولهم ومشاعرهم للتلقي والانفعال . ان الحركة الاسلامية بامكانها ان تلفت الناس الى الاسلام من خلال كل قضية من قضاياهم صغيرة كانت ام كبيرة . وان معالجة قضية - سياسية - معالجة سليمة من وجهة النظر الاسلامية وفي ضوء الاسلام يمكن ان تكشف"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0030.png"}, {"n": 31, "paras": ["للناس خطأ السياسات المعتمدة ولو على الزمن ، وبالتالي توجه أنظار الناس وتحفز انتباههم الى تلقي المزيد من الافكار والمفاهيم والتوجيهات الاسلامية .", "وهكذا يتبين لنا ان بمقدور الحركة ان تستفيد من كل قضية تستأثر باهتمام الناس كسبيل لنقد الاوضاع الجاهلية القائمة ولفت الناس الى الاسلام والى ضرورة ادراك محتواه ودراسة افكاره والتزام مبادئه والى شرف العمل له والجهاد في سبيله ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0031.png"}, {"n": 32, "paras": ["الاتصال الفردي المباشر", "من خلال التجارب الكثيرة التي مرت بها الحركة الاسلامية ، في نطاق الدعوة الى الله والقيام بواجب التوعية والتوجيه في المجتمع ، تأكد للعاملين والدعاة - بما لا يحتمل الشك - جدوى واثر الاتصال الفردي المباشر في كسب عناصر جديدة للحركة ، وفي تزايد الانتاج الحركي لدى كل فرد من افراد التنظيم ..", "مفهوم الاتصال الفردي :", "والمراد بالاتصال الفردي المباشر هو قيام كل فرد من افراد التنظيم بواجب الاحتكاك المقصود الهادف بعناصر جديدة ومحاولة جذبها الى الفكرة اولا ، والى الحركة اخيرا . فالفرد - كل فرد - يعيش بطبيعة الحال في مجتمع تربطه بأفراده اواصر شتى .. فمن رابطة قرابة .. الى رابطة صداقة .. الى زمالة .. الى رابطة مصلحة .. الى ما هنالك من الروابط والعلاقات ..", "وحري بصاحب الفكرة ان يحاول الاستفادة من كافة"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0032.png"}, {"n": 33, "paras": ["العلاقات والظروف لطرح افكاره ومحاولة اقناع الآخرين بها .. وبالتالي الخروج بطبيعة صلاته وعلاقاته من نطاقها ( التجريدي ) العفوي الى النطاق ( الموجه ) الذي يخدم الفكرة الاسلامية ويفتح امامها كثيرا من الابواب والمنطلقات ..", "ان الاخ ينبغي ان تكون حياته كلها بكلياتها وتفصيلاتها صورة معبرة مجسدة للاسلام ، بحيث يتأتى له تهيئة مناخ مناسب له في شتى الظروف والاحوال .. والفرد - كل فرد - له وجود وله اثر .. ووجوده لا يغني عن اثره .. بل ان اثره يدل على قيمة وجوده ... اما الوجود المجرد العفوي فهو مظهر تشترك فيه الحيوانات والجمادات فضلا عن الانسان .. وقيمة الاخ المسلم ليس بوجوده - قطعا - وانما بأثره .. اي بما يحققه هذا الوجود من انتاج واثمار ..", "ومن هنا يترتب على الاخ - وهو صاحب رسالة - ان يعيش رسالته ولرسالته .. وان تكون رسالته محور تفكيره وانشغاله ، وبذلك دون غيره يتحقق المعنى الذي اشارت اليه الآية الكريمة ( قل ان صلاتي ونسكي ومحياي ومماتي لله رب العالمين . لا شريك له وبذلك أمرت ) .", "الاتصال الفردي واجب شرعي :", "وعلى الاخ المسلم ان يدرك تمام الادراك ان مهمة نشر الدعوة ، ونقل المفاهيم الاسلامية الى الناس ومكافحة المنكرات واجب شرعي ، ومسؤولية فردية لا يسقطها عنه انتسابه لجماعة او دورانه في فلكها . ان مسؤولية العمل الاسلامي مترتبة على كل مسلم سواء كانت هناك حركة ام لا .. ومن"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0033.png"}, {"n": 34, "paras": ["هنا كان الهدف من التنظيمات الحركية استيعاب النشاطات الفردية وتنميتها وتوجيهها ، وتحويلها مع الزمن الى طاقة ضخمة يمكن بها مواجهة القضايا الكبرى التي لا طاقة للافراد منعزلين على مواجهتها .", "ان صيغ المخاطبة الفردية التي ورد بها التكليف القرآني والنبوي تؤكد المسؤولية الشخصية في حمل اعباء الدعوة الاسلامية .", "نورد منها على سبيل المثال قوله تعالى : ( ومن احسن قولا من دعا الى الله وعمل صالحا وقال انني من المسلمين ) . ( فلذلك فادع واستقم كما أمرت ولا تتبع أهواءهم ) . ( ادع الى سبيل ربك بالحكمة والموعظة الحسنة ) . ( وادع الى ربك انك لعلى هدى مستقيم ) . وقوله صلى الله عليه وسلم : ( من رأى منكم منكرا فليغيره بيده فان لم يستطع فبلسانه ، فان لم يستطع فبقلبه وذلك اضعف الايمان ) . ( كلكم راع وكلكم مسؤول عن رعيته ) الحديث .", "وقد يفهم كثيرون من العاملين في الحقل الاسلامي خطأ، ان مهمة القيام بأعباء وتكاليف الاتصال الفردي ونشر الدعوة انما تفرض ، على من يريد ان يتصدى لها ، أن يكون على جانب كبير من العلم والمعرفة ، وان هذا يقتضيه التعمق في دراسة علوم القرآن وتفسيره ، وعلوم الحديث ومصطلحه ، وعلوم الشريعة وأصولها وفروعها ، عدا عن الثقافة الاجتماعية والاقتصادية والسياسية ، مما لا يمكن ان يتوفر"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0034.png"}, {"n": 35, "paras": ["الا لقليل من الافراد الذين قد تسمح لهم ظروفهم وامكانياتهم بهذا ..", "وفي اعتقادي ان الامر ابسط من هذا بكثير .. وان الاخ اذا تكاملت جوانب فهمه للاسلام ، وأصبح بمقدوره التعبير بوضوح وبساطة عن هذا الفهم ، بات من واجبه ان يضع قدمه عند اول الطريق وان يباشر مسؤولياته كداعية ، ولكن ضمن ثلاثة شروط :", "١ - ان يعرف حده من العلم والمعرفة فيعمل في نطاقه وعلى مستواه .", "٢ - ان يكون في سلوكه منسجما مع المبادىء التي يدعو الناس اليها .", "٣ - ان يعمل على تنمية ثقافته الاسلامية والبلوغ بها على الزمن المستوى الحسن الذي يمنحه مزيدا من الانطلاق والانفتاح والانتاج .", "فالمهم اذن ان يبدأ .. والبداية ككل بداية .. قد تكون معضلة المعضلات بالنسبة لاي عمل . فاذا ما تجاوز المرء هذه المرحلة تتهاوى على التوالي كل المعوقات ، ويأخذ الانتاج الاسلامي بالتصاعد يوما بعد يوم .", "عقبات في الطريق :", "وانني لا اجد للعقم والجمود والانعزال الذي مني به كثيرون من المنتسبين للتنظيمات الحركية الا سببا واحدا هو: زيادة خوفهم وتهيبهم من الناس والمجتمع ..", "فهؤلاء اما ان يكونوا ضعفاء الثقة بأنفسهم فينبغي ان يعالجوا انفسهم من هذا الجانب .. او انهم يخافون على"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0035.png"}, {"n": 36, "paras": ["حياتهم فيتحاشون تعريضها للإيذاء .. وهؤلاء أقل ما يقال فيهم انهم ضعفاء جبناء ، ويلزمهم معالجة وتطبيب قبل أن يرشحوا لتطبيب الناس ومعالجتهم .. أو انهم أصحاب مصالح يبالغون في المحافظة عليها ولو على حساب الاسلام.", "ان الخوف من الناس لا يمكن ان يكون صفة من صفات المؤمنين . لان الايمان بطبيعته يكسب الانسان الجرأة في الحق والشجاعة فيه . يؤكد ذلك قوله تعالى : ( الذين قال لهم الناس ان الناس قد جمعوا لكم فاخشوهم فزادهم ايمانا وقالوا حسبنا الله ونعم الوكيل فانقلبوا بنعمة من الله وفضل لم يمسسهم سوء ) .", "والى هذا المعنى يشير الرسول صلى الله عليه وسلم بقوله : ( امرت ان اقول الحق ولو كان مرا ) وقوله : ( امرت ان اقول الحق ولا اخشى في الله لومة لائم ) .. وان الفرار من المعركة صفة المتشككين المترددين الغافلين عن قوله تعالى : ( قل لن يصيبنا الا ما كتب الله لنا هو مولانا وعلى الله فليتوكل المؤمنون ) والذين يظنون انهم مانعتهم حصونهم من الله ومن قدره ونسوا قول الله تعالى ( اينما تكونوا يدرككم الموت ولو كنتم في بروج مشيدة ) .. الى هؤلاء وامثالهم يشير القرآن الكريم بقوله : ( الذين قالوا لاخوانهم وقعدوا ، لو أطاعونا ما قتلوا . قل فادرءوا عن انفسكم الموت ان كنتم صادقين ) وقوله : ( قل ان الموت الذي تفرون منه فانه ملاقيكم ثم تردون الى عالم الغيب والشهادة فينبئكم بما كنتم تعملون ) .", "واما الذين يخافون من العمل الاسلامي على مصالحهم وارزاقهم وقواتهم ويحسبون لذلك الف حساب ، فهؤلاء لا"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0036.png"}, {"n": 37, "paras": ["يمكن الا ان يكونوا عبيدا للارض وحطامها ، وحري بهم ان يتحرروا من كل ما يعيق انطلاقهم ويكبل حركتهم .. فالاخ وان كان مفروضا عليه ان يعمل ويكسب وان لا ينسى نصيبه من الدنيا عملا بقوله تعالى : ( وابتغ فيما آتاك الله الدار الآخرة ولا تنس نصيبك من الدنيا وأحسن كما أحسن الله إليك ) الا ان عليه ان يجعلها في جيبه لا في قلبه وان يسخرها للخير دون ان تسخره للشر ، وان لا يكون اقباله عليها عاملا في ادباره عن الجهاد في سبيل الله ..", "من حسنات الاتصال الفردي : للاتصال الفردي المباشر حسنات كثيرة لا مجال لحصرها .. ولكن يكتفى هنا بالاشارة الى ان الاحتكاك الفردي ، يتيح للدعاة التعرف على العناصر المراد جذبها الى الدعوة وتبليغها الفكرة عن كثب . كما يمكنهم الاحتكاك من الوقوف على اوضاع هؤلاء ومشاكلهم ، ويسهل عليهم بالتالي عملية التشخيص والتوجيه والمعالجة . بينما لا يتحقق في مجالات الاتصال الجماعي فوائد التأثير المباشر الذي يلامس العلة ذاتها ويعالج الداء نفسه .", "ومن حسنات الاتصال الفردي كذلك انه يضع الاخوان جميعا وبدون استثناء امام مسؤولياتهم وواجباتهم . وبهذا لا يبقى العمل الاسلامي محصورا في عدد من الافراد الذين يمارسون مهام التوجيه والارشاد . وانما يفرض على كل فرد من افراد التنظيم ان يؤدي دوره الانتاجي في حدود ما تسمح به امكانياته وقدراته وطاقاته ..", "وهذا من شأنه ان يحول الجماعة الى خلية عمل ، الكل فيها يعمل وينتج : ولا مجال فيها للبطالة والكسل .."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0037.png"}, {"n": 38, "paras": ["ومن محاسن الاتصال الفردي ايضا انه يجنب الحركة كثيرا من مواقف الاحراج التي تفرضها احيانا الظروف السياسية . ويعين الدعاة على مواجهة كافة الاسئلة المطروحة بالنقاش الموضوعي وبالتبسيط والتفصيل ، مما لا تتيحه اجواء الاتصال العام كأجواء الاحتفالات والمهرجانات والمحاضرات .", "وبهذا يكون الاتصال الفردي الوسيلة المثمرة المنتجة التي تؤتي اكلها من غير ضجيج او ضوضاء ، وتبلغ بالحركة الغاية المنشودة منها بأيسر التكاليف واقصر الاوقات ..", "وأخيرا فليضع الدعاة أمام أعينهم باستمرار قول الرسول صلى الله عليه وسلم : ( لان يهدي الله بك رجلا واحدا خير لك من الدنيا وما فيها ) ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0038.png"}, {"n": 39, "paras": ["فصل في بيان أنَّه لا يصحُّ أن يكونَ في الوجودِ إلَّا واجبُ الوجودِ لذاتِه، وأنَّه لا شريكَ له في وجوبِ الوجودِ، ولا في غيرِه من صفاتِ الكمالِ.", "اعلمْ أنَّه قد ثبتَ بالبراهينِ القاطعةِ، والأدلَّةِ الساطعةِ، أنَّ واجبَ الوجودِ لذاتِه واحدٌ لا شريكَ له، ولا نظيرَ له، ولا ضدَّ له، ولا ندَّ له، ولا صاحبةَ له، ولا ولدَ له، ولا وزيرَ له، ولا مشيرَ له، ولا معينَ له، ولا ظهيرَ له، ولا شبيهَ له، ولا مثيلَ له، ولا كفؤَ له، ولا شريكَ له في ملكِه، ولا في خلقِه، ولا في أمرِه، ولا في تدبيرِه، ولا في شيءٍ من صفاتِ كمالِه، ولا في شيءٍ من أفعالِه، ولا في شيءٍ من أسمائِه، ولا في شيءٍ من نُعوتِ جلالِه، ولا في شيءٍ من آثارِ عظمتِه، ولا في شيءٍ من مقتضياتِ ربوبيتِه، ولا في شيءٍ من لوازمِ ألوهيتِه، ولا في شيءٍ من متعلقاتِ قدرته، ولا في شيءٍ من متعلقاتِ إرادتِه، ولا في شيءٍ من متعلقاتِ علمِه، ولا في شيءٍ من متعلقاتِ سمعِه، ولا في شيءٍ من متعلقاتِ بصرِه، ولا في شيءٍ من متعلقاتِ كلامِه، ولا في شيءٍ من متعلقاتِ حياتِه، ولا في شيءٍ من متعلقاتِ قيوميتِه، ولا في شيءٍ من متعلقاتِ عِزَّتِه، ولا في شيءٍ من متعلقاتِ حِكمتِه، ولا في شيءٍ من متعلقاتِ رحمتِه، ولا في شيءٍ من متعلقاتِ نِعمتِه، ولا في شيءٍ من متعلقاتِ إحسانِه، ولا في شيءٍ من متعلقاتِ فضلِه، ولا في شيءٍ من متعلقاتِ جودِه، ولا في شيءٍ من متعلقاتِ كرمِه، ولا في شيءٍ من متعلقاتِ عفوِه، ولا في شيءٍ من متعلقاتِ غفرانِه، ولا في شيءٍ من متعلقاتِ حِلمِه، ولا في شيءٍ من متعلقاتِ رِفقِه، ولا في شيءٍ من متعلقاتِ لُطفِه، ولا في شيءٍ من متعلقاتِ برِّه، ولا في شيءٍ من متعلقاتِ إكرامِه، ولا في شيءٍ من متعلقاتِ إعزازِه، ولا في شيءٍ من متعلقاتِ إذلالِه، ولا في شيءٍ من متعلقاتِ قبضِه، ولا في شيءٍ من متعلقاتِ بسطِه، ولا في شيءٍ من متعلقاتِ خفضِه، ولا في شيءٍ من متعلقاتِ رفعِه، ولا في شيءٍ من متعلقاتِ", "إعطائِه، ولا في شيءٍ من متعلقاتِ منعِه، ولا في شيءٍ من متعلقاتِ إحيائِه، ولا في شيءٍ من متعلقاتِ إماتتِه، ولا في شيءٍ من متعلقاتِ تقديمِه، ولا في شيءٍ من متعلقاتِ تأخيرِه، ولا في شيءٍ من متعلقاتِ أوليَّتِه، ولا في شيءٍ من متعلقاتِ آخريتِه، ولا في شيءٍ من متعلقاتِ ظاهريتِه، ولا في شيءٍ من متعلقاتِ باطنيتِه، ولا في شيءٍ من متعلقاتِ قُربِه، ولا في شيءٍ من متعلقاتِ مَعِيَّتِه، ولا في شيءٍ من متعلقاتِ استوائِه، ولا في شيءٍ من متعلقاتِ نُزولِه، ولا في شيءٍ من متعلقاتِ مجيئِه، ولا في شيءٍ من متعلقاتِ إتيانِه، ولا في شيءٍ من متعلقاتِ رضاه، ولا في شيءٍ من متعلقاتِ سخطِه، ولا في شيءٍ من متعلقاتِ غضبِه، ولا في شيءٍ من متعلقاتِ مقتِه، ولا في شيءٍ من متعلقاتِ حبِّه، ولا في شيءٍ من متعلقاتِ بغضِه، ولا في شيءٍ من متعلقاتِ كراهتِه، ولا في شيءٍ من متعلقاتِ إرادتِه، ولا في شيءٍ من متعلقاتِ مشيئتِه، ولا في شيءٍ من متعلقاتِ أمرِه، ولا في شيءٍ من متعلقاتِ نهيِه، ولا في شيءٍ من متعلقاتِ وعدِه، ولا في شيءٍ من متعلقاتِ وعيدِه، ولا في شيءٍ من متعلقاتِ خبرِه، ولا في شيءٍ من متعلقاتِ حكمِه، ولا في شيءٍ من متعلقاتِ قضاءِه، ولا في شيءٍ من متعلقاتِ قدرِه، ولا في شيءٍ من متعلقاتِ خلقِه، ولا في شيءٍ من متعلقاتِ رزقِه، ولا في شيءٍ من متعلقاتِ هدايتِه، ولا في شيءٍ من متعلقاتِ إضلالِه، ولا في شيءٍ من متعلقاتِ توفيقِه، ولا في شيءٍ من متعلقاتِ خذلانِه، ولا في شيءٍ من متعلقاتِ عصمتِه، ولا في شيءٍ من متعلقاتِ خِذلانِه، ولا في شيءٍ من متعلقاتِ تأييدِه، ولا في شيءٍ من متعلقاتِ نصرِه، ولا في شيءٍ من متعلقاتِ إعانتِه، ولا في شيءٍ من متعلقاتِ كفايتِه، ولا في شيءٍ من متعلقاتِ وقايتِه، ولا في شيءٍ من متعلقاتِ حِفظِه،", "ولا في شيءٍ من متعلقاتِ رِعايتِه، ولا في شيءٍ من متعلقاتِ ولايتِه، ولا في شيءٍ من متعلقاتِ مَحبَّتِه، ولا في شيءٍ من متعلقاتِ قُربِه، ولا في شيءٍ من متعلقاتِ مَعِيَّتِه، ولا في شيءٍ من متعلقاتِ استوائِه، ولا في شيءٍ من متعلقاتِ نُزولِه، ولا في شيءٍ من متعلقاتِ مجيئِه، ولا في شيءٍ من متعلقاتِ إتيانِه، ولا في شيءٍ من متعلقاتِ رضاه، ولا في شيءٍ من متعلقاتِ سخطِه، ولا في شيءٍ من متعلقاتِ غضبِه، ولا في شيءٍ من متعلقاتِ مقتِه، ولا في شيءٍ من متعلقاتِ حبِّه، ولا في شيءٍ من متعلقاتِ بغضِه، ولا في شيءٍ من متعلقاتِ كراهتِه، ولا في شيءٍ من متعلقاتِ إرادتِه، ولا في شيءٍ من متعلقاتِ مشيئتِه، ولا في شيءٍ من متعلقاتِ أمرِه، ولا في شيءٍ من متعلقاتِ نهيِه، ولا في شيءٍ من متعلقاتِ وعدِه، ولا في شيءٍ من متعلقاتِ وعيدِه، ولا في شيءٍ من متعلقاتِ خبرِه، ولا في شيءٍ من متعلقاتِ حكمِه، ولا في شيءٍ من متعلقاتِ قضاءِه، ولا في شيءٍ من متعلقاتِ قدرِه، ولا في شيءٍ من متعلقاتِ خلقِه، ولا في شيءٍ من متعلقاتِ رزقِه، ولا في شيءٍ من متعلقاتِ هدايتِه، ولا في شيءٍ من متعلقاتِ إضلالِه، ولا في شيءٍ من متعلقاتِ توفيقِه، ولا في شيءٍ من متعلقاتِ خذلانِه، ولا في شيءٍ من متعلقاتِ عصمتِه، ولا في شيءٍ من متعلقاتِ خِذلانِه، ولا في شيءٍ من متعلقاتِ تأييدِه، ولا في شيءٍ من متعلقاتِ نصرِه، ولا في شيءٍ من متعلقاتِ إعانتِه، ولا في شيءٍ من متعلقاتِ كفايتِه، ولا في شيءٍ من متعلقاتِ وقايتِه، ولا في شيءٍ من متعلقاتِ حِفظِه، ولا في شيءٍ من متعلقاتِ رِعايتِه، ولا في شيءٍ من متعلقاتِ ولايتِه، ولا في شيءٍ من متعلقاتِ مَحبَّتِه."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0039.png"}, {"n": 40, "paras": ["من عوامل النجاح", "هنالك عوامل عدة تساعد على نجاح الداعية الى حد بعيد في مجالات الدعوة ، وتحقق له الخصب والاثمار ، وتمنحه القدرة على التأثير والتفاعل والايغال بمبادئه وافكاره في كل وسط وعلى كل صعيد .", "والاسلوب الحسن .. هو احد العوامل الحساسة الهامه التي توفر على الداعية الوقت والجهد ، وتصل به الى الغاية والمطلوب بأقل التكاليف وايسرها ..", "فالداعية في كل مجال من مجالات الدعوة والتبليغ .. في الكتابة .. والخطابة والتحدث .. والنقاش .. في العمل الشعبي والنقابي .. والسياسي .. والطلابي؛ بحاجة الى الاسلوب الحسن الذي يصيب الهدف ويبلغ القصد .", "وقد يكون من أبرز الامور التي ينبغي توفرها للداعية ليتمتع بالاسلوب الحسن في مجالات دعوته ، تعرفه على الوسط الذي سيكون ميدانا لنشاطه وعمله .. يدرس اوضاعه ومشكلاته واتجاهاته وميوله ورغباته .. كالطبيب يرقب عوارض المرض وتطوره ومراحله ، ثم يشخص اسبابه"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0040.png"}, {"n": 41, "paras": ["وبواعثه .. على علم ومعرفة .. علم بخصائص الداء ومعرفة بأسباب الشفاء ..", "والداعية الناضج كالطبيب الناجح يعرف من اين يبدأ وكيف يبدأ .. ثم لا يبدأ قبل ان تتوفر لديه امكانية التمحيص والتشخيص والمعالجة ، حتى لا يكون عمله سلسلة من تجارب فاشلة واعمال مرتجلة ..", "والمجتمع اليوم يموج بعديد المذاهب والاتجاهات .. وكلها تتجاذب الناس بما تطلع عليهم من دعايات منمقة ، واساليب مزوقة ..", "تخاطبهم من حيث يصغون ويسمعون .. وتأتيهم من حيث يحسون ويشعرون .. تلامس جروحاتهم ، وتتحسس امراضهم ، وتتلمس مشكلاتهم ..", "ودعاة الاسلام .. يجب ان لا يكونوا اقل عناية واهتماما بأساليب دعوتهم من سواهم .. فلا يخاطبون العمال الكادحين بلغة « القبوريين » ولا يناقشون الملاحدة الماديين بلسان « العاطفيين » وانما يجعلون لكل مقام مقالا .. يحدوهم لذلك قول الرسول الاعظم صلى الله عليه وسلم : ( خاطبوا الناس على قدر عقولهم ) .", "ان الاسلام في هذا الزمن بحاجة الى دعاة يحسنون عرض افكاره ومبادئه بأسلوب شيق جذاب .. يؤثرون ولا ينفرون ، ويوضحون ولا يعقدون ويحسنون فلا يسيئون .. وكم من ادعياء شوهوا الاسلام بسوء دعوتهم له ، واساؤوا اليه وهم يحسبون انهم يحسنون صنعا ..", "ومن هنا كانت وظيفة الدعاة خطيرة ومسؤوليتهم .."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0041.png"}, {"n": 42, "paras": ["كبيرة .. ولهذا وجب أن تتوافر عناصر الواقعية والايجابية والاتزان في أساليب الدعاة .", "بين الشدة واللين", "فالنفوس جبلت على حب من احسن اليها . وقد تدفعها القسوة والشدة احيانا الى المكابرة والاصرار والنفور فتأخذها العزة بالاثم .. وليس من معنى اللين المداهنة والرياء والنفاق ، وانما بذل النصح واسداء المعروف بأسلوب دمث مؤثر ، يفتح القلوب ويشرح الصدور ، خاصة اذا كانت الدعوة لجماعة المسلمين انه لا ينبغي بحال مجاهرتهم بالتوبيخ والتقريع الشديدين ..", "الا ترى الى القرآن الكريم في معرض التوجيه الرباني يخاطب « موسى وهارون » ويوصيهما بمبادأة الطاغية فرعون باللين والحسنى : ( اذهبا الى فرعون انه طغى ، فقولا له قولا لينا لعله يتذكر أو يخشى ) بل ان اللفتات القرآنية والاشارات النبوية الى الرفق ومجانبة الغلظة والقسوة تؤكد بما لا يحتمل الشك فاعلية هذا الاسلوب وقيمته التوجيهية .", "ويقول الله تعالى في اخر سورة النحل آمرا نبيه بالتزام الحكمة في دعوة الناس ( ادع الى سبيل ربك بالحكمة والموعظة الحسنة ، وجادلهم بالتي هي احسن ، ان ربك هو اعلم بمن ضل عن سبيله وهو أعلم بالمهتدين ) وفسرها ابن كثير بقوله : أي من احتاج الى مناظرة وجدال فليكن بالوجه الحسن برفق ولين وحسن خطاب .", "وفي سورة ال عمران يشير القرآن الكريم الى فوائد الرفق واللين في كسب الانصار والمؤيدين ، وانطلاق"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0042.png"}, {"n": 43, "paras": ["الدعوة والتفاف القلوب حولها : ( فبما رحمة من الله لنت لهم ، ولو كنت فظا غليظ القلب لانفضوا من حولك ) . وقد ورد في تفسير هذه الآية قول لعبد الله بن عمر جاء فيه: اني ارى صفة الرسول صلى الله عليه وسلم في الكتب المتقدمة انه ليس بفظ ، ولا غليظ ، ولا صخاب في الاسواق، ولا يجزي بالسيئة السيئة ، ولكن يعفو ويصفح .", "وفي السيرة النبوية نماذج عملية ووقائع تفسيرية للاسلوب الاخاذ النافذ الذي كان يبلغ به رسول الله صلى الله عليه وسلم دعوته الى الناس بلباقة ، فقد روي أبو امامة : « ان غلاما شابا اتى النبي صلى الله عليه وسلم فقال : يا نبي الله .. أتأذن لي في الزنا ؟ فصاح الناس به .. فقال النبي صلى الله عليه وسلم قربوه ، ادن .. فدنا حتى جلس بين يديه . فقال النبي : اتحبه لامك ؟ قال : لا جعلني الله فداك . قال كذلك الناس لا يحبونه لامهاتهم . اتحبه لابنتك ؟ قال : لا جعلني الله فداك . قال كذلك الناس لا يحبونه لبناتهم . اتحبه لاختك ؟ وزاد ابن عوف انه ذكر العمة والخالة وهو يقول في كل واحدة : لا جعلني الله فداك . فوضع رسول الله صلى الله عليه وسلم يده على صدره وقال : اللهم طهر قلبه ، واغفر ذنبه ، وحصن فرجه . فلم يكن شيء ابغض اليه منه ، يعني الزنا » (١) .", "واسلوب الدعوة ينبغي ان يكون متجددا متطورا في حدود ما يسمح به الاسلام .. ومرونة الاسلام تقتضي العمل على مستوى العصر ، وبمختلف الوسائل المشروعة ، التي تضمن نقل الاسلام الى الناس منهج عيش ورسالة حياة ، في اجمل صورة وعلى احسن وجه ..", "(١) رواه احمد باسناد جيد ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0043.png"}, {"n": 44, "paras": ["وهذا منطق المرونة في قول الرسول صلى الله عليه وسلم : ( الحكمة ضالة المؤمن انى وجدها فهو احق الناس بها ) وقوله : ( خذوا الحكمة من اي وعاء خرجت ) ..", "ماذا تريد ؟", "وقد يكون من خير ما يحقق الاسلوب الحسن لدى الداعية ادراكه الواضح لما يريد .. فتقييم التصور والتشخيص الواضحين للغايات والاهداف يملي على الداعية الاسلوب الذي ينبغي التزامه وتبنيه ..", "وادراك الداعية لما يريد يوفر عليه الوقت والجهد ، ويجعل سيره وانطلاقة على بصيرة ونور .. فلا يخبط خبط عشواء ، او يدخل البيوت من غير ابوابها ، دونما تقدير للعواقب او تحسب للنتائج ؟ والى هذا يشير التوجيه الرباني الكريم في قوله تعالى : ( يا ايها الذين امنوا اتقوا الله وقولوا قولا سديدا يصلح لكم اعمالكم ويغفر لكم ذنوبكم ومن يطع الله ورسوله فقد فاز فوزا عظيما ) .", "ان مسالك الدعوة يسيرة وعسيرة .. يسيرة على من عرف حدودها وابعادها ، والتزم اصولها وقواعدها .. وعسيرة على من تفرقت به سبل الاجتهاد ، ولم يحالفه التوفيق . وصدق من قال : اذا لم يكن من الله عون للفتى فأول ما يقضي عليه اجتهاده", "فالداعية عليه ان يعرف ماذا يريد من كل خطوة"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0044.png"}, {"n": 45, "paras": ["يخطوها ، ان خطب وكتب ، ان ناقش وتحدث ، ان سالم وخاصم .. وصدق الحسن البصري حيث يقول : ( العامل على غير علم ، كالسائر على غير طريق ، والعامل على غير ما يريد يفسد اكثر مما يصلح ) وفي الحكم ( من سلك طريقا بغير دليل ضل ، ومن تمسك بغير اصل ذل ) ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0045.png"}, {"n": 46, "paras": ["كتب مقترحة للمطالعة حول موضوع ( الدعوة الى الاسلام )", "- تذكرة الدعاة تأليف : الاستاذ البهي الخولي", "- تذكرة دعاة الاسلام تأليف : الاستاذ المودودي", "- كيف ندعو الناس تأليف : الاستاذ عبد البديع صقر", "- رجال الفكر والدعوة في الاسلام تأليف : السيد ابي الحسن الندوي", "- مذكرات الدعوة والداعية تأليف : الشهيد حسن البنا", "- مجموعة رسائل البنا"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0046.png"}, {"n": 47, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0047.png"}, {"n": 48, "paras": ["المبحث الثالث في الموضوعات التي يحسن طرحها", "• نقد الواقع القائم", "• نقد الاتجاهات المعاصرة = الرأسمالية = الشيوعية", "• اثبات الحاجة الى الاسلام", "• اثبات ان الاسلام منهج حياة", "• مصادر المنهج الاسلامي = القرآن = السنة = مصادر اخرى", "• خصائص المنهج الاسلامي = ربانيته = شموله = انقلابيته = استمراريته = عالميته", "• الخطوط الكبرى للمنهج الاسلامي في العقيدة : = الايمان بالله == الايمان باليوم الآخر = القضاء والقدر في الشريعة: = في النظام العبادي = في النظام الاجتماعي = في النظام الاقتصادي = في النظام السياسي"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0048.png"}, {"n": 49, "paras": ["هذا الكتاب هو الجزء الثاني من كتاب «المدخل إلى علم التفسير» للشيخ الدكتور محمد بن محمد أبو شهبة، وهو يشتمل على مباحث هامة في علوم القرآن الكريم، وقد اعتمدت فيه على أمهات المصادر والمراجع في هذا الفن، مع تحري الدقة في النقل والتحقيق، والرجوع إلى أقوال المفسرين والعلماء، ومناقشتها بما يقتضيه المقام من البحث العلمي الرصين.", "وقد رتبت هذا الجزء على أبواب وفصول، تناولت فيها:", "١. أسباب النزول، وأهميتها، وطرق معرفتها، والضوابط التي وضعها العلماء في قبولها أو ردها.", "٢. المكي والمدني، وضوابط معرفتهما، وفوائد ذلك في التفسير.", "٣. الناسخ والمنسوخ، وحقيقته، وأقسامه، وشروطه، والرد على من أنكر وقوعه في القرآن.", "٤. القراءات القرآنية، وأثرها في التفسير، وتوجيهها، والرد على الشبهات التي أثيرت حولها.", "٥. الإعجاز القرآني، وأوجهه، والرد على منكري الإعجاز.", "وقد حاولت في هذا الكتاب أن أجمع بين الأصالة والمعاصرة، وأن أقدم للقارئ مادة علمية ميسرة، بعيدة عن التعقيد، مع التزام المنهج العلمي في العرض والتحليل، سائلاً المولى عز وجل أن ينفع به، وأن يجعله خالصاً لوجهه الكريم."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0049.png"}, {"n": 50, "paras": ["(۱) نَقْدُ الواقعِ القَائِمِ وَإثباتُ الحَاجَةِ إلى الإسْلَامِ", "يحسن بالاخ الداعية ان يطرح - في اوائل اجتماعاته بالعناصر الجديدة المراد دعوتها الى الاسلام - موضوع نقد الاوضاع الشاذة التي تعيشها الامة .. وان يوضح ما استطاع بالموضوعية والرقمية والمنطق في نقده هذا .. وبقدر ما يتمكن من ملامسة العلل والامراض وابراز اسبابها ومسبباتها وبيان اثارها ونتائجها ، بقدر ما يكون تأثيره عميقا واثره كبيرا على الحاضرين .", "وأرى ان يتولى الداعية معالجة هذا الموضوع من خلال النقاط التالية :", "* فساد العقيدة : لقد كانت الكارثة الاولى التي اصيبت بها الامة هي فساد عقيدتها واصابتها بلوثات مادية جانحة زرعت الشك والالحاد في نفوس ابنائها ، وعملت مع الايام على اشاعة المفاهيم والاراء اللادينية ، مما عرض روح التدين لهزات"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0050.png"}, {"n": 51, "paras": ["عنيفة ومخيفة مهدت بعدئذ لظهور الاتجاهات الالحادية وتسلطها على بلاد المسلمين ومقدراتها ، ومن ثم محاربتها للاسلام ودعاته ، تارة باطلاق الشائعات والاراجيف ، وطورا باختلاق الذرائع والمبررات لاستئصالهم والخلاص منهم ..", "* انحراف الاخلاق : ولقد كان من نتائج فساد العقيدة الذي أصيبت به الامة انهيار اخلاقها وشيوع الفواحش والمنكرات فيها . والشواهد التاريخية تؤكد بما لا يحتمل الشك ان من اسباب تداعي الامم وزوالها هو انغماسها في حمأة الرذائل والشهوات وانصرافها الى المتع والملذات ( وما تشيع الفاحشة في قوم قط الا عمهم الله بالبلاء ) .", "التجارب الفاشلة : ولقد شهدت هذه الامة خلال ربع القرن الماضي محاولات متلاحقة من التجارب الفاشلة على كل صعيد .. فعلى الصعيد « السياسي » فشلت الاتجاهات القومية في اقامة اي شكل من اشكال الوحدة او الاتحاد حتى بين قطرين عربيين اثنين . وعلى الصعيد « الاقتصادي » اخفقت النظريات المستوردة - رأسمالية واشتراكية - في ايجاد مجتمع الكفاية والعدل . بل ان هذه النظريات اصابت من الاقتصاد « القومي » مقتلا مما ادى الى تدمير الحياة التجارية والمالية في اكثر من قطر . وأما على الصعيد العسكري فان الهزائم المتلاحقة التي"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0051.png"}, {"n": 52, "paras": ["منيت بها الامة تؤكد بما لا يقبل الشك عجز الانظمة القائمة - كل الانظمة - عن تحضير الامة نفسيا وحسيا لمواجهة التحديات الاستعمارية وخوض معارك التحرير .", "حالة الضياع التي تعيشها الامة :", "وهكذا اصبحت الامة في حالة ضياع وضياع كامل .. الاوضاع التي تعيشها في غاية الشذوذ والانحراف .. والنكبات والكوارث تنزل بساحتها من كل جانب ..", "ولم تكن الامة لتصل الى ما وصلت اليه عبثا .. بل كان ذلك حصاد ادبارها عن الله ، وتمردها على حاكميته وتنكرها لمنهجه في الحياة ، وبالتالي عودتها الى الجاهلية الاولى من جديد ..", "اذا عرف السبب بطل العجب :", "والحقيقة ان هذه الردة التي اصابت المسلمين كانت نتيجة طبيعية للمؤامرات التي تكاتفت فيها على هذه الامة معاول الهدم من كل مكان .. فمن حركات شعوبية الى اتجاهات مادية الى مخططات صهيونية الى جمعيات ماسونية الى أقلام استخبارات اجنبية ، والى ما لدى هذه الجهات والاتجاهات من امكانيات مادية ووسائل اعلام .. ولقد عانت الامة من جراء هذا وكابدت الامرين ..", "ورأت برهان ذلك في كل شأن من شؤون حياتها .. فحياتها الاجتماعية تعفنت من كثرة ما عمها من فواحش وموبقات .. وحياتها الاقتصادية أجدبت بسبب فشل النظم الوضعية الحاكمة وعجزها عن تحقيق العدالة والرفاه .."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0052.png"}, {"n": 53, "paras": ["ولقد رأت برهان ذلك - كذلك - في ضعفها وتفرق كلمتها ، وانقسامها ثم انهزامها في معارك متلاحقة مع دولة مسخ وعصبة من شذاذ الافاق ..", "سبيل النجاة :", "واخيرا .. وبعد ان افلست الاتجاهات المادية والمذاهب الوضعية لم يبق سوى الاسلام سبيلا لانقاذ الامة من كل مظاهر التناقض والانحراف التي تجتاحها ..", "فالاسلام هو المنهج الوحيد المؤهل لمواجهة تحديات الحضارة المادية ، وهو الاتجاه الوحيد المؤهل لقيادة هذه الامة بل وترشيحها لريادة البشرية ..", "ان المادة الطاغية التي داست في طريقها كل المثل وكل القيم ، والتي زرعت القلق والاضطراب والانحراف والشذوذ في شتى انحاء المعمورة ، لا يقوى على مواجهتها ودحرها واستئصالها .. سوى منطق الفطرة ، اذ هو اقوى منها واقدر على اسعاد الانسان وتوفير الطمأنينة له ..", "وان الامة وقد استنزفت في دوامة تجاربها الفاشلة عزيز طاقاتها ، وبعد ان وصلت الى ما وصلت اليه من بؤس وشقاء ، بسبب اعراضها عن صوت الفطرة .. مدعوة من جديد للافصاح عن شخصيتها « الاصلية » مدعوة لتطل على العالم برسالة الانقاذ والخلاص .. مدعوة لتحقيق « ذاتها الاسلامية » ، في معركة تحقيق الذات .", "وهنا يحسن بالداعية نقد المذهبين العالميين الشيوعية والرأسمالية ، بمنطق وموضوعية .."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0053.png"}, {"n": 54, "paras": ["(٢) نقد النظام الشيوعي", "نشأة الشيوعية :", "الشيوعية اشد انواع الاشتراكية عنفا ، وقد أنشأها ( كارل ماركس ) اليهودي الذي ولد في المانيا عام ١٨١٨ ومات في انكلترا عام ١٨٨٣ . اعلن ماركس عن آرائه الشيوعية عام ١٨٤٧ وكان واثقا من انهيار النظام الرأسمالي ، وان الهوة سوف تتسع بين العمال واصحاب العمل ، وأن نتيجة ذلك ستكون قيام ( دكتاتورية الفقراء ) .. وقد أعلن ماركس عن آرائه هذه في وثيقة معروفة باسم ( مانيفتو الشيوعية ) . ان المتتبع لحياة ماركس الخاصة يستطيع أن يتبين بوضوح العوامل التي جعلته لا ينتج غير ( الشيوعية ) مبدأ للحياة ؟؟ فالعامل الاول هو فشله في شؤون حياته الخاصة العاطفية ففي عام ١٨٣٦ عقد خطوبته سرا على فتاة من اسرة ارستقراطية وعندما انكشف الامر للاسرة عارضت مشروع"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0054.png"}, {"n": 55, "paras": ["الزواج هذا لاعتبارات ( طبقية ) فكانت هذه اولى الصدمات النفسية في حياته بل هي أول العوامل التي اذكت في نفسه بواعث الحقد على المجتمع الارستقراطي البورجوازي ؟", "وفي عام ١٨٣٥ خاض ماركس مبارزة بالسيف في ( نادي الشعراء ) ببون ضد أحد اعضاء النادي البورجوازيين، فتفوق عليه خصمه واصابه بجرح حاجبه .. ويبدو أن الطعنة التي وجهها اليه ذلك البورجوازي لم تترك أثرا في الحاجب فحسب ، وانما في أعماق عقله الباطن ؟", "ثم ان العوز والفاقة ، وضيق ذات اليد التي كانت عليها اسرة ماركس ، خلقت لديه نقمة عارمة على الاغنياء ، والمتمولين وجعلته يردد دائما مقطوعة لشكسبير يقول فيها : ( أيها الذهب .. أيها الذهب الثمين البراق .. انك تصير الابيض أسودا ، والقبيح جميلا ، والشر خيرا ، والعجوز فتيا ، والجبان باسلا هذه العبودية الحمراء القانية هي التي تعقد الروابط المقدسة وهي تحلها : )", "ان هذه العوامل جميعها تمكنت أن تفعل في ماركس فعلها البالغ يحركها العامل الاكبر ( يهوديته ) لينتج الشيوعية أو الماركسية (١)", "يضاف الى ما تقدم أن الشيوعية كانت ردة فعل لطغيان الاقطاع وتسلطه ، وللاوضاع الشاذة التي كانت تعيشها ، أوربا بوجه عام .. لقد عانى الفلاحون في ذلك الجزء من العالم خلال القرون ، السابع عشر والثامن عشر والتاسع عشر من ألوان العذاب ما جعلهم يفرون الى مجاهل أوربا والى غابات سيبيريا .", "(١) راجع كتاب ماركس والخلق لطلال جرجس ص ٢٧ - ٣٦ ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0055.png"}, {"n": 56, "paras": ["كذلك كانت الشيوعية ردة فعل لانحراف الكنيسة عن خطها الاصيل ، ووقوفها الى جانب الحكم ( التيوقراطي ) (١) وتدعيمها لسلطان الطغاة والحكام ودورانها في فلكهم ؟؟ مما حمل ماركس على الكفر بكل ما يتصل بالفكرة الدينية والاديان كما سيأتي معنا ..", "وهكذا أدت العوامل الخاصة في حياة ماركس ، بالاضافة الى العوامل العامة التي كان عليها المجتمع الى ولادة الشيوعية ، التي نعتبرها ردة فعل منحرفة ، لاوضاع منحرفة، وليست علاجا نافعا لانحراف تلك الاوضاع (٢) .", "النظرية الماركسية :", "تقوم النظرية الماركسية على مبدئين أساسيين هما المادية المنطقية والمادة الدياليتيكية اي على التفسير المادي للتاريخ . ولهذا سميت بالمادية التاريخية ، ذلك أنها تنظر الى المادة على انها أساس كل أمر في الحياة ، وأن البشرية مسيرة في مختلف اطوارها بتأثير المادة فقط ..", "المادة المنطقية :", "المادية المنطقية تعني أن الحياة كلها مادة ، وانها أي المادة في حركة دائمة وتطور مستمر .. وهذا بالتالي يعني رفض كل", "(١) الحكم الديني الذي يقوم على الاعتقاد بأن الله قد اختار الملوك مباشرة لحكم الشعب .", "(٢) نشبت الثورة الشيوعية في روسيا عام ١٩١٧ وبعدها تألفت الحكومة برئاسة نيقولاي لينين وأطلقت على القرارات واللوائح والسياسات التي وضعها موضع التنفيذ اسم اللينينية التي قامت على أصول كارل ماركس. ومات لينين ١٩٢٧م ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0056.png"}, {"n": 57, "paras": ["العوامل الغيبية التي تؤمن بها الاديان واعتبار المادة الفاعل المتحرك الوحيد في هذه الحياة ..", "ان هذه النظرية ( التخريفية ) مرفوضة بداهة لاعتبار أن المادة الصماء لا يمكن أن تتحول ذاتيا ، وأنه لا بد لها من محول أو عامل خارجي عنها مؤثر فيها .. فكما أن الجبال والصخور لم تتحول الى ابنية ، والمعادن المختلفة لم تصبح قطعا الية ومعدات ميكانيكية الا بفعل الانسان ، كذلك فان المادة بشكل عام ليست العامل في كل شيء لانها منفعلة وليست فاعلة ؟", "واذا ثبت أن المادة لا بد لها من قوة فاعلة ، وانها لا يمكن أن تتحرك ، أو تتطور تلقائيا من مؤثر خارجي .. وأن الانسان هو هذا المؤثر الخارجي ، اصبح الانسان هو صاحب القيمة الاساسية في الوجود وليس كما تقول الماركسية . وبالتالي فان الانسان والمادة كقوتين مخلوقتين مخلوقتين محدودتين تعملان بطرق متقلبة وناقصة - دلالة على نقص ملازم لهما - تؤكدان بمجرد وجودهما وعجزهما ومحدوديتهما وجود قوى غيبية قادرة وراء المادة ووراء الانسان وفوق المادة وفوق الانسان ..", "فالمادة والانسان مخلوقان ، وبالتالي ناقصان وعاجزان وقابلان للزوال ، ويحتاجان الى خالق وجد قبلهما دون أن يكون محتاجا الى غيره وهو ( الله ) الذي أثبتت وجوده أعماله وخلقه .", "الشيوعية قرين الالحاد : ان ( تقييم ) الشيوعية المادي للكون والانسان والحياة جعلاها تنكر وجود الله وتنكر سائر المغيبات الاخرى كالروح"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0057.png"}, {"n": 58, "paras": ["والجنة والنار والحساب والعقاب والجان والملائكة ، واليكم الشواهد على ذلك :", "★ قال ماركس ( لا اله والحياة مادة ) .", "★ قال لينين عام ١٩١٣ ( ليس صحيحا أن الله هو الذي ينظم الاكوان . انما الصحيح هو أن الله فكرة خرافية اختلقها الانسان ليبرر عجزه . ولهذا فان كل شخص يدافع عن فكرة الله انما هو شخص جاهل وعاجز ) .", "★ جاء في خطاب لينين في المؤتمر الروسي عام ١٩٢٠ ( أن تهذيب الشبان وتعليمهم يجب أن يتوخى تلقيحهم بالاخلاق الشيوعية ولكن هذه الاخلاق ليست مستمدة من وصايا الهية لاننا لا نؤمن بالله ) .", "★ يقول لينين ( أن كل فكرة دينية وكل معتقد بالله ، لا بل ان مجرد التفكير بالله دناءة كامنة في النفس ) .", "★ نشرت صحيفة ( سوفتسكيا برافدا ) عام ١٩٥٤ ( أن الاعتقاد بالله هو تراث القدامى الجهلة ) .", "★ ونشرت عام ١٩٥٨ ( أن واجبنا يقضي بان نوجه حملة كفاح عقائدي صحيح ضد الدين ) .", "★ اذاعت محطة اذاعة موسكو في ٣ نيسان ١٩٥٨ ما نصه : ( ان جميع الديانات متشابهة من حيث انها كلها باطلة، كما أن وجود الميول والاتجاهات المختلفة جعل الواحدة منها تطرد الاخرى ) .", "★ نشرت صحيفة تركمانسكايا اسكرا في ١ كانون الاول عام ١٩٥٨ ( أن العقيدة الدينية الاسلامية هي القوة المظلمة التي لا تزال تفسد العقول وحياة الشعوب وتعيق"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0058.png"}, {"n": 59, "paras": ["النمو وتقف كأي حاجز في طريق السعادة والنور والمعرفة . هذا وان الطقوس الدينية لا تزال لاصقة ثابتة ، كما أن الديانة لم تتوقف عن كونها مادة الافيون لدى بعض الناس ) .", "★ ونشرت ( باكنسكي بابوشي ) في ١٧ كانون الاول ١٩٥٨ ( لو كان الله موجودا لما سمح أن ننبذ الدين ) .", "★ نشرت صحيفة العلم الاحمر بتاريخ ١ اذار ١٩٥٩ ( من الطبيعي أن الصراع بين الالحاد والايمان بالله لم ينته بعد ، ولا بد من توجيه الجماهير نحو استئصال جذور الايمان بالخرافات والجنة والالهة بصورة أعمق مما حدث حتى الان ) .", "★ وفي برنامج المؤتمر السادس الدولي الشيوعي الذي انعقد في سنة ١٩٢٨ ما يأتي : ( الحرب ضد الدين - أفيون الشعب - تشغل مكانا هاما بين أعمال الثورة الثقافية، ويلزم أن تستمر هذه الحرب باصرار وبطريقة منظمة ) .", "وقد روى فريق من المسلمين اللاجئين من الاتحاد السوفياتي قصصا مثيرة عن حوادث التعذيب والتجويع والتقتيل التي عانوا منها الامرين على أيدي السوفيت .. وهم يقولون ان عدد مسلمي الاتحاد السوفياتي انخفض خلال الثلاثين سنة الماضية الى النصف او اكثر .. ويروون أن السوفيت انتهكوا حرمة المساجد ، واعدموا مئات الالوف من المسلمين ، وارسلوا اخرين الى معسكرات الاعتقال في سيبيريا للقضاء على الاسلام في الاتحاد السوفياتي ..", "ولن ينسى المسلمون ولا ذراريهم ، ذلك المؤتمر الاسلامي الذي انعقد في خوقند سنة ١٩١٧ ، أي في أوائل الشيوعية ليطالب بالحكم الذاتي لتركستان . فاذا بالجنود الشيوعيين"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0059.png"}, {"n": 60, "paras": ["يغيرون على المدينة غارة وحشية اجرامية ، ويقتلون آلافاً من المسلمين ويهدمون بيوتهم ، ويصادرون املاكهم واموالهم ، وتقع بعد ذلك المجاعة البشعة التي مات فيها عدد لا يحصى من المسلمين ..", "وقد قدرت المصادر الروسية نفسها عدد ضحايا الحكم السوفياتي من المسلمين فيما بين سنتي ١٩١٧ - ١٩١٨ بمليون مسلم (١) ؟؟ المادية التاريخية :", "المادية التاريخية هي المبدأ الثاني من المبادىء التي تقوم عليها الماركسية .. وهي النظرة التي تدعي بأن تاريخ الانسانية ليس سوى مجموعة أعمال واحداث بشرية كملت وقامت بدوافع مادية بحتة ؟", "يقول ماركس ( ليست الافكار - كما يتردد ذلك أكثر الاحيان - هي التي تقود العالم ، بل ان هذه الافكار ذاتها تتعلق كذلك بالشروط الاقتصادية .. ومعنى هذا انها تتعلق بالمادة التي تفسر التاريخ في نهاية الامر .. ان الاقتصاد الذي يشمل مجموع الجهود الانسانية في سبيل امتلاك المادة واستخدامها ، انما يشكل البنية الاساسية للعلاقات الانسانية في حين ان المذاهب الفكرية ليست الا بنية فوقية ) .", "والتصويب المنطقي الذي لفت الاسلام الفكر الانساني اليه في تصور أسباب التطور ، أقر به ( هيغل ) في فجر القرن التاسع عشر اقرارا عفويا حين لم يعتبر الفكر نتاجا للمادة وانعكاسا لحركتها في دماغ الانسان ، وانما اعتبر الفكرة المطلقة ( الله ) صانعة المادة وخالقتها . وهذا ما ..", "(١) «حقيقة الشيوعية» (صفحة ١٨٦ - ١٩٨) ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0060.png"}, {"n": 61, "paras": ["ماركس الى أن يهاجم فلسفة هيغل بقوة ، فيقول في كتابه ( رأس المال ) : ( ان الطريقة الديالكتيكية لا تختلف عن الطريقة الهيغلية من حيث الاساس فحسب بل هي ضدها تماما . فحركة الفكر ليست سوى انعكاس الحركة الواقعية ( المادية ) منقولة الى دماغ الانسان ومستقرة فيه ) . والنظرية الشيوعية في تفسيرها المغلوط لاسباب النشوء والتطور تجنح الى اخضاع الاسلام نفسه لمقاييسها العرجاء . يقول ماركس وانجلز ( ان الاسلام كغيره من الاديان ظاهرة تاريخية خاضعة للتطور ومحدودة بالزمن . وظهور الاسلام قائم على أسباب تاريخية واضحة لا تحمل في طياتها اي عنصر غريب او عجيب ) . فاذا سلمنا ان اختفاء القديم ونشوء الجديد هما قانون التطور المادي المجرد من كل العوامل الغيبية والبواعث الفكرية والوجدانية والخلقية كما تقول بذلك الشيوعية (١) وان الشيوعية ستحل محل الرأسمالية ، فمعنى هذا ايضا ان نظاما اخر سيحل محل الشيوعية في حينه تبعا للنظرية الديالكتيكية نفسها ؟", "انه مما لا شك فيه أن العالم في تطور دائم وتغير مستمر ، لا يكاد ينتهي في طور حتى ينتهي الى صيرورة ،", "(١) يقول ستالين في كتابه ( المادية الديالكتيكية ) : اذا صح أن العالم يتحرك ويتطور دائما وأبدا .. واذا صح ان اختفاء القديم ونشوء الجديد هما قانون التطور .. أصبح من الواضح أن ليست هناك أنظمة اجتماعية ثابتة غير قابلة للتغيير ، ولا مبادىء أبدية للملكية الخاصة والاستثمار . وليست هناك أفكار أبدية عن خضوع الفلاحين لكبار ملاكي الارض والعمال للرأسماليين وبالتالي يمكن ان يحل النظام الاشتراكي محل النظام الرأسمالي كما حل النظام الرأسمالي في حينه محل النظام الاقطاعي ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0061.png"}, {"n": 62, "paras": ["وهكذا حتى تنطفىء اخر شعلة للحياة في الكون ويرث الله الارض ومن عليها . ونظرة الاسلام الى الحياة تسلم بوجود هذا التطور الدائم والتغيير المستمر .. والتطور المنهجي في دعوات الانبياء منذ الخليقة الاولى حتى الاسلام دليل واضح على التطور الحتمي في حياة البشرية .. كل هذا مما يقرره الاسلام ويثبته ويشير الى أسبابه ويعلق على نتائجه .. لكن الاسلام لا يذهب مذهب الشيوعية في تفسيرها المادي لهذا التطور ، بل يجعل للقوى ( الغيبية ) وللقدرات ( الفكرية ) وللبواعث ( الاخلاقية ) وللمنافسات ( المنافية ) الحساب الاقوى والاكبر في تحقيق هذا التطور .. فالاسلام والشيوعية وان اتفقا شكلا على حتمية التطور فبينما يؤمن الاسلام باله لهذا الكون يصرف فيه كل أمر حسب قانون ارتضاه لعباده ، تنكر الشيوعية من ناحية ثانية وجود اي اله لهذا الكون ، كما تنكر اي دور لعبه الانبياء والرسل في عملية التطور البشري .. ولقد علق لينين على هيرقليطس الفيلسوف اليوناني حينما قال : ( ان العالم لم يخلقه اي اله أو انسان ، وقد كان ولا يزال وسيكون شعلة حية الى الابد تشتعل وتنطفىء تبعا لقوانين معينة ) قال لينين : يا له من شرح رائع لمبادىء المادية الديالكتيكية ؟ فالشيوعية تعارض ما تسميه بالمثالية الفلسفية ( اي النظرة الغيبية للوجود ) من حيث الاساس وعلى خط مستقيم ، وتتميز بالخطوط الاساسية التالية : أولا : خلافا ( للمثالية ) التي تعتبر العالم تجسدا ( للفكرة المطلقة ) أو ( للعقل الكلي ) أو ( للوعي ) تسير مادية ماركس الفلسفية على المبدأ القائل ان العالم بطبيعته"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0062.png"}, {"n": 63, "paras": ["مادي ، وان حوادث العالم المتعددة هي مظاهر مختلفة للمادة المتحركة . وان العلاقات المتبادلة بين الحوادث ، وتكييف بعضها بعضا بصورة متبادلة كما تقررها الطريقة الديالكتيكية هي قوانين ضرورية لتطور المادة المتحركة ، وان العالم يتطور تبعا لقوانين حركة المادة ، وهو ليس بحاجة الى ( عقل كلي ) .", "ثانيا : خلافا ( للمثالية ) التي تؤكد أن شعورنا وحده هو الموجود واقعيا ، وأن العالم المادي والكائن والطبيعة لا توجد في ادراكنا واحساساتنا وتخيلاتنا وتصوراتنا. تقوم المادية الفلسفية الماركسية على مبدأ اخر وهي أن المادة والطبيعة والكائن هي حقيقة موضوعية موجودة خارج الادراك وبصورة مستقلة عنه ، وان المادة هو عنصر أول لانها منبع الاحساسات والتصورات والادراك ، بينما الادراك هو عنصر ثان مشتق ، لانه انعكاس المادة انعكاس الكائن . وان الفكر وهو نتاج المادة لما بلغت في تطورها درجة عالية من الكمال. ثالثا : خلافا ( للمثالية ) التي تنكر امكان معرفة العلم وقوانينه ولا تؤمن بقيمة معارفنا ، ولا تعترف بالحقيقة الموضوعية وتعتبر أن العالم مملوء ب ( أشياء قائمة بذاتها ) ولن يتوصل العلم أبدا الى معرفتها . تقوم المادية الفلسفية الماركسية على المبدأ القائل انه من الممكن تماما معرفة العالم وقوانينه ، وان معرفتنا لقوانين الطبيعة ، تلك المعرفة التي يجري اختبارها بالعمل والتجربة هي معرفة ذات قيمة ، ولها حقيقة موضوعية ، وان ليس في العالم أشياء لا تمكن معرفتها وانما فيه اشياء لا تزال مجهولة بعد ، وهي ستكشف وتصبح معروفة بوسائل العلم والعمل (١)", "(١) المادية الديالكتيكية صفحة ٢١ - ٢٧ ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0063.png"}, {"n": 64, "paras": ["وبذلك تكون الشيوعية بتفسيرها المادي للتاريخ قد هبطت بقيمة الانسان الى مستوى الحيوانية ، وجردته من كل القيم والفضائل والخصائص الانسانية ، وهذا بدون شك مرفوض من الاسلام لانه ( اي الاسلام ) كرم الانسان ، وجعل حياته مسرحا للتنافس على الحق واشاعته وتحقيقه بين الناس ..", "وفي نظري أن ( الكنيسة ) في أوربا تتحمل مسؤولية ردة الفعل هذه التي اصابت التفكير البشري بداء العداء للدين- كل دين - وفي بروز كل اتجاه مادي متطرف يكفر بالقيم الروحية ويعتبر الدين أفيونا للشعوب او عدوا للعلم والتقدم. والشيوعية احدى هذه الثمار التي تسببها خروج الدين في أوربا عن اطار الاصيل للمسيحية ، وسوء استغلالهم السلطات الزمنية .", "والاسلام كدين حين يتعرض اليوم لكثير من المظان من مختلف الاتجاهات المادية فبجريرة ما ارتكبته الكنيسة من اخطاء شوهت كل فكرة دينية على الاطلاق .", "فالمثالية التي تقصدها الشيوعية انما هي المثالية الفلسفية التي اعتمدتها الكنيسة لانتزاع السلطة الزمنية من الحكام وبسط النفوذ الاكليري واحكام السيطرة الروحية ومحاربة العلم والعلماء .", "أما مثالية الاسلام فانها لم تعن بالروح على حساب الجسد والمادة ، وانما برزت مثالية الاسلام في خطة محكمة"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0064.png"}, {"n": 65, "paras": ["قويمة معتدلة لا تفريط فيها ولا افراط .. كذلك كانت مثالية الاسلام غاية في التوافق مع العلم والمعرفة والدعوة اليهما والحض على الاستزادة منهما .. هذا فضلا عن أن محتوى النصرانية غير محتوى الاسلام كما ورد تفصيل ذلك في موضع آخر من هذا الكتاب .", "الشيوعية قرين الصهيونية :", "ان الممعن في دراسة طبيعة وخصائص واهداف الحركتين الصهيونية والشيوعية يلمس بوضوح العلاقة الوثيقة القائمة بين هاتين الحركتين ويبدو له بجلاء القاسم المشترك بينهما سواء في الخصائص أو في الاهداف ؟", "(١) سيادة العالم", "النقطة الاولى من نقاط الالتقاء بين الشيوعية والصهيونية تبدو في نزعة السيادة على العالم واستغلاله وتسخيره لمصالحهما .", "فالشيوعية تهدف الى غزو العالم والسيطرة عليه . وقد كشفت الشيوعية عن هذا الغرض من ظهور بيان ماركس وانجلز المشهور في تاريخ الشيوعية .. يقول ماركس ( امامكم العالم وعليكم ان تكسبوه ) .", "كذلك طغت فكرة السيطرة على العالم منذ زمن بعيد على العقلية اليهودية ودونها اليهود في قوانينهم السرية ،"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0065.png"}, {"n": 66, "paras": ["لاعتقادهم بانهم شعب الله المختار ، وأن بقية الناس فقد خلقوا ليسخروا في خدمة بني اسرائيل ؟", "جاء في البروتوكول الخامس من بروتوكولات حكماء صهيون : ( اننا نقرأ في شريعة الانبياء اننا مختارون من الله لنحكم الارض . وقد منحنا الله العبقرية كي نكون قادرين على القيام بهذا العمل ، وسنضع موضع الحكومات القائمة ماردا Monstor يسمى ادارة الحكومة العليا : ( Adminstration of supergoverment ) . وستمتد أيديه كالمخالب الطويلة المدى ، وتحت امرته سيكون له نظام يستحيل معه أن يفشل في اخضاع كل الاقطار ) .", "(٢) نشر الالحاد", "يلاحظ القارىء ان علماء اليهود كذلك يعملون ما في وسعهم لهدم الاديان عن طريق استحداث المذاهب السياسية والفكرية كالشيوعية والوجودية والماسونية ومذهب التطور والسريالية ويقومون على دراسة علم الاديان المقارن لغاية نشر الالحاد ونسف الايمان من النفوس . جاء في البروتوكول الرابع عشر ( ولهذا السبب يجب علينا أن نحطم كل عقائد الايمان . واذ تكون النتيجة المؤقتة لهذا هي اثمار ملحدين ، فلن يدخل هذا في موضوعنا ، ولكنه سيضرب مثلا للاجيال القادمة التي ستصغي الى تعاليمنا على دين موسى الذي وكل الينا بعقيدته الصارمة واجب اخضاع كل الامم تحت اقدامنا (١) .", "(١) الخطر اليهودي - بروتوكولات حكماء صهيون لمحمد خليفة التونسي صفحة ١٨٤ ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0066.png"}, {"n": 67, "paras": ["(٣) التوسل بالعنف", "والملاحظ كذلك أن الشيوعية تلتقي مع الصهيونية في التوسل بالعنف والقسوة والوحشية لاقامة سلطانها ؟", "يقول ستالين ، ( انكم لا تستطيعون الهرب من الكوارث الطبيعية كالزلازل والعواصف التي تقتل الملايين ، فتقبلونها صاغرين ، فكيف لا تقبلون عمليات التطهير التي تقوم بها السلطات الشيوعية للحفاظ على هذا المبدأ الذي سيقدم اليكم الخير ٠٠)", "كذلك يقول البروتوكول الصهيوني الاول ( يجب أن يكون شعارنا « كل وسائل العنف والخديعة ، ان القوة المحضة هي المنتصرة في السياسة ، وبخاصة اذا كانت مقنعة بالالمعية لرجال الدولة ٠ يجب أن يكون العنف هو الاساس ) كما يقول البروتوكول السابع : ( وبايجاز ، من أجل أن نظهر استعبادنا لجميع الحكومات الاممية في اوربا ، سوف نبين قوتنا لواحدة منها ، متوسلين بجرائم العنف ٠ وذلك هو ما يقال له حكم الارهاب واذا اتفقوا جميعا ضدنا ، فعندئذ سنجيبهم بالمدافع الاميركية او الصينية أو اليابانية ) ٠", "(٤) التوسل بالخداع وبجميع الوسائل المناهضة للاخلاق", "وكما أن الشيوعية تبارك كل أنواع الخداع والغش والاحتيال في سبيل تحقيق المبادىء الشيوعية ، يقول لينين: ( يجب على المناضل الشيوعي أن يتمرس بشتى ضروب الخداع والغش والتضليل ٠ فالكفاح من أجل الشيوعية يبارك كل وسيلة تحقق الشيوعية ٠ يجب أن يكون مفهوما أن"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0067.png"}, {"n": 68, "paras": ["الشيوعية غاية نبيلة ، وان تحقيق الغاية النبيلة يتطلب في كثير من الاحيان استخدام وسائل غير نبيلة . ولهذا فان الشيوعية تبارك شتى الوسائل المناهضة للاخلاق ما دامت هذه الوسائل تساعد على تحقيق اهدافنا الشيوعية ) .", "كذلك تفعل الصهيونية حين تقول في البروتوكول الاول : ( ويتحتم أن يكون ماكرا خداعا حكم تلك الحكومات التي تأبى أن تداس تيجانها تحت أقدام وكلاء (Agenr) قوة جديدة . ان هذا الشر هو الوسيلة الوحيدة للوصول الى هدف الخير . ولذلك يتحتم الا نتردد لحظة واحدة في أعمال الرشوة والخديعة والخيانة اذا كانت تخدمنا في تحقيق غايتنا ) ويقول الدكتور أوسكار ليفي ( نحن اليهود لسنا الا سادة العالم ومفسديه ومحركي الفتن فيه وجلاديه ) .", "(٥) تعاطف الحركتين", "ان التعاطف العقائدي بين الماركسية الدولية والصهيونية العالمية والذي تحول الى تعاطف سياسي بين اليسار واسرائيل هو من الادلة التي تساق في هذا المجال أيضا .. هذا الكلام نحن لا نقوله افتئاتا ، وانما نقرر به أمرا بات يقينيا ، أكدته مئات الشواهد والمواقف القطعية: فبتاريخ ٢٢ حزيران ١٩٦٤ أدلى الملحق العسكري السوفياتي في باريس لمراسل صحيفة ( معاريف ) بتصريح طويل نقتطف منه المقاطع التالية : ( لقد اعربنا عن تأييدنا لاسرائيل بالسلاح والعتاد والرجال في اقسى ظروف الامة الفلسطينية . فما قدمناه ونقدمه للبلاد العربية من سلاح هو لاغراض دفاعية ولمكافحة الرجعية العربية فقط . ولا يمكن ان نسمح باستعماله للعدوان على اسرائيل فنحن نريد سلامة اسرائيل،"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0068.png"}, {"n": 69, "paras": ["بل نعمل من أجل سلامتها .. ثم هل تظنون اننا جاهلون لاهمية اسرائيل بالنسبة الينا؟ وهل تظنوننا لا نعلم ما هو نوع الحكم الاشتراكي السليم الذي تبنونه في اسرائيل بأيديكم ؟ وهل من المعقول أن نكون طرفا في هدم التجربة الاشتراكية التي حققتها اسرائيل ؟ وهل تظنون اننا مهملون أهمية الوجود الاسرائيلي في الشرق الاوسط ، تلك المنطقة المهمة؟ اطمئنوا .. اطمئنوا .. ان الاتحاد السوفياتي مع اسرائيل ، وسيؤيدها اليوم وغدا كما أيدها ورعاها بالامس . ونحن نرعى الاشتراكية العربية لان في ذلك تعزيزا لمصلحة اسرائيل أيضا ؟ )", "وبتاريخ الرابع عشر من شباط سنة ١٩٦٥ نشرت صحيفة ( هاارتس ) الاسرائيلية تصريحا للمستشار الاول في السفارة السوفياتية في اسرائيل نقتطف منه ما يلي : ( لم نقدم السلاح لبعض الدول العربية الا بما يكفي لحاجات الدفاع لا الهجوم وعلى الشعب في اسرائيل أن يتذكر أن الاتحاد السوفياتي كان أول من دعا الى حظر توريد السلاح الى الشرق العربي عام ١٩٥٧ ونحن مستعدون لحظر السلاح عن المنطقة العربية .. لكن حركات التحرير اليسارية في العالم العربي تحتاج الى السلاح لتكافح الرجعية العربية وتقضي عليها وعلى كل من يساعدها . ان القضاء على الرجعية العربية سيزيل خطر العدوان العربي على اسرائيل ، لان الانظمة والحركات التقدمية اليسارية في البلاد العربية لا تريد العدوان على اسرائيل .. )", "وبتاريخ الخامس عشر من شباط من عام ١٩٦٨ ألقى الكسي كوسيغن خطابا في مدينة ( مدينسك ) السوفياتية جاء فيه : ( نحن لسنا أنصار حرب جديدة في الشرق الاوسط بل على العكس ، نريد سلاما مستقرا في المنطقة ، وهناك بعض"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0069.png"}, {"n": 70, "paras": ["الدول العربية تؤيد هذا الموقف . اننا نرفض تصفية اسرائيل بل نؤيد استمرار اسرائيل كدولة ) .", "(٦) شواهد اخرى", "ولم يكن من قبيل المصادفة أن زعيم الشيوعية الاكبر وواضع اسسها هو الحبر الاعظم ( كارل ماركس ) اليهودي المتعصب ؟ وان انصار الشيوعية في العالم معظمهم انصار الصهيونية .. وأن المجلس الذي حكم روسيا بعد الثورة الشيوعية عام ١٩١٧ كان بينهم ستة يهود من أصل عشرة اعضاء .. وان صهر (ستالين) (وبريا) الذي كان رئيسا للشرطة السرية ، ( وشنفرنك ) رئيس جلسات مجلس السوفيات الاعلى ، ( واليا اهرنبرج ) لسان حال الكرملين وداعيته المشهور ، كلهم يهود ؟", "واذا اضفنا الى ذلك ما نشرته مجلة ( افريكان هيبرو ) في عددها الصادر يوم ١٠ سبتمبر عام ١٩٢٠ وهي من كبرى المجلات اليهودية ( ان الثورة الشيوعية في روسيا كانت من تصميم اليهود ، وانها قامت نتيجة لتدبير اليهود الذين يهدفون الى خلق نظام جديد للعالم ، وان ما تحقق في روسيا كان بفضل العقلية اليهودية التي خلقت الشيوعية في العالم ، ونتيجة لتدبير اليهود ، ولسوف تعم الشيوعية العالم بسواعدهم ) (١) .", "يتأكد لنا بما لا يحتمل الشك أن الشيوعية ربيبة الصهيونية العالمية ، وهذا ما نطقت به فقرة من فقرات البروتوكول الثالث لحكماء صهيون حيث تقول : ( اننا نقصد", "(١) راجع كتاب حقيقة الشيوعية لمجموعة من الكتاب المصريين ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0070.png"}, {"n": 71, "paras": ["ان نظهر كما لو كنا المحررين للعمال ، جئنا لنحررهم من هذا الظلم ، حينما ننصحهم بان يلتحقوا بطبقات جيوشنا من الاشتراكيين والفوضويين والشيوعيين . ونحن على الدوام نتبنى الشيوعية ونحتضنها متظاهرين باننا نساعد العمال طوعا لمبدأ الاخوة والمصلحة العامة للانسانية . وهذا ما تبشر به الماسونية الاجتماعية .. )", "الشيوعية خيانة عظمى وقرين الاستعمار :", "وأما ان الشيوعية خيانة عظمى وقرين للاستعمار فلان الارتباط بها والانتماء اليها انما هو في الحقيقة ارتباط بكيان اجنبي يضع ( المصلحة الشيوعية ) فوق المصلحة الوطنية والعربية والاسلامية . وهو بالتالي تكريس لاستعمار جديد تتزعمه ( موسكو أو بكين ) عوضا عن ( لندن وواشنطن ) . وهو خروج من منطقة النفوذ ( البلشفي الصيني ؟ ) .", "جاء في البيان الشيوعي ( ليس للعمال وطن - يا صعاليك - العالم اتحدوا ) .. وجاء في محاضرة لستالين ألقاها في موسكو عام ١٩٢٤ : ( ان من واجب الشيوعي في كل الاحوال أن يناضل ضد الوطنية الضيقة وان لا يحصر نفسه في حركته المحدودة الافق ) (١) ويقول (جورج يمتروف) ( الاتحاد السوفياتي هو الوطن الكبير لعمال العالم اجمع ) . وكتب ماركس ( ان العمال في اكثريتهم الساحقة منزهون عن الاوهام القومية ، لان ثقافتهم وحضارتهم في الجوهر انسانيتان ومعاديتان للقومية ) (٢) .", "(١) القضية الوطنية - تأليف ستالين صفحة ٣٨ .", "(٢) القومية العربية - تأليف عفلق والبيطار صفحة ٣٥ ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0071.png"}, {"n": 72, "paras": ["في ضوء هذه الحقائق يتأكد - بما لا يحتمل الشك - أن الشيوعية خيانة عظمى وقرين الاستعمارية وتبعية للون جديد من ألوان الاستعمار .. وان المصلحة الشيوعية التي يقدرها ( الكرملين ) هي عند الشيوعيين فوق كل مصلحة ؟؟", "جرثومة فناء الشيوعية :", "ان نظرة فاحصة الى النزاع القائم في دول المعسكر الشيوعي يمكن ان تكون كافية للتأكيد على أن طور الانحدار والانهيار في الفلسفة الماركسية قد بدأ ، وان الفكر الشيوعي يعاني ازمة مصيرية حادة قد لا يخرج منها الا وقد دكت أصوله وقواعده ولفظ نفسه الاخير .", "في أيلول عام ١٩٦١ نشرت جريدة ( برافدا ) الناطقة بلسان اللجنة المركزية للحزب الشيوعي في الاتحاد السوفياتي مشروع برنامج جديد للحزب يؤكد للمرة ( الثالثة ) خروج الحزب على المبادىء الاساسية الماركسية . فقد تضمن المشروع فكرة الغاء النهج الثوري الذي تعتمده الشيوعية في هدم الكيان الرأسمالي وبناء المجتمع الشيوعي ، والذي نصت عليه الفقرة التالية : ( وبالتالي فان الانتقال من الرأسمالية الى الاشتراكية وتحرير الطبقة العاملة من النير الرأسمالي ، يمكن تحقيقها لا بتغييرات بطيئة ولا باصلاحات بل بتغير كيفي للنظام الرأسمالي فقط ، أي بالثورة ) (١) .", "وهذا ما جعل بكين وموسكو - مسرحا لمنازعات دموية حادة ، لاصرار الحزب الشيوعي الصيني الذي يتزعمه ( ماوتسي تونغ ) على تنفيذ مبدأ ( الحرب الحتمية ) بين الشيوعية والرأسمالية .", "(١) المادية الدياليكتيكية صفحة ٢٥ ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0072.png"}, {"n": 73, "paras": ["وفضلا عن جنوح المنهج الجديد عن فلك النظام الاساسي للحزب الشيوعي ، فقد أكد من خلال تعهده بتحقيق المجتمع الشيوعي خلال العشرين سنة المقبلة ، على فشل الشيوعية خلال الاربعين سنة الماضية في خلق الاساس المادي والتكنيكي للمجتمع الشيوعي . وهذا يعني أن الشيوعية كفكرة تفقد القدرة على ما يمسونه بالحتمية التاريخية في الانتقال من الرأسمالية الى الاشتراكية . ويعود هذا العجز اساسا الى ان الشيوعية لا ترتكز على اصول وقواعد عامة قابلة لاستيعاب مشاكل الحياة المتجددة المتعقدة ، مما عرضها الى كثير من التعديل والتغيير الجذريين في أصولها المنهجية والفكرية في أقل من ربع قرن .", "فمبدأ محو ( الملكية الفردية ) عدل عنه الى حل وسط ، وهو الاحتفاظ للدولة بالصناعات الثقيلة والتجارة الخارجية والمصارف والمشاريع العامة ، وترك الصناعات الصغيرة والتجارة الوسطى للسعي الفردي .", "كذلك عدل عن مبدأ ( توزيع السلع الاستهلاكية ) فبدل أن كانت القاعدة ( من كل حسب قدرته ولكل حسب حاجته) أصبحت كما نص عليها الدستور السوفياتي المعدل عام ١٩٣٦ ( من كل حسب قدرته ولكل حسب ما يؤديه من عمل، ومن لا عمل له ليس له الحق أن يأكل ) ومرة ثالثة جاء المشروع الجديد عام ١٩٦١ يشير الى أن الاتحاد السوفياتي سيطبق خلال العشر سنوات الواقعة بين ( ١٩٧١ - ١٩٨٠ ) مبدأ (التوزيع حسب الحاجة) وبذلك يتراجع الحزب الشيوعي مرة أخرى عن تعديل عام ١٩٣٦ .", "ومن الامثلة الحسية التي تساق على اضطراب معايير النهج الشيوعي ، الغاء المزارع الحكومية المعروفة باسم"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0073.png"}, {"n": 74, "paras": ["( السوفوكوز ) بعد أن ظهر فشلها ، وبعد أن كلفت الحكومة مبالغ طائلة من المال . بالاضافة الى التعديلات الاخرى التي اجريت على المؤسسات الزراعية المعروفة باسم ( الكلوكوز ) .", "والحقيقة أن الفكر الشيوعي من يوم ولد كان في وضع لا يسمح له بالحياة والاستمرار الا بمقدار ما تحميه القوة التي يمتلكها .", "هذه الحقيقة افصحت عن نفسها في كثير من مواقف التأديب والعنف التي وقفها ( الكرملين ) من عدد من البلدان الاشتراكية في شرقي أوربا ، بدعوى خروجها على الخطوط الاساسية ( للايديولوجية الشيوعية ) .", "فلقد هز الكرملين في السابق عصاه في وجه ( اولبرخت ) و ( غوموكا ) و ( المجريين ) و ( الصينيين ) .. ومن عهد قريب اجتاحت جيوشه العاصمة التشيكية لتأديب من يعتبر انهم شقوا عصا الطاعة عليه وصبنوا عن ( دين ) ماركس ولينين ؟", "وان أشد ما يخشاه ( الكرملين ) ويخافه أن يفلت الزمام من يده ، وتخرج عن طاعته دول الكتلة الشيوعية دولة فدولة لاسيما وقد سبق أن افلتت من قبضته كل من ( يوغسلافيا ورومانيا ) .", "والذي يهمنا هنا وفي هذا المقام هو الاشارة الى أن العامل الاساسي الكامن وراء الازمات الحادة والمنازعات المتصاعدة بين البلدان الاشتراكية هو أن ( الفلسفة الماركسية ) كغيرها من المبادىء ( الوضعية ) خاضعة للتفسيرات والتصورات الشخصية لزعماء الحركة الشيوعية ، وهذا ما جعلها تدور خلال نصف قرن من الزمن في دوامة مفرغة من التأويلات"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0074.png"}, {"n": 75, "paras": ["الجدلية المتناقضة ، مما أدى الى انفراط وحدة الحركة الفكري والى نشوء مدارس متعددة للفكر الشيوعي ( كاللينينية - والستالينية - والتروتسكية - والكاستروية - والماوتسية .. الخ .. ) .", "ان بشرية ( الفلسفة الماركسية ) جعلها تفقد عنصر ديمومتها وبقائها ، وجعلها تفقد القدرة على مواجهة مشاكل الحياة ، كما جعلها تصطدم بكثير من المبادئ الفطرية وتخرج عن الحقائق الكونية الثابتة ..", "وحين فشلت ( الثورة البلشفية الشيوعية الحمراء ) في تحقيق الغاية من قيامها، وغدت (الجنة الموعودة) سجنا رهيبا لا يطاق ، وحياة ضنكا ملؤها البؤس والشقاء .. وغدا ( السلام والعدالة شعارات حمراء ملطخة بالدماء ، شأنها شأن الشعارات الكاذبة المزيفة التي يرفعها ( الغرب ) لاخفاء حقيقتة وتغطية جرائمة وخداع الرأي العام العالمي .. عند ذلك بدأ التشقق في ( الجسم الشيوعي ) وانفجرت في انحائه القروح وعمت اجزاءه الجيوب والجروح .. وهذه هي النهاية المنتظرة والمصير المحتوم لكل الاتجاهات المادية والأنظمة الوضعية والفلسفات البشرية .", "انه تأكيد على عجز الانسان وقصوره وحاجته الملحة الى هدى الله والى شرع الله . « يا ايها الناس ضرب مثل فاستمعوا له : ان الذين تدعون من دون الله لن يخلقوا ذبابا ولو اجتمعوا له ، وان يسلبهم الذباب شيئا لا يستنقذوه منه ، ضعف الطالب والمطلوب . ما قدروا الله حق قدره ان الله لقوي عزيز » ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0075.png"}, {"n": 76, "paras": ["مراجع مقترحة للدراسة", "- أصول الفلسفة الماركسية .", "- المادية الديالكتيكية .", "- البيان الشيوعي .", "- هذه هي الديالكتيكية - بول فولكييه .", "- اعرف مذهبك - لمارتين دودج .", "- ماركس والخلق - لطلال الجرجس .", "- الشيوعية والديمقراطية - ابراهيم حداد .", "- حقائق عن الشيوعية - لمجموعة من الكتاب .", "- الخطر اليهودي - محمد خليفة التونسي .", "- نقض الاشتراكية الماركسية - غانم عبده .", "- الاسلام في نظر الشيوعية والشيوعيين - ابن حمدون .", "- نهضة الشيوعية الحديثة - ماسيمو سلفادوري .", "- تأملات في فشل الاشتراكية - ماكس ايستمان .", "- أسس اللينينية - ستالين ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0076.png"}, {"n": 77, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0077.png"}, {"n": 78, "paras": ["(۳) نقد الرأسمالية", "لا تعتبر الرأسمالية مذهبا تعتمده الحكومات بل هي نظام اقتصادي يقوم على أساس تملك الافراد والشركات لكل وسائل الانتاج .. يرى ( فرنسوا كيناي ) أحد فلاسفة الفكر الرأسمالي « انه يجب أن يكون الافراد أحرارا في العمل ، وأن يسيروا وفق مصالحهم الخاصة ، وان يسمح لهم بمزاولة المهن التي يختارونها وان تترك لهم حرية الانتقال وحرية اجتناء الثروات وحرية التصرف في ممتلكاتهم كما يرغبون ، ولا يجوز أبدا للدولة أن تتدخل في نشاطاتهم » . ويمكننا أن نلخص أبرز الظواهر التي يتمحض عنها النظام الرأسمالي بما يلي : أولا - تملك الافراد للارض ولرؤوس الاموال ولمنابع الثروات . ثانيا - تكالب الافراد في الحصول على الارباح وابتكار شتى المشروعات والطرق التي تؤدي الى ذلك سواء كانت مشروعات وطرقا مشروعة أم غير مشروعة ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0078.png"}, {"n": 79, "paras": ["ثالثا - العمل على نشر التجارة في انحاء العالم وما يحققه ذلك من بسط سلطان النفوذ المالي والسياسي على المؤسسات الاقتصادية والحكومية بما يحقق مصالح الدول والمؤسسات الرأسمالية .", "ما هي الرأسمالية ؟", "يقول الاستاذ أحمد الشيباني في كتابه ( دراسات في العقائد ) تحت هذا العنوان [ أرى أن الرأسمالية هي المخطط الكامل الذي ابتدعته السلبية في العقل البشري لتنظيم وادارة وتوجيه الغريزة البشرية في أحط ادوارها الهمجية . لذلك اعتبر الرأسمالية هي الحيوانية التي ينظمها العقل ، اذ انها تمثل طمعا واعيا ونهما يقظا يعرف أهدافه ويعرف الوسائل التي يسلكها اليها ، وشراهة تتغذى بالواقع وتهتدي بنور العقل ، واثرة ضيقة خانقة . انها في اختصار أرقى الدرجات التي وصل اليها «العقل الحيواني» في الانسان .. ] ففي ظل النظام الرأسمالي تنعدم حتى الفضائل القليلة التي عرفها مجتمع الاقطاع فضائل النخوة والشهامة والفروسية .. لذلك يبلغ في النظام الرأسمالي الصراع بين « العقل الحيواني » و « العقل الانساني » في الانسان ذروته. ويتخذ المجتمع من الغابة مظهرها وجوهرها ، فلا حياة الا للاقوى ، ولا وجود للضعيف .", "أما أم الفضائل ومنبعها في ظل النظام الرأسمالي فهي الربح ، الربح بأي وسيلة وسبب. والرأسمالية كما سنرى فيما يأتي من بحث لا تتغذى من دماء الشعب فحسب ، بل انما يلتهم الرأسماليون بعضهم بعضا أيضا . وللرأسمالية قوانين رهيبة تسير بموجبها وتطبقها على كل نشاطاتها . وهذه القوانين الرهيبة هي :"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0079.png"}, {"n": 80, "paras": ["١ - قانون البحث عن الربح .", "٢ - قانون المزاحمة والمنافسة .", "٣ - قانون التمركز والقدرة على الانتاج وحصره .", "٤ - قانون السعر المخفض . وسنتناول الان كل قانون من هذه القوانين على حدة .", "١ - قانون البحث عن الربح : ان هذا القانون يشكل التعارض الجوهري بين النظام الاشتراكي والنظام الرأسمالي .. فالنظام الاشتراكي يحصر غاياته الاقتصادية في سد احتياجات البشر ، بينما يوجه النظام الرأسمالي الاقتصاد نحو تحقيق الارباح واختبائها وتكديسها في صناديق اصحاب المشروعات . وتبدأ الرأسمالية أول ما تبدأ في تطبيق هذا القانون على المجتمع الذي تنشأ فيه وتنشط . ويكون أول ضحايا هذا القانون العمال والمستهلكون، اذ انها تسعى أبدا الى زيادة أرباحها على حساب الاجور . ونحن اذا ما عدنا الى المراحل الاولى من تطور الرأسمالية شاهدنا من الاستغلال البشع الذي كانت الرأسمالية تمارسه ضد العمال ، اذ كان هدفها الاساسي يتركز أولا واخيرا على ابتزاز اكبر قدر من الساعات الانتاجية من العمال لقاء أقل قدر ممكن للاجور .. ووفق هذا القانون ، قانون البحث عن الربح ، يصبح العامل سلعة خاضعة لقانون العرض والطلب . فليس للاجور"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0080.png"}, {"n": 81, "paras": ["حد ادنى أو حد أعلى ، وانما تقرر مستواها حاجة السوق الصناعية اولا ومقدار عدد العمال ثانيا .", "ويدفع قانون البحث عن الربح بالرأسماليين وبالدول الرأسمالية الى التفتيش عن المرابح في كل قطر وبلد من أقطار العالم . وكلنا يذكر المآسي الانسانية التي اقترفها ويقترفها الاستعمار بواسطة نفوذه المالي والتجاري في شتى اقطار الارض ..", "٢ - قانون المزاحمة : قلت في مطلع البحث أن الرأسماليين لا يعيشون على دماء الطبقة العاملة ويتغذون بلحوم سكان المستعمرات فحسب بل انهم يلتهمون بعضهم بعضا أيضا . فكل مشروع صناعي يجد في مثيلة من المشروعات الصناعية منافسا له ومزاحما ، لذلك يسعى بكل ما اوتي من جهد لتصفية هذا المشروع والاستئثار بالزبائن والاسواق . وذلك كله حبا باجتناء الارباح.", "ونحن اذا ما أردنا ان نفتش عن أسباب جميع الحروب منذ أن عرف التنظيم الرأسمالي للمجتمع والدولة فاننا نرد أسباب كل حرب الى هذا القانون - قانون المنافسة والمزاحمة .", "٣ - قانون التمركز على الانتاج وحصره : ان قانون المنافسة الذي يدفع بالشعوب والامم الى خوض غمرات الحروب من الرأسمالية والرأسماليين ، يدفع أيضا بالشركات الى الاصطراع والصراع بعضها ضد بعض . اذ تحاول الشركات الكبرى تصفية الشركات الصغيرة أو المتوسطة ، وذلك اما عن طريق ابتلاعها بشراء اكثرية اسهمها"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0081.png"}, {"n": 82, "paras": ["او عن طريق منافستها منافسة شديدة تؤدي الى افلاس الشركات الصغيرة او المتوسطة ومن ثم انهيارها كليا .", "وتلعب المصارف دورا كبيرا في تحقيق اغراض الشركات الكبرى لتصفية الشركات الصغيرة او المتوسطة . اذ أن المصارف تعمد في أوقات الازمات الى منع القروض عن الشركات الصغيرة او المتوسطة ، وتقوم بمطالبة هذه الشركات بتسديد ما عليها من ديون ، وبهذا تدفع بها الى الافلاس والانهيار .", "٤ - قانون السعر المنخفض :", "يقول هذا القانون بالمحافظة على الارباح مع انمائها ، وذلك عن طريق التوسع الميكانيكي في الانتاج وتقليص اليد العاملة . أما ما ينشأ عن انخفاض في تكاليف السلعة عن طريق تقليص الاجور الناشيء عن الاستعاضة بالالة عن العمال ، فهو يؤدي الى تخفيض سعر السلعة على مقادير الارباح ، وبذلك يحافظ الرأسماليون على أرباحهم دون أن يؤثر تخفيض سعر السلعة على مقادير الارباح التي تدخل عليهم ، وهذا كله بسبب أن المشكلة قد حلت عن طريق تقليص اليد العاملة ، وبالتالي الانحدار بالتكاليف عن طريق الاستغناء عن دفع الاجور لعمال حلت الآلة محلهم .", "حكم الاسلام في الرأسماليه :", "ان النظام الرأسمالي يخالف الاسلام من وجوده عدة منها :", "١ - ان الاسلام يرفض النظام الرأسمالي أساسا على"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0082.png"}, {"n": 83, "paras": ["اعتبار انه نظام وضعي كما يرفض بالتالي سائر الانظمة الوضعية .. ويعتبر أن ( بشرية ) النظم الوضعية سبب فشلها وجوثومة فنائها .. كما يعتبر أن كل نظام وضعي انما هو تطاول على حق الله في التشريع ، وأن المنهج الوحيد الذي ختم به الرسالات والاديان جميعا ، وارادة منهج حياة للبشرية في كافة العصور انما هو الاسلام ( ان الدين عند الله الاسلام . ومن يبتغ غير الاسلام دينا فلن يقبل منه وهو في الآخرة من الخاسرين ) .", "٢ - والنظام الرأسمالي حين يقوم على تكوين طبقة في المجتمع تستأثر بتداول المال واستثماره ، كما تستأثر بالنفوذ والسلطة انما يكرس بذلك الطبقية والمظالم الاجتماعية . وهذا يخالف الاسلام الذي يؤمن بضرورة تقييد الملكية الفردية ومحاربة تكديس الثروات ، والذي يضع من التشاريح ما يضمن تفتيتها وتوزيعها على افضل وجه . ( ما أفاء الله على رسوله من أهل القرى فلله وللرسول ولذي القربى واليتامى والمساكين وابن السبيل ، كي لا يكون دولة بين الاغنياء منكم .. ) ( والذين يكنزون الذهب والفضة ولا ينفقونها في سبيل الله فبشرهم بعذاب اليم ) .", "٣ - والنظام الرأسمالي حين يقوم على اطلاق الحرية الشخصية واباحة الاحتكار ، انما يعمل على اذكاء روح الانانية الفردية في المجتمع . وهذا يصطدم بالاسلام الذي يحرص أول ما يحرص على تحقيق مصلحة الجماعة ويحرم الاضرار بالمصالح العامة والقاعدة في ذلك ( لا ضرر ولا ضرار ) . ولذلك يحرم الاسلام الاحتكار واغتصاب حقوق الآخرين واكل أموالهم بالباطل . وهو بالتالي يعطي الانسان من الحرية ما يحفظ به التوازن بين مصلحة الفرد ومصلحة الجماعة ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0083.png"}, {"n": 84, "paras": ["٤ - والنظام الرأسمالي حين يقوم على اباحة (الربا) الذي هو في الواقع علة العلل في كل ما يشكو منه العالم من اضطراب ومشاكل ، والذي يعتبر من النظام الرأسمالي (عموده الفقري) يخالف الاسلام الذي يحرم الربا تحريما قطعيا قال تعالى ( الذين يأكلون الربا لا يقومون الا كما يقوم الذي يتخبطه الشيطان من المس ، ذلك بأنهم قالوا انما البيع مثل الربا ، واحل الله البيع وحرم الربا ) وقال ( يمحق الله الربا ويربي الصدقات ) وقال: ( يا أيها الذين امنوا اتقوا الله وذروا ما بقي من الربا ان كنتم مؤمنين . فان لم تفعلوا فأذنوا بحرب من الله ورسوله ) .", "٥ - واخيرا فان النظام الرأسمالي حين ينظر الى الانسان على أنه كائن مادي مجرد من الميول الروحية والافكار الاخلاقية والغايات المعنوية، وهو حين لا يبالي فيما يجب أن يكون عليه المجتمع من رفعة معنوية وسمو روحي واخلاقي ، انما يتساوى مع سائر المذاهب المادية الاخرى التي يرفضها الاسلام"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0084.png"}, {"n": 85, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0085.png"}, {"n": 86, "paras": ["مراجع مقترحة للدراسة", "- اقتصادنا للسيد محمد باقر الصدر .", "- أسس الاقتصاد بين الاسلام والنظم المعاصرة للمودودي .", "- الاسلام لا رأسمالية ولا اشتراكية - للبهي الخولي .", "- هذه هي الرأسمالية - فرنسوا بيرو .", "- معركة الاسلام والرأسمالية - للشهيد سيد قطب", "- دراسات في العقائد - لاحمد الشيباني .", "- النظام الاقتصادي في الاسلام - لتقي الدين النبهاني .", "- الاسلام ونظم الحكم المعاصرة - لمحمد البهي ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0086.png"}, {"n": 87, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0087.png"}, {"n": 88, "paras": ["(٤) إثبات أن الإسلام منهج حياة", "على الاخ الداعية في هذه الحلقة ان يثبت للمدعو أن الاسلام منهج حياة .. وان يقوض الاعتقاد السائد لدى جمهور المسلمين بانه دين تعبدي لا علاقة له بالحياة وشؤونها الاجتماعية والاقتصادية والسياسية ..", "وبامكان الداعية معالجة هذا الموضوع على النحو التالي :", "* نشأة هذا التصور", "ان العالم الاسلامي ، بسبب من تأثره بالحضارة الغربية ولوثاتها الجانحة اعتبر اوربا والعالم الغربي على ( الكنيسة ) وحدة من نفوذها السياسي ، بل وفصله (السلطة الاكليرية ) عن السلطة الزمنية ، اعتبر هذا قاعدة عامة مطردة يجب الصدور عنها في فصل الدين ( كل دين ) عن الدولة وجعل ما لقيصر لقيصر وما لله لله ..", "والواقع ان الجماهير كانت محقة في خروجها على الكنيسة في اوروبا ، ومطالبتها باقصاء رجال الدين عن"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0088.png"}, {"n": 89, "paras": ["المسرح السياسي بعد أن ذاقت من هؤلاء الامرين . فالظلم والقتل والشنق والحرق والسحل كانت من الوسائل التي لجأت اليها الكنيسة لتدعيم سلطانها .. وكانت الجماهير محقة - كذلك - لان الكنيسة في خروجها عن دائرة التعاليم والمبادىء الروحية والاخلاقية التي جاء بها عيسى عليه السلام، ودخولها المعترك السياسي ، واستغلالها لسلطانها الروحي في ميدان الحياة العامة ، تكون قد تجاوزت حدود صلاحياتها وتدخلت فيما ليس من شأنها .. فكان من حق الجماهير - عندئذ - ان تثور لتصحيح الاوضاع ، ولاعادة الامور الى نصابها ..", "* الجهل بالاسلام وبسبب من جهل المسلمين - كذلك - بخصائص دينهم وافاق شريعتهم .. وبانتقال القيادة الفكرية والسياسية منهم الى غيرهم .. وبانتقاض الحكم الاسلامي في العهد العثماني ، والذي كان على علاته ومساوئه مظهرا للحاكمية الاسلامية والوجود الكلي للاسلام بأسباب من هذه وغيرها أصبح تصور المسلمين وفهمهم للاسلام شيئا مشوها لا يتفق وجوهره وحقيقته في شيء ..", "* الاسلام من المحتوى الى التاريخ فالاسلام منهج حياة .. هكذا ينبغي أن يفهم ، وهكذا يجب ان يطبق .. وهو ثورة شاملة .. ثورة لا تقتصر على جانب من جوانب الحياة ، وانما تمتد الى كل جانب .. ثورة لا تعبر عنها ( كلمة او شعار ) بل هي تحويل ( كيفي ) للمجتمع وتغيير جذري لمرتكزاته الاساسية على كل صعيد .."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0089.png"}, {"n": 90, "paras": ["وتاريخ الاسلام - كذلك - لا يشهد قط اي فصل بين شيء يسمى دين وشيء يسمى دولة .. حتى ولا بين طبقة تسمى رجال دين واخرى تسمى رجال دولة ..", "ولقد بدت هذه الصورة واضحة مطردة من خلال حياة المسلمين في شتى العصور .. فقد كانوا رجال حرب ومحراب .. كانوا يؤمون الناس في محاريب المساجد ، ويقودونهم في ساحات الحرب والقتال ..", "وعلى هذا فان طبيعة الاسلام وتاريخه مختلفان تماما عن طبيعة المسيحية وتاريخها . ولكن خطأ الكثيرين ، الذين حكموا على الاسلام بجريره سواه ، انما يعود الى جهل هؤلاء بالاسلام كرسالة ، والى المؤامرات المفتعلة على الاسلام والتي عمدت على نشر هذه الاراء والتصورات القبيحة عن الدين ، وبثها في مناهج التعليم ووسائل الاعلام وعن طريق الارساليات والمؤسسات الثقافية الاجنبية . كخطة مدروسة هدفها ابعاد الاسلام عن قيادة الامة ، والذي هو سر قوتها والعمود الفقري في وجودها ..", "* الاسلام منهج حياة", "فالاسلام منهج حياة .. فهو عقيدة توضح التصور الصحيح للكون والانسان والحياة .. عقيدة تعرف هذا الانسان على نفسه ، وسر خلقه وسبب وجوده . وتحل بذلك عقدة من اخطر العقد في الحياة البشرية .", "وعلى اساس هذه العقيدة تقوم شريعة ونظام .. شريعة تنظم حياة الانسان في كافة شؤونها ..", "فالاسلام منهج متكامل الجوانب ، شامل النظرة .. فيه"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0090.png"}, {"n": 91, "paras": ["تنظيم علاقة الفرد بنفسه وبأسرته وبمجتمعه . وفيه بيان للأصول والقواعد التي تقوم عليها النظم والقوانين التي تحكم سير المجتمع والناس . فهو يجمع الى رقة التوجيه دقة التشريع ، والى جلال العقيدة جمال العبادة ، والى امامة المحراب قيادة الحرب . وبذلك يكون منهج حياة بكل ما في هذه الكلمة من معنى ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0091.png"}, {"n": 92, "paras": ["(٥) مَصَادِرُ المَنْهَجِ الإِسْلَامِي", "يحسن بالداعية ان يحاول في هذا الموضوع التأكيد على ان وقف مصادر التشريع الاسلامي على القرآن والسنة عامل اساسي في ثباته ورسوخه وعدم تعرضه للتحريف والتعديل والتأويل .. وان باطل النظم والمذاهب الوضعية كونها قاصرة في ذاتها اساسا ، وخاضعة للتفسيرات والتأويلات البشرية الشتى على كر العصور والدهور .. وليتناول الداعية مصادر المنهج الاسلامي بشيء من التفصيل بحسب الترتيب التالي :", "اولا : في المصادر الاصلية", "١ - الكتاب ( او القرآن ) : وهو كتاب الله المنزل على رسوله محمد صلى الله عليه وسلم باللفظ العربي ، المنقول الينا عن النبي صلى الله عليه وسلم نقلا متواترا بلا شبهة ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0092.png"}, {"n": 93, "paras": ["نزوله وجمعه :", "نزل القرآن على الرسول صلى الله عليه وسلم منجما خلال اثنتي وعشرين سنة ونيف . وكانت الآيات تكتب فور نزولها . وكان هذا المكتوب يوضع في بيت الرسول . وكان للقرآن كتاب معروفون قيل ان عددهم اثنان واربعون .", "جمع القرآن في خلافة عمر بن الخطاب رضي الله عنه . وامتازت عملية الجمع هذه بميزات اهمها : انهما جمعت القرآن كله على أدق وجوه البحث والتحري والتثبت العلمي ، وانها اقتصرت على ما لم تنسخ تلاوته ، وانها ظفرت باجماع الامة عليها وتواتر ما فيها .", "وفي خلافة عثمان بن عفان رضي الله عنه حدث الجمع الثاني للقرآن ، وقد امتازت هذه العملية بما يلي : انها اقتصرت على ما ثبت بالتواتر دون ما كانت روايته احادا وانها اهملت ما نسخت تلاوته ولم يستقر في العرضة الاخيرة . كما رتبت السور والآيات على الوجه المعروف الآن . انها جردت من كل ما ليس قرآنا ، كالذي يكتبه بعض الصحابة في مصاحفهم الخاصة شرحا لمعنى او بيانا لناسخ او منسوخ .", "خصائصه :", "١ - لفظ القرآن ومعناه من عند الله وليس للرسول فيه فيه سوى التبليغ . وعلي هذا لا تعتبر احاديث الرسول من القرآن لان الفاظها ليست من عند الله وان كانت معانيها موحى بها اليه . كما ان ترجمة القرآن الى غير اللغة العربية لا تعتبر قرآنا .", "٢ - انه نقل الينا نقلا متواترا ، بمعنى انه نقل عن النبي من قبل اقوام لا يحصون ولا يتصور العقل تواطأهم على"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0093.png"}, {"n": 94, "paras": ["الكذب ثم نقله عن هؤلاء آخرون - كذلك - حتى وصل الينا .", "٣ - انه وصل الينا دون زيادة او نقص ، لان الله تعالى تكفل بحفظه حيث قال عز وجل ( انا نحن نزلنا الذكر وانا له لحافظون ) .", "٤ - انه معجز بمعنى ان البشر جميعا عاجزون عن الاتيان بمثله ( قل لئن اجتمعت الانس والجن على أن يأتوا بمثل هذا القرآن لا يأتون ولو كان بعضهم لبعض ظهيرا ) .", "انواع احكامه : احكام القرآن ثلاثة انواع : اولا : احكام تتعلق بالعقيدة كالايمان بالله ورسله واليوم الآخر الخ .. ثانيا : احكام تتعلق بتزكية النفوس وتهذيبها وبيان الاخلاق الكريمة الواجب التحلي بها ، والاخلاق السيئة الواجب التخلي عنها . ثالثا : الاحكام المتعلقة بأقوال وافعال المكلفين فيما عدا النوعين السابقين . وهذه هي الاحكام العملية وتدخل في موضوع الفقه وهي قسمان : عبادات ومعاملات .", "٢ - السنة : وهي ثاني المصادر الاصلية للتشريع الاسلامي . والمراد بها ما صدر عن الرسول صلى الله عليه وسلم من قول او فعل او صفة او تقرير ..", "تدوين السنة : لم تدون السنة رسميا في عهد الرسول صلى الله عليه وسلم كما دون القرآن لاعتماد الصحابة على ذاكرتهم وانشغالهم"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0094.png"}, {"n": 95, "paras": ["بتدوين القرآن في تلك الفترة . ولكن هذا لا يعني ان شيئا لم يكتب من السنة ، اذ ثبت حدوث ذلك من بعض الصحابة حيث كانوا يدونون ذلك لانفسهم . في القرن الاول والثاني الهجريين قامت محاولات متعددة لتدوين السنة . وفي القرن الثالث قامت طائفة من العلماء الاجلاء بتدوين السنة وجمعها ، وتمييز صحيحها من غيره ، وفي طليعتهم الشيخان الجليلان البخاري ومسلم . وهكذا اصبحت للسنة مجاميع صحيحة منقحة كان في مقدمتها الكتب الستة : صحيح البخاري - صحيح مسلم - موطأ مالك - الجامع للترمذي - سنن أبي داوود - سنن النسائي - سنن ابن ماجة .", "علوم الحديث :", "ولقد كان من ثمار الجهود التي حققت التدوين ، وضع قواعد واصول علمية لتناول الاحاديث وتصنيفها ومنها :", "١ - علم مصطلح الحديث : ويعني هذا العلم بالقواعد الاساسية لقبول الحديث وتمحيصه وتصنيفه على ضوء ذلك الى صحيح او حسن او ضعيف او ما يتفرع من كل قسم من هذه الاقسام .", "٢ - علم الجرح والتعديل : وهو علم ميزان الرجال ويبحث في احوال الرواة وامانتهم وثقتهم وعدالتهم الخ ..", "الدليل على حجية السنة وانها مصدر للتشريع :", "١ - التصريح بأن النبي لا ينطق عن الهوى. قال تعالى ( وما ينطق عن الهوى ان هو الا وحي يوحى ) ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0095.png"}, {"n": 96, "paras": ["٢ - الامر بطاعة الرسول (قل اطيعوا الله والرسول) .", "٣ - جعل طاعة الرسول طاعة لله ( من يطع الرسول فقد اطاع الله ) .", "٤ - الامر باتباع ما يأتينا به الرسول ( وما اتاكم الرسول فخذوه وما نهاكم عنه فانتهوا ) .", "٥ - وجوب رد المتنازع فيه الى الله والى رسوله ( فان تنازعتم في شيء فردوه الى الله والرسول ان كنتم تؤمنون بالله واليوم الآخر خير واحسن تأويلا ) .", "٦ - وجوب تحكيم الرسول فيما يحصل من خلاف وقبول ما يحكم به ( فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في انفسهم حرجا مما قضيت ويسلموا تسليما ) .", "٧ - التحذير بالعذاب الاليم من مخالفة الرسول ( فليحذر الذين يخالفون عن امره ان تصيبهم فتنة او يصيبهم عذاب اليم ) .", "٨ - أعطي الرسول سلطة بيان احكام القرآن ، لان فيه احكاما مجملة تحتاج الى تفصيل حتى يصح بها التكليف ، قال تعالى ( وانزلنا اليك الذكر لتبين للناس ما نزل اليهم ) .", "انواع السنة باعتبار سندها :", "ويقصد بسندها رواتها ، وهي بهذا الاعتبار ثلاثة انواع اذا اتصل سندها . واذا لم يتصل سندها الى النبي بأن لم يذكر التابعي اسم الصحابي الذي روي السنة عن النبي فتسمى بالحديث المرسل . والانواع الثلاثة هي :"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0096.png"}, {"n": 97, "paras": ["اولا : سنة متواترة : وهي ما رواها عن النبي جمع لا يتصور تواطأهم على الكذب ولا يحصى عددهم . ثم نقلها عنهم جمع بهذه الصفة ايضا حتى بلغتنا . ومن هذا النوع السنن العملية التي بينت مقادير الزكاة وأفعال الحج وهيآت الصلاة وأركانها ، وهذه تفيد العلم اليقيني .", "ثانيا : سنة مشهورة وهي ما رواها عن النبي واحد او اثنان اي عدد لا يبلغ حد التواتر ثم اشتهرت فنقلها جموع التواتر في عصر التابعين وتابعي التابعين .", "ثالثا : سنة احاد : وهي ما يرويها عن النبي عدد لم يبلغ حد التواتر ولم تشتهر فيما بعد ، اي ليست سنة متواترة ولا مشهورة . وهذا النوع يفيد العلم الظني الراجح بصحة نسبتها الى النبي ويلزم العمل بها .", "انواع الاحكام التي جاءت بها السنة :", "النوع الاول : احكام موافقة لاحكام القرآن ومؤكدة لها مثل حديث ( لا يحل مال امرىء مسلم الا بطيب من نفسه ) فانه موافق ومؤكدة لقوله تعالى ( يا ايها الذين امنوا لا تأكلوا اموالكم بينكم بالباطل الا ان تكون تجارة عن تراض منكم).. ومثله ايضا ما جاء في السنة من النهي عن عقوق الوالدين وشهادة الزور وقتل النفس ونحو ذلك مما ورد في القرآن كذلك .", "النوع الثاني : احكام مبينة ومفصلة لمجمل القرآن ومن ذلك السنة التي بينت مقادير الزكاة ومقدار المال المسروق الذي تقطع به السارق .", "النوع الثالث : احكام مقيدة لمطلق الكتاب ومخصصه"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0097.png"}, {"n": 98, "paras": ["لعامه . فمن الاحكام ما يرد في القرآن مطلقا فتقيده السنة . فمن ذلك قطع يد السارق - جاءت مطلقة فقيدتها السنة بالرسغ اي تقطع اليد من الرسغ .", "النوع الرابع : احكام جديدة لم يذكرها القرآن لان السنة مستقلة بتشريع الاحكام وانها كالقرآن في ذلك . وقد ثبت عنه عليه السلام انه قال ( الا واني اوتيت القرآن ومثله معه ) ومن هذا النوع تحريم الحمر الاهلية وتحريم اكل كل ذي ناب من السباع ، ومخلب من الطير ، وكالحكم بشاهد ويمين ، ووجوب الدية على العاقلة وميراث الجدة ونحو ذلك.", "ثانيا : في المصادر التبعية", "٣ - الاجماع : وهو في اصطلاح الفقهاء وعلماء الاصول اتفاق المجتهدين من الامة الاسلامية في عصر من العصور بعد وفاة النبي على حكم شرعي .", "والاجماع مصدر للتشريع ودليل من ادلة الاحكام . وقد ثبت ذلك بنصوص كثيرة من الكتاب والسنة .", "مستند الاجماع : لا بد للاجماع من ان يستند الى دليل لان القول في الامور الشرعية من غير دليل خطأ والامة الاسلامية لا تجتمع على خطأ . ومستند الاجماع قد يكون نصا من كتاب الله او سنة نبيه كما قد يكون قياسيا ، كتحريم التزوج ببنات الاولاد مهما نزلت درجتهن فانه مستند الى نص القرآن ( حرمت عليكم امهاتكم وبناتكم ) ، وكالاجماع على تحريم شحم الخنزير قياسا على تحريم لحمه ونحو ذلك .", "٤ - القياس : وهو في اصطلاح العلماء الحاق مسألة لا نص على حكمها بمسألة ورد النص بحكمها في الحكم الذي"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0098.png"}, {"n": 99, "paras": ["ورد به النص لتساوي المسألتين في علة الحكم . فاذا وجدت مسألة ورد النص بحكمها وعرفنا علة الحكم ثم وقعت مسألة لم ينص على حكمها ولكن تشترك مع المسألة الاولى في علة الحكم فان المسألة الثانية تأخذ حكم المسألة الاولى . امثلة على القياس :", "- حكم شرب الخمر ( التحريم ) لورود نص بذلك . هذا الحكم ( الاسكار ) فكل شراب فيه هذه العلة يكون حكم التحريم ايضا قياسا على الخمر .", "- قتل الوارث مورثه ، مسألة ورد النص بحكمها وهو حرمان القاتل من الميراث ، وعلة الحكم هو استعجال الوارث الميراث قبل أوانه فعوقب بحرمانه . وقتل الموصى له الوصي مسألة لم يرد النص بحكمها ولكن فيها نفس العلة التي في المسألة السابقة وهي استعجال الشيء قبل اوانه ، فتأخذ نفس الحكم وهو حرمان الموصي له القاتل من حقه في الوصية كما حرم الوارث القاتل من حقه في الميراث . ه - الاستحسان : وهو في اصطلاح العلماء العدول عن قياس جلي الى قياس خفي لدليل يقتضي هذا العدول مثال على ذلك : ان المحجور عليه لسفه لا تصح منه التبرعات ومنها الوقف . ولكن استثني من هذا الاصل جواز وقفه على نفسه للمصلحة استحسانا . ووجه ذلك هو حفظ ماله وعدم صيرورته عالة على غيره .", "٦ - المصالح المرسلة : مصدر فقهي دل على اعتباره استقراء نصوص الشريعة واحكامها في الكتاب والسنة ، وعمل فقهاء الصحابة . وهذا المصدر يتسع للاحداث الجديدة والوقائع المتطورة ويجعل الفقه مرنا يستوعب مشاكل"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0099.png"}, {"n": 100, "paras": ["الحياة في كل عصر . وقد اخذ الفقهاء بهذا المصدر واستنبطوا الاحكام منه .", "فالمصالح المرسلة اذن هي المصالح التي لم يشرع الشارع احكاما لتحقيقها ولم يقم دليل معين على اعتبارها أو الغائها . فكل واقعة ليس فيها نص ولا اجماع ولا قياس ولا استحسان وفيها مصلحة للناس ، يجوز للمجتهد ايجاد الحكم المناسب لتحقيقها اي لتحقيق هذه المصلحة للناس .", "امثلة على المصالح المرسلة :", "- جمع القرآن في مصحف واحد من قبل ابي بكر .", "- تدوين الدواوين من قبل عمر .", "- تضمين الصناع ما يهلك بأيديهم من أموال الناس.", "- حق ولي الامر في فرض الضرائب على الاغنياء عند الضرورة ونحو ذلك", "٧ - سد الذرائع : الذرائع معناها الوسائل . فاذا كانت الوسائل مفضية الى الحرام والفساد كانت هذه الوسائل محرمة ووجب سدها اي منعها حسما لمادة وسائل الفساد . وان كانت هذه الوسائل تؤدي الى أمر مطلوب في الشرع كانت هذه الوسائل مطلوبة ايضا . فالذرائع تسد وتمنع اذا كانت تفضي الى الفساد ، وتجب وتفتح اذا كانت تفضي الى المصالح. ولما كان اكثر ما يطلق اسم الذرائع على الافعال والطرق المؤدية الى الشر والفساد فقد سميت سد الذرائع .", "حجية هذا الاصل : واصل سد الذرائع مشهود له بالصحة بدلائل الكتاب"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0100.png"}, {"n": 101, "paras": ["والسنة وعمل الصحابة . فمن الكتاب قوله تعالى ( ولا تسبوا الذين يدعون من دون الله فيسبوا الله عدوانا بغير علم ) ومن السنة نهي النبي صلى الله عليه وسلم عن ( الاحتكار ) سدا لذريعة الربا . فسد الذرائع اصل معتبر ومصدر فقهي تستقي منه الاحكام وقد اخذ به الائمة المجتهدون وكان اكثرهم اخذا بهذا المصدر الامام مالك والامام أحمد بن حنبل ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0101.png"}, {"n": 102, "paras": ["مراجع مقترحة للدراسة", "١ - المدخل لدراسة الشريعة الاسلامية - للدكتور عبد الكريم زيدان .", "٢ - تاريخ التشريع الاسلامي - للمرحوم محمد الخضري .", "٣ - السنة ومكانتها في التشريع الاسلامي - للمرحوم الدكتور مصطفى السباعي .", "٤ - الاجماع في الشريعة الاسلامية - للاستاذ علي عبد الرازق .", "٥ - علوم اصول الفقه - لمحمد عبد الله ابو النجا ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0102.png"}, {"n": 103, "paras": ["هذا الكتاب هو الجزء الثاني من كتاب \"المنهاج\" للإمام النووي، وهو كتاب في الفقه الشافعي."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0103.png"}, {"n": 104, "paras": ["(٦) في خصائص المنهج الإسلامي", "على الاخ الداعية في هذه الحلقة ان يبين للمدعو الخصائص التي امتاز بها المنهج الاسلامي عن سواه من المناهج الوضعية . وان هذه الخصائص هي فواصل جذرية ، وفوارق اساسية بينه وبين الاتجاهات والمذاهب الاخرى . وان من هذه الخصائص :", "اولا - ربانيته :", "فالمنهج الاسلامي منهج الهي ، وليس مخاض عقل بشري شأن المذاهب الوضعية . وهذه الصفة تؤكد قابليته للحياة وقدرته على استيعاب مشاكلها المتجددة المتطورة ابدا، انسجاما مع « القدرة » التي صدر عنها ، والتي لا يعزب عنها مثقال ذرة ، وقد احاطت بكل شيء علما . ( افمن يخلق كمن لا يخلق افلا تذكرون ؟ ) .", "وان بشرية المناهج الوضعية هي جرثومة فنائها الاولى، وهي النقطة التي تنشأ عنها وتتوالد كافة مثالب تلك المناهج وعيوبها ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0104.png"}, {"n": 105, "paras": ["ثانيا - شموله :", "والمنهج الاسلامي يمتاز بشموله وكليته واستيعاب نظرته وتصوره لكافة شؤون الحياة . ففيه تنظيم علاقة الفرد بنفسه ، وعلاقته بخالقه ، وعلاقته بأسرته ، وعلاقته بمجتمعه، وعلاقة مجتمعه به . وفيه بيان للاصول والقواعد التي تحكم سير المجتمع والناس وفق نظرة الاسلام للكون والانسان والحياة .", "وعظمة ما في هذا الشمول ، انه متوافق منسجم في جزئياته وكلياته مع بعضه أولا ، ومع المرتكز الاعتقادي الاساسي الذي ينبثق عنه .", "وقد يجد المرء في العصر الحديث نظما وضعية فيها شيء من الشمول لا الشمول كله . وهو مع هذا شمول غير متجانس ولا متوافق . اذ انه خليط من نظرات ونظريات ونظم واحكام شتى جمعت جمعا محدثا طارئا ، ولم تنبثق انبثاقا طبيعيا عن مفهوم عقيدي واحد ..", "وعظمة ما في هذا الشمول كذلك انه شمول توزعت جزئياته بالقسطاس المحقق للتوازن بين مختلف الحاجات والمطالب العضوية والنفسية ، مما لا يمكن ان يحدث تضخما في جانب على حساب جانب . فكان توزيعا فطريا محققا التناسق والتوافق والاطمئنان والاستقرار في حياة الكائن الانساني .", "ثالثا - انقلابيته :", "ومن خصائص هذا المنهج ايضا انه منهج انقلابي يرفض الترقيع والاصلاح الجزئي ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0105.png"}, {"n": 106, "paras": ["فهو يرفض تصحيح بعض شؤون المجتمع الجاهلي ولا يستسيغ التعايش في هذا المجتمع الا لمحاولة هدمه واقامة مجتمع اسلامي مكانه .", "وهو يرفض ان يكون مصدرا من مصادر التشريع في بلد ما ، ولا يرضى الا بأن يكون المصدر الوحيد للتشريع .", "وهو يرفض ان يحكم ببعض جزئيات تشريعه ، ولا يرضى الا بأن يحكم بتشريعه كله .", "وهو يرفض ان ينص على ان دين الدولة الاسلام في بلد ، ولا ينص على ان الاسلام هو نظام هذا البلد ومنهجه في الحياة .", "فطبيعة المنهج الاسلامي تأبى التجزؤ ولا ترضى بغير الكلية في اخذه او تركه ( افتؤمنون ببعض الكتاب وتكفرون ببعض فما جزاء من يفعل ذلك منكم الا خزي في الحياة الدنيا ويوم القيامة يردون الى اشد العذاب وما الله بغافل عما تعملون ) .", "رابعا - استمراريته :", "ومن خصائص المنهج الاسلامي قابليته وقدرته على استيعاب الحياة وقيادتها وريادتها في اية مرحلة من مراحلها.", "فقد يتأتى لنظام وضعي ان ينجح لفترة معينة من الزمن وفي حدود معينة من النجاح ، ثم لا يلبث ان يخفق ويفلس وتظهر مثالبه وعيوبه . أما المنهج الاسلامي فان فيه من مقومات الاستمرار وصفات المرونة ما يجعله صالحا لامامة البشرية في مختلف العصور والدهور ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0106.png"}, {"n": 107, "paras": ["خامسا - عالميته :", "ومن خصائص المنهج الاسلامي انه منهج عالمي ، بمعنى ان في تشريعاته القدرة على استيعاب الحياة ومشاكلها المتجددة في كل مكان ، وبالتالي القدرة على تنظيم الحياة في أية بقعة من بقاع الارض .", "فالمنهج الاسلامي ليس وليد بيئة معينة ، او ردة فعل لسوء اوضاع بيئة معينة ، شأن كل المناهج البشرية الوضعية وانما هو المنهج الذي اريد له ان يكون منهج البشرية جمعاء في مختلف ديارها واقطارها ، ومصدره الالهي ارسى في قواعده واصوله من سعة الافاق وكلية الاحاطة ما جعله عالميا قادرا على الحياة والخصب والابداع في كل مكان .", "وبهذه الخصائص التي يمتاز بها المنهج الاسلامي عن سائر المناهج الوضعية يكون هو المنهج الوحيد المرشح لحل مشكلات الانسان وانقاذه من التناقض الذي يعيش فيه ، وبالتالي انقاذ البشرية من الانحدار السحيق الذي تهوي اليه . ( ما كان حديثا يفترى ولكن تصديق الذي بين يديه وتفصيل كل شيء وهدى ورحمة لقوم يؤمنون ) ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0107.png"}, {"n": 108, "paras": ["* كتب مقترحة للمطالعة حول موضوع ( خصائص المنهج الاسلامي )", "- المرونة والتطور في التشريع الاسلامي تأليف المرحوم الدكتور مصطفى السباعي", "- المدخل لدراسة الشريعة الاسلامية تأليف الدكتور عبد الكريم زيدان", "- خصائص التصور الاسلامي للشهيد سيد قطب"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0108.png"}, {"n": 109, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0109.png"}, {"n": 110, "paras": ["الخطوط الكبرى للمنهج الإسلامي", "١ - في نطاق العقيدة :", "* اثبات وجود الله", "* اثبات عقيدة الآخرة", "* عقيدة القضاء والقدر"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0110.png"}, {"n": 111, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0111.png"}, {"n": 112, "paras": ["(۷) في اثبات وجود الله", "ان اول مشكلة يقتضي أن يعالجها الداعية في نطاق دعوته الى الاسلام ، وان يقدم لها الحلول المنطقية اللازمة ، هي مشكلة انكار وجود الله .. وما لم يتمكن الداعية من حل هذه المشكلة وتقديم الادلة والقرائن الدامغة على وجود الله ، فان كل محاولاته الجانبية ستذهب عبثا .. ويخطئ كل من يظن ان بامكانه اقناع الملاحدة ومنكري وجود الله بأن الاسلام منهج حياة ، ثم يلزمهم بالعمل لاستئناف الحياة الاسلامية من جديد عن غير ذلك الطريق، كأن يحدثهم عن العدالة الاجتماعية والمساواة الانسانية ، وغير ذلك من المبادىء التي جاء بها الاسلام .", "ان الالحاد والكفر وانكار وجود الله ظواهر قديمة قدم هذا الكون .. ولم تكن الوظيفة الاولى من ارسال الرسل والانبياء سوى حل هذه المشكلة ، وتقديم التصور العقائدي الصحيح عن الكون والانسان والحياة . من اجل ذلك كانت الدعوة الى الايمان بالله المنطلق الاساسي والاول لدى الانبياء جميعا وبدون استثناء . ودليل هذا قائم في كل سورة من"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0112.png"}, {"n": 113, "paras": ["سورة القرآن حكمت قصة رسول أو نبي . نسوق من ذلك على سبيل المثال الآيات التالية :", "( لقد أرسلنا نوحا الى قومه فقال يا قوم اعبدوا الله ما لكم من اله غيره اني اخاف عليكم عذاب يوم عظيم ) ، ( والى عاد اخاهم هودا قال يا قوم اعبدوا الله ما لكم من اله غيره أفلا تتقون ) ( والى ثمود اخاهم صالحا قال يا قوم اعبدوا الله ما لكم من اله غيره ) ، ( والى مدين أخاهم شعيبا قال يا قوم اعبدوا الله مالكم من اله غيره قد جاءتكم بينة من ربكم ) ، ( وابراهيم اذ قال لقومه اعبدوا الله واتقوه ذلكم خير لكم ان كنتم تعلمون ) .", "واليوم يشهد العالم اجمع « ردة » عن الايمان بالله وكفرا جماعيا وعالميا لم يعرف لهما مثيل من قبل . ولقد ساعد على هذا عوامل كثيرة منها :", "١ - انعدام وجود واقع اسلامي صحيح ولو في قطر واحد من الاقطار ، يطبق في الحكم الاسلامي ، وتسوده شريعة « لا اله الا الله » مما يمكن ان يعتبر نموذجا عمليا للمنهج الالهي الذي يقوم اساسا على الايمان بالله ، وما يمكن أن يوفره هذا الواقع من امكانات ووسائل علمية واعلامية وفنية لنقض الاتجاهات والمذاهب المادية الالحادية ودحض آرائها ومزاعمها .", "٢ - قيام اكثر من « واقع الحادي » في العالم .. بل قيام معسكر برمته تلتقي فيه عشرات الدول على فلسفة مادية تقوم اساسا على انكار وجود الله . وبالتالي تسلل هذه الفلسفة الى العالم الاسلامي وتبني عدد من اقطاره لها . واذا كان يقال - كوسيلة لذر الرماد في العيون - : ان هذه الاقطار تتبنى النظم الاقتصادية لتلك الفلسفة دون النظرية"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0113.png"}, {"n": 114, "paras": ["الكونية .. ولو اننا سلمنا بصحة هذا الادعاء كذلك ، فان هذه النظم الاقتصادية ذاتها قائمة اصلا على النظرية المادية التي تنكر وجود الله ولا تعترف الا بالمادية وحدها . وبديهي ان ما فسد اصله فسد فرعه . ولقد تأكدت هذه النتيجة عمليا حيث غمرت موجة الالحاد بلادنا وعصفت بمفاهيمها وتصوراتنا واطفأت شعلة الايمان والعقيدة في اجيالنا . ومن هنا وجب على الاخ الداعية ان يبدأ اول ما يبدأ حواره مع الآخرين باثبات وجود الله الذي هو الطريق الطبيعي للايمان بالاسلام ، وللالتزام بأحكامه ومبادئه وللنهوض بتكاليف الجهاد في سبيله . وان يكون حواره منظما ومركزا وواضحا .. وارى ان يتقيد بمعالجة النقاط التالية ما وسعه ذلك :"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0114.png"}, {"n": 115, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0115.png"}, {"n": 116, "paras": ["العناصر الأساسية لبحث الإيمان بالله وإثبات وجوده", "ان من واجب الاخ في نطاق الدعوة الى الاسلام ان يبدأ حواره مع الآخرين باثبات وجود الله ، الذي هو الطريق الطبيعي للايمان بالاسلام ، وللالتزام باحكامه ومبادئه ، وللنهوض بتكاليف الجهاد في سبيله . وان يكون حواره منظما ومركزاً واضحاً . وفيما يلي العناصر الاساسية التي يجب ان يعتمدها اساساً لبحثه :", "اولا : الفرضيات الثلاث لوجود هذا الكون", "ان هنالك فرضيات ثلاث لوجود هذا الكون ونشأته :", "١ - ان يكون هذا الكون قد أوجد نفسه بنفسه .", "٢ - ان يكون قد وجد بالمصادفة .", "٣ - ان يكون وراء وجوده قوة .", "* اما الاحتمال الاول فلا يقول به عاقل لان الموجودات لا يكون عندها القدرة على الفعل الا بعد وجودها . فكيف يصدر عنها فعل الايجاد وهي بعد لما توجد ؟"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0116.png"}, {"n": 117, "paras": ["وهذا الاحتمال مرفوض بداهة لاصدامه بمبدأ ( السببية ) وهو أول مبادىء العقل الذي ينفي قيام اي حادث من غير سبب ، والذي يجعل وجود مسبب لنشأة هذا الكون امرا قطعيا لا جدال فيه . ويذكر المؤرخون ان بعض الزنادقة طلبوا موعدا من أبي حنيفة رضي الله عنه ليجادلوه في الله . ولما حان الموعد تأخر عنهم . ثم قدم اليهم بعد ان يئسوا من مجيئه . فعاتبوه في التأخر ، فقال لهم معتذرا لقد قدمت اليكم في الموعد المحدد ولكنني لبثت طويلا على شاطىء دجلة باحثا عن صاحب زورق يجتاز بي النهر : فما وجدت . ولما يئست وهممت بالرجوع رأيت الواحا من الخشب قادمة بنفسها ، وجعلت تنضم الى بعضها حتى صارت بين يدي مركبا حسنا ، فركبته وقطعت به النهر ، وقدمت اليكم . فقال الزنادقة جميعا لابي حنيفة اتهزأ بنا ؟ وهل يمكن أن تأتي الواح بنفسها فتكون زورقا ؟ فقال لهم : ( هذا ما اجتمعتم لتجادلوني به . فاذا كنتم لا تصدقون ان زورقا يصنع نفسه فكيف تريدون مني ان اصدق ، بل كيف تصدقون انتم في عقولكم ان هذا الكون المتقن العجيب قد جرت حوادث تغييراته بنفسه دون خالق عظيم ؟ فبهت الزنادقة ، وقامت عليهم الحجة الدامغة ، واسلموا على يده رضي الله عنه . ( وبذلك يكون الاحتمال الاول مرفوض بداهة ) .", "* وأما الاحتمال الثاني فيقول به الماديون .. والحقيقة انه لا وجود للمصادفة. والانسان يلجأ اليها اذا جهل السبب. حتى اذا ادركه انكر القول بالمصادفة . وقد ضرب العالم ( كريس موريسون ) مثلا بسيطا لدحض (مبدأ المصادفة) فقال : ( خذ عشر قطع من الخشب صغيرة ومتساوية الاحجام . وضع عليها ارقاما مسلسلة من ( ١ الى ١٠ ) ثم ضعها في جيبك وهزها هزا جيدا . ثم حاول ان تسحبها من"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0117.png"}, {"n": 118, "paras": ["جيبك بحسب ترتيبها من ( ١ - ١٠ ) .. ان فرصة سحب القطعة رقم واحد ستكون بنسبة ١ الى ١٠ وفرصة سحب القطعتين ١ و ٢ متتابعتين ستكون بنسبة ١/١٠٠ وفرصة سحب رقم ١ و ٢ و ٣ متتاليات ستكون بنسبة ١/١٠٠٠ وهكذا حتى تصبح فرصة سحب القطع كلها بترتيبها الاول من ١ الى ١٠ هي بنسبة واحد الى ١٠ بلايين ؟", "والغرض من هذا المثل البسيط هو ان نبين كيف تزداد النسب بشكل هائل ضد المصادفة . لهذا كان لا بد للحياة فوق ارضنا من شروط جوهرية عديدة بحيث يصبح من المحال توافرها وتتابعها وانتظامها بمجرد المصادفة ..", "وهكذا نجد أن القول بالمصادفة بالنسبة لنظام الوجود الشامل المحكم لا يقول به الا جاهل بعيد عن التحقيق ، او مكابر يرى الحق ويعرض عنه . وانه يكفي التأمل في بعض آيات الوجود بالطريقة العلمية حتى تزول ( المصادفة ) واوهامها وتحل محلها الاحكام المعللة باسبابها .", "وفيما يلي مختارات من الامثلة على دقة التنظيم الكوني مما يدحض القول ( بالمصادفة ) :", "١ - لو كانت قشرة الارض أسمك مما هي عليه لامتص ثاني اوكسيد الكربون الاوكسيجين ولما كانت حياة .", "٢ - ولو كان الهواء اقل ارتفاعا مما هو عليه فان بعض الشهب التي تحترق بالملايين كل يوم في الهواء الخارجي كانت تضرب في جميع اجزاء الكرة الارضية وتشعل كل شيء قابل للاحتراق .", "٣ - ولو ان شمسنا اعطت نصف اشعاعها الحالي لكنا تجمدنا . ولو انها زادت بمقدار النصف لكنا رمادا منذ زمن بعيد ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0118.png"}, {"n": 119, "paras": ["٤ - ولو كان قمرنا يبعد عنا ( ٢٠٠٠٠ ) ميلا بدلا من بعده الحالي لكان المد يبلغ من القوة بحيث ان جميع الاراضي تغمر مرتين في اليوم بماء جارف يزيح الجبال نفسها.", "٥ - ولو كان ليلنا اطول مما هو عليه الان عشر مرات لاحرقت شمس الصيف الحارة نباتنا في النهار ، وفي الليل يتجمد كل نبات الارض .", "٦ - ولو كان الاوكسيجين بنسبة ٥٠ بالمئة او اكثر في الهواء بدلا من ٢١ بالمئة فان جميع المواد القابلة للاحتراق تصبح عرضة للاشتعال عند اول شرارة ..", "٧ - ولو كانت مياه المحيطات حلوة لتعفنت وتعذر معها الحياة على الارض . حيث ان الملح هو الذي يمنع حصول التعفن والفساد ، ولولا ان الكلور يتحد مع الصوديوم لما كان ملح وبالتالي ما كانت حياة ..", "٨ - ولو لم تكن قوانين الجاذبية موجودة فمن اين تلتقي وتتماسك الذرات وجزيئاتها ؟", "٩ - ولو كان محور الارض معتدلا بل هذا الميل الحالي لظل الصيف دائما والشتاء ابدا .", "١٠ - ولو كانت الارض كعطارد لا يدير الا وجها واحدا نحو الشمس لما عاش احد حيث الليل الدائم او النهار الدائم ولما كانت حياة .. ( وبذلك يكون القول بالمصادفة مرفوضا كذلك ) .", "* ويبقى الافتراض الثالث .. الافتراض الحق الذي يقول به المؤمنون ، الذي تقبله العقول ، وهو أن وراء هذا الكون ( خالق ) ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0119.png"}, {"n": 120, "paras": ["ثانيا : قوة الانسان الادراكية", "ورب قائل يقول : اذا سلمنا بالافتراض الثالث وهو ان وراء هذا الكون مكون هو الله افلا يتعين أن نراه بحواسنا؟", "وللجواب على هذا التساؤل ينبغي ان نبين للسائل ان حواسنا هي السبيل الوحيد للتعرف على الوجود وهي من حولنا منافذ قصيرة المدى محدود كما وكيفا .. من ذلك:", "١ - ان الفضاء مملوء بالصور التي لا نستطيع ان نراها بابصارنا لعدم توافق ذبذبتها وذبذبة ابصارنا ٢ - وانه مملوء بالاصوات التي فوق أو دون مستوى سمعنا يمكننا أن نسمعها بواسطة اجهزة الكترونية خاصة ٣ - وان التراب مملوء بالمعادن لا تستطيع حواسنا ان تدركها او تميزها دون اجهزة خاصة .", "فاذا كانت حواسنا عاجزة عن ادراك الاشياء الحسية الصغيرة القريبة التي حولنا فهل عساها قادرة على الاحاطة بما وراء الطبيعة من أمور غريبة كبرى ؟", "ومن هنا وجب على الانسان ان يسلم بوجود اشياء - من خلال اثارها - لان حواسه قد لا تساعده على لمسها او رؤيتها ..", "ثالثا : الغاية من اثبات وجود الله ؟", "١ - رد القول (بمادية الحياة) وبالتالي رد كل الافكار والمذاهب المنبثقة عن ذلك ..", "٢ - اثبات ان الايمان بالله يستتبع طاعته وامتثال اوامره وتأكيد الحاجة الى هداه ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0120.png"}, {"n": 121, "paras": ["٣ - اثبات ان طاعة الله وامتثال امره يستلزم الايمان بانبيائه والتصديق بكتبه .", "٤ - اثبات ان الاسلام اخر الرسالات ، وانه منهج حياة، وان الايمان به يقتضي العمل له والجهاد من اجله .", "رابعا : دحض القول بأزلية الوجود :", "ورب قائل ان الموجودات قديمة لا أول لها .. ولمناقشة هذه الفرضية لابد من التساؤل عن تنوع هذه الموجودات .. اذ الملاحظ ان فيها ما هو جامد لا حياة فيه .. ومنها ما هو حي ينمو ويتكاثر .. ومنها ( وهو الانسان ) كائن حي عاقل .. هذا التنوع في الموجودات هل هو قديم ؟ ام انه طرأ على الموجودات بعد زمن معين ؟ فان كان التنوع قديما في العالم فما هو المبرر العقلي المقنع بذلك ؟ ولماذا تكون بعض الموجودات عاقلة مفكرة حية ، ويكون بعضها الآخر حيا من غير قدرة على التفكير والعقل .. ويكون بعضها الاخير جامدا لا حياة عنده ولا تفكير ؟؟", "المبرر العقلي الوحيد هو وجود قوة اخرى وراء هذا العالم المادي هي التي ارادت هذا التنوع لغاية معينة .. وهذا يقودنا الى التسليم بوجود الله سبحانه وتعالى .", "واذا كان التنوع طارئا .. اي ان الموجودات كلها كانت شيئا واحدا ، ثم طرأ عليها التنوع بعد مدة من الزمن ، فلا بد من التساؤل : هل طرأ هذا التنوع فجأة أم كان نتيجة تطور استغرق"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0121.png"}, {"n": 122, "paras": ["فترة زمنية طويلة ؟ فان كان تنوع الموجودات طرأ على العالم فجأة فما هو السبب ؟ ليس هناك من سبب يقبله العقل الا ان يكون حدوث هذا التنوع نتيجة ارادة وراء هذا الكون ، وهي أقوى من هذا العالم ، بحيث تملك القدرة على التأثير فيه .. وهذا يقودنا ايضا الى التسليم بوجود الله سبحانه وتعالى ..", "وأما ان كان هذا التنوع قد طرأ على العالم بالتطور خلال احقاب طويلة من الزمن - كما تذهب الى ذلك المادية الجدلية - فيرد على ذلك بما يلي :", "أولا : ان ظاهرة التطور نفسها تحتاج الى تفسير عقلي مقبول . فلماذا كانت الموجودات تملك خاصة التطور ولم تكن جامدة ؟ الا يقودنا هذا التساؤل الى التسليم بوجود اله وهب هذه الموجودات خاصة التطور للوصول الى تحقيق غاية معينة ؟", "ثانيا : ثم ان التطور كما هو ملاحظ ليس تطورا مطلقا، ولكنه مقيد ببقاء الموجود في حدود خواصه الاصلية .. ولم يعرف التاريخ الانساني منذ الاف السنين ، ان تطورا قد حصل فحول حيوانا الى انسان ، او حول التراب الى حيوان .. ان التراب قد يتحول الى صخر . والصخر قد يتفتت الى تراب بفعل ظروف وعوامل معينة ، وقد تخرج دودة حية من ثمرة ، ذلك لان خواص الحياة موجودة اصلا في الثمرة ..", "والملاحظ ان هذا التطور مقيد في حدود هذه الاشياء لا يخرج عنها .. كما وانه ملاحظ ايضا ان الانسان خلال الاف السنين لم يحصل له تطور غير شيئا من حاجاته والاستفادة من خصائصه وصفاته .."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0122.png"}, {"n": 123, "paras": ["فاذا كان تنوع الموجودات قد حصل بالتطور فلماذا توقف هذا التطور منذ آلاف السنين ؟", "الا يضطرنا هذا الى الاعتراف بوجود قوة عاقلة فريدة هي التي طورت الموجودات حتى كان منها هذا النوع .. واذا كان التطور نفسه يحتاج الى الله فلماذا لا نعترف اصلا بأن الله هو الذي خلق الموجودات من التنوع الذي نراه ؟", "يتبين من هذا ان القول بقدم الموجودات لا يعفي الانسان من ضرورة الاعتراف بوجود الله . واذا اضفنا الى ذلك ان هذا الاحتمال ليس سوى ظن لا يدل على صحته اي برهان ، ادركنا انه محاولة للتهرب من الاعتراف بوجود الله يمليها عجز الانسان عن معرفة مبدأ الخلق وسببه ..", "( مراجع هذا البحث )", "* تعريف عام بدين الاسلام : للطنطاوي .", "* العقيدة الاسلامية واسسها : لحبنكة .", "* الله : لسعيد حوى .", "* كبرى اليقينيات الكونية : للبوطي ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0123.png"}, {"n": 124, "paras": ["(۸) في إثبات عقيدة الآخرة", "على الاخ الداعية ان يبين للمدعو من خلال هذا الموضوع الغاية من الحياة كما قررها الاسلام . وانها اي في هذه الحياة هي طريقنا الى الآخرة .. وان الله لم يخلقنا فيها عبثا وبدون غاية كما يعتقد الملاحدة والماديون ، وانما لبلونا فيما اتانا ، وان الانسان مرهون بعمله صالحا كان ام طالحا . وان الآخرة هي دار القرار ، فاما الى الجنة واما الى النار .. وان هذه العقيدة وادراكها وايمان بها ودوام التفكير فيها هي العاصمة من القواصم وهي المانعة من الزلل والانحراف . وليكن تبسيطه للموضوع على الشكل التالي :", "اولا- في قيمة الاعتقاد بالاخرة : ان الايمان بالاخرة ركن اساسي من اركان العقيدة الاسلامية وثمرة من ثمرات الايمان بالله ، ومن الفواصل الجذرية ونقاط الافتراق بين هذه العقيدة وبين العقائد المادية. فالاسلام حين يقرر ان الله خالق الكون وموجده وان الكون لم يوجد صدفة او نتيجة تفاعلات كيميائية مادية مجردة"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0124.png"}, {"n": 125, "paras": ["يكون قد خطا بالانسان الخطوة الاولى الاساسية في طريق المعرفة والادراك الكونيين .", "ومن هذه النقطة بالذات تنشأ وتنبثق سائر نقاط الادراك والمعرفة ، وبالتالي ينعكس السلوك والتصرف .", "فاذا امن الانسان بوجود الله ، وجب عليه ان يؤمن بعظمته وقدرته وسائر صفاته . وانه سبحانه اجل من ان يخلق شيئا عبثا .. وان هذا الانسان المخلوق ، انما خلق بأمر الله ليكون عامل اصلاح وتعمير لا معول افساد وتدمير ( تبارك الذي بيده الملك وهو على كل شيء قدير . الذي خلق الموت والحياة ليبلوكم ايكم احسن عملا وهو العزيز الغفور ) وانه في نهاية هذه الرحلة سيواجه المصير الذي ارتضاه لنفسه وقرره بنفسه ، بملء حريته ( فاما من طغى وآثر الحياة الدنيا فان الجحيم هي المأوى . واما من خاف مقام ربه ونهى النفس عن الهوى فان الجنة هي المأوى ) .", "هذه العقيدة تشد الانسان شدا نفسيا الى اعلى دائما .. فهو لا يرى ان الدنيا هي كل شيء .. وانما يراها طريقا الى الاخرة . ويرى عمله مركبة الى دار القرار . وان مكانه في تلك الدار مرهون بما قدمت يداه وبما تزوده من دنياه ( من كان يريد العاجلة عجلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم يصلاها مذموما مدحورا .. ومن اراد الاخرة وسعى لها سعيها وهو مؤمن فاولئك كان سعيهم مشكورا ) .", "هذا الشعور الدافق من شأنه ان يلعب دورا كبيرا في توجيه حياة الانسان وصونها من كل ما يؤذيها او يفسدها .", "أما المنكرون لوجود الله فانهم منكرون للبعث مكذبون به كذلك .. وانكارهم للبعث وتكذيبهم به من شأنه ان يجعل"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0125.png"}, {"n": 126, "paras": ["كل تصوراتهم وتصرفاتهم تصدر عن قيم مادية بحتة ، وبالتالي يجعل الدنيا بداية تفكيرهم ونهايته . وهذه بلا شك نقطة افتراق اساسية بين المذاهب المادية وبين الاسلام .", "ثانيا - قيمة الدنيا من الآخرة :", "ثم ان على الاخ ان يعرض لحقيقة الدنيا والمبلغ قيمتها من الآخرة . وان نعيم الدنيا لا يعدل شيئا من نعيم الآخرة وان نعيم الآخرة هو النعيم ( وما هذه الحياة الدنيا الا لهو ولعب وان الدار الآخرة لهي الحيوان لو كانوا يعلمون ) ثم ليستدل على ذلك - كذلك - بحديث الرسول صلى الله عليه وسلم : « يؤتي بأنعم اهل الدنيا من اهل النار يوم القيامة فيصبغ في النار صبغة ثم يقال : يا ابن ادم هل رأيت خيرا قط ؟ هل مر بك نعيم قط ؟ فيقول : لا والله يا رب . ويؤتي بأشد الناس بؤسا في الدنيا من اهل الجنة ، فيصبغ صبغة في الجنة فيقال له : يا ابن ادم هل رأيت بؤسا قط ؟ هل مر بك شدة قط ؟ فيقول : لا والله يا رب ما مر بي بؤس ولا رأيت شدة قط » رواه مسلم .", "ان هذا التصور لحقيقة الدنيا من شأنه ان يجعل الانسان غير متعلق بها او متهالك عليها . وبذلك يكون ديدنه في دنياه اتيان كل ما من شأنه ارضاء الله والتزود لاخراه متمثلا في ذلك وصية الرسول الاعظم صلى الله عليه وسلم : « كن في الدنيا كأنك غريب أو عابر سبيل » .", "ومتى تم للانسان استنهاض نفسه من ترابيتها تم له دفعها والارتقاء بها في مدارج الكمال الانساني .. وبذلك تتحقق ولادة الثمرة الاساسية من تفاعل العقيدة مع النفس الا وهي مكارم الاخلاق ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0126.png"}, {"n": 127, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0127.png"}, {"n": 128, "paras": ["(۹) فِي عَقِيدَةِ القَضَاءِ وَالقَدَرِ", "في هذه الحلقة على الاخ أن يشرح للمدعو عقيدة القضاء والقدر بأسلوب مبسط واضح ... ذلك أن للمفهوم الخاطيء عن القضاء والقدر انعكاسات خطيرة وآثار سيئة في حياة الناس .. لذا كان من واجب الدعاة أن يولوه أهمية بالغة وان يجعلوه في مطالع مناقشة موضوعات العقيدة .", "رسالة القضاء والقدر", "من المطاعن التي يوجهها اعداء الاسلام اليه ان عقيدة القدر هي التي كانت من اهم اسباب ضعف المسلمين وتخلفهم لانها تعطل المدارك والقوى وتميل بمعتقدها الى الكسل والتواكل انتظارا لما سيأتي به الغيب ..", "١ - الجبرية مفهوم خاطيء :", "ان الاعتقاد بان الله تعالى كتب على الانسان كل تصرفاته وافعاله .. فضلاله ان ضل ، وهداه ان اهتدى ، واستقامته ان استقام، وانحرافه ان انحرف، كل ذلك مكتوب عليه منذ الازل لا يملك دفعه ولا يستطيع منعه .. فهو مسير"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0128.png"}, {"n": 129, "paras": ["معدوم الإرادة مسلوب التفكير تجري به سفينة الأقدار في بحر زاخر وهو لا يستطيع ان يقدم لنفسه نفعا ولا ضرا .. ان هذا الاعتقاد ( الجبري ) يتنافى في الواقع مع مفهوم الاسلام لعقيدة القضاء والقدر كما يخالف عقيدة السلف الصالح وبالتالي يتناقض مع ابسط قواعد العدل الالهي .. لانه لو كان الانسان مجبرا في كل ما يفعل لما كان هنالك من مبرر لوجود العقل والادراك ، ولما كان هنالك من مبرر لوجود الشرائع والقوانين ، ما دام الانسان ملزما بفعل ما يفعل دونما ارادة او اختيار ؟", "والحق ان الرسول صلى الله عليه وسلم عندما سئل عن الايمان ذكر من جملة اركانه : وان تؤمن بالقدر خيره وشره من الله . ومعنى ذلك ان كلا من الخير والشر يجري في الكون بمقادير وموازين وسنن واسباب اقتضتها حكمة الله تعالى ، وان الله لم يخلق شيئا الا بارادته وان جميع ما وجد في الكون موافق لما سبق في علمه ..", "ولقد نقض علي بن ابي طالب رضي الله عنه ( الجبرية ) في نفس رجل جاء يحتج بالقدر فقال له ( لعلك ظننت قدرا لازما وقضاء حتما ؟ لو كان كذلك لبطل الثواب والعقاب ، والوعد والوعيد والامر والنهي ، ولم تأت لائمة من الله لمذنب ، ولا محمدة لمحسن ، ولم يكن المحسن اولى بالمدح من المسيء ، ولا المسيء اولى بالذم من المحسن . تلك مقالة عباد الاوثان ، وجنود الشيطان وشهود الزور ، واهل العمى عن الصواب ، وهم قدرية هذه الامة ومجوسها ) .", "٢ - مشيئة الانسان ضمن مشيئة الله :", "خلق الله كل شيء .. وجعل في كل شيء خواص"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0129.png"}, {"n": 130, "paras": ["معينة .. فجعل في النار خاصة الاحراق ، وفي الماء خاصة الاحياء ، وفي السكين خاصة القطع ، وفي الخمر خاصة الاسكار. فحين يستخدم الانسان النار للاضرار فانما يفعل ذلك بمشيئته هو ، وان كانت فاعلية الاحراق مقدرة اساسا في النار بمشيئة الله تعالى . فدائرة مشيئة الله تعالى تقع في نطاقها خواص كل الاشياء في هذه الحياة . وأما دائرة مشيئة الانسان فتنحصر في نطق التصرف بهذه الخواص ، وهي مناط التكليف .. من ذلك ان الله تعالى جعل في العمل الجنسي خاصة التناسل . فمن مارسه نكاحا كان له في ذلك الاجر ، ومن مارسه سفاحا كتب عليه في ذلك الوزر .. ومن هنا نتبين ان هذه الخواص التي اختص الله بها الاشياء كل الاشياء ، وان كانت قابلية بعضها للشر من الله تعالى ، غير ان الله لم يجعل هذه الطبيعة على وجه يلزم الانسان بالشر ، وانما كان الانسان بما وهبه الله من عقل مطلق الحرية في الاختبار والمفاضلة ( لا اكراه في الدين قد تبين الرشد من الغي ) ونفس وما سواها فألهمها فجورها وتقواها ، قد أفلح من زكاها وقد خاب من دساها ) ( سيقول الذين اشركوا لو شاء الله ما اشركنا ولا اباؤنا ولا حرمنا من شيء ، كذلك كذب الذين من قبلهم حتى ذاقوا بأسنا . قل هل عندكم علم فتخرجوه لنا . ان تتبعون الا الظن وان انتم الا تخرصون . قل فلله الحجة البالغة فلو شاء لهداكم اجمعين ) .", "٣ - الهداية والاضلال : ان الهداية والاضلال اللذان بيد الله الامر الذي اتخذه"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0130.png"}, {"n": 131, "paras": ["البعض حجة على ان الانسان مجبر كقوله تعالى ( افمن حق عليه كلمة العذاب افانت تنقذ من في النار ) وقوله ( انكلا تهدي من احببت ولكن الله يهدي من يشاء ) . ان الهداية والاضلال هذه عللهما القرآن بانهما على سابقة استحقاق للعباد وبين اسبابهما مثل قوله تعالى : ( ان الله لا يهدي القوم الظالمين ) ( ان الله لا يهدي من هو كاذب كفار ) ( فلما زاغوا ازاغ الله قلوبهم ) ( كذلك يطبع الله على كل قلب متكبر جبار ) ( وما يضل به الا الفاسقين ) ( ويضل الله الظالمين ) .. فأصحاب هذه الصفات الذميمة لا يستحقون الهداية وهم بعيدون عن رحمة الله . أما الذين يستحقون الهداية فأمثال هذه الصفات ( ومن يؤمن بالله يهد قلبه ) ( قل ان الله يضل من يشاء ويهدي اليه من أناب ) ( يهدي به الله من اتبع رضوانه سبل السلام ) . والقرآن في كثير من آياته يثبت الاختيار للانسان وانه مسؤول عن اعماله ، وان الفساد الذي يشكو منه في حياته ، وضروب الشر الشائعة في شؤونه كل ذلك نتائج لمقدمات وضعها الانسان بنفسه . قال تعالى ( ظهر الفساد في البر والبحر بما كسبت أيدي الناس ) ( وما أصابكم من مصيبة فبما كسبت ايديكم ) ( ان الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم ) .", "٤ - الخلاصة : من خلال ما تقدم نستطيع ان نقول بأن اوامر الله تعالى في القرآن قسمان : الاول : أوامر تكوينية : كأمره تعالى للمخلوقات غير العاقلة ( يا نار كوني بردا وسلاما على ابراهيم ) ( يا ايتها"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0131.png"}, {"n": 132, "paras": ["النفس المطمئنة ارجعي الى ربك راضية مرضية ) فهذه الاوامر تقتضي الاطاعة الفورية ، والانسان لا يملك حيالها شيئا وبالتالي فهو ليس مسؤولا تجاهها البتة .", "فعمر الانسان وشكله وطوله وقامته ولون بشرته ورزقه وغير ذلك من النواميس التي تقوم بها حياة الانسان والتي يجري على اساسها هذا الكون الفسيح هي اوامر تكوينية قضى الله تعالى ان تكون كذلك فكانت ، والانسان لا يلام حيالها في شيء .", "الثاني : اوامر تكليفية : وهي الاوامر المكلف بها الانسان والمجزى بنتيجتها خيرا او شرا .. كقوله تعالى ( قل للمؤمنين يغضوا من ابصارهم ويحفظوا فروجهم ) وقوله ( يا ايها الذين آمنوا لا تأكلوا الربا اضعافا مضاعفة ) وقوله ( يا ايها الذين آمنوا قوا انفسكم واهليكم نارا ) فالانسان في نطاق هذه الدائرة من الاوامر التكليفية له حق المفاضلة والاختيار بل هو الذي يفاضل ويختار ، وهو بذلك مسؤول عن اعماله محاسب عليها ( فمن يعمل مثقال ذرة خيرا يره ، ومن يعمل مثقال ذرة شرا يره ) ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0132.png"}, {"n": 133, "paras": ["مراجع مقترحة للدراسة", "١ - كبرى اليقينيات الكونية للبوطي .", "٢ - العقيدة الاسلامية وأسسها لحبنكة .", "٣ - الله لحوى .", "٤ - روح الدين الاسلامي لطبارة ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0133.png"}, {"n": 134, "paras": ["الخطوط الكبرى للمنهج الإسلامي", "٢ - في موضوعات الشريعة :", "* في النظام العبادي", "* في النظام الاجتماعي", "* في النظام الاقتصادي", "* في النظام السياسي"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0134.png"}, {"n": 135, "paras": ["(١٠) في النظام العبادي", "وهو النظام الذي يبحث في تنظيم العلاقة بين العبد وربه، وفي الاعمال التي تقرب الى الله تعالى ، وتعمل على تزكية النفس وتطهيرها والسمو بها في معارج الربانية والكمال تحقيقا للتوازن الفطري بين مطالبها ومطالب البدن في حياة الانسان .. وتشمل اركان الاسلام الخمسة . روي ابن عمر رضي الله عنه ان النبي صلى الله عليه وسلم قال : « بني الاسلام على خمس : شهادة ان لا اله الا الله ، وان محمدا رسول الله - واقام الصلاة - وايتاء الزكاة - وصوم رمضان - وحج البيت من استطاع اليه سبيلا » .", "* الصلاة", "حكمها : الصلاة عمود الدين ، وركن من اركان الاسلام .. وفرض عين على كل مكلف . قال تعالى : ( حافظوا على الصلوات والصلاة الوسطى وقوموا لله قانتين ) .", "حكمتها : الصلاة معراج المؤمن الى الله، وفسحته الروحية التي تنير قلبه وتزكي نفسه ، وتهذب جوارحه ، مصداقا لقوله"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0135.png"}, {"n": 136, "paras": ["تعالى : ( ان الصلاة تنهى عن الفحشاء والمنكر ) ولقوله صلى الله عليه وسلم : أرأيتم لو أن نهرا بباب احدكم يغتسل منه كل يوم خمس مرات . هل يبقى من درنه شيء ؟ قالوا : لا يبقى من درنه شيء . قال : فذلك مثل الصلوات الخمس يمحو الله بهن الخطايا » (١) .", "حكم تاركها : تارك الصلاة في الاسلام عمدا كافر على رأي أئمة المذاهب ويجب قتله ، وعلى راي البعض الآخر فاسق ان كان تركه لها عمدا من غير جحود ، ويجب تعزيره او حبسه الى ان يصلي . قال صلى الله عليه وسلم : « العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر » (٢) وقال : « بين الرجل وبين الكفر ترك الصلاة » .", "شروطها : طهارة البدن والثوب والمكان ، ودخول وقت الصلاة ، واستقبال القبلة ، وستر العورة ، والوضوء .", "اركانها : النية - تكبيرة الاحرام - القيام للقادر - قراءة الفاتحة في كل ركعة - الركوع مع الطمأنينة - الاعتدال من الركوع مع الطمأنينة - السجود مع الطمأنينة - الجلوس بين السجدتين مع الطمأنينة - التشهد الاخير - الصلاة على النبي - التسليمة .", "مبطلاتها : خروج شيء من القبل او الدبر ، والكلام العمد ، وكثرة الحركة ، وترك ركن من اركانها او شرط من شروطها .", "اوقاتها : الصبح - الظهر - العصر - المغرب - العشاء .", "(١) متفق عليه .", "(٢) رواه الترمذي وقال : حديث حسن صحيح ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0136.png"}, {"n": 137, "paras": ["الأذان والاقامة : هما سنتان لكل فريضة بعد دخول الوقت . صلاة الجمعة : فرض عين على المكلفين المقيمين . ركعاتها اثنتان ، ويخطب قبلها خطبتين . صلاة المسافر : يجوز للمسافر قصر الصلاة الرباعية ويصليها ركعتين . وله ان يجمع بين الظهر والعصر وبين المغرب والعشاء . ومتى نوى اقامة اربعة ايام فأكثر فليس له القصر . واذا اقام بمكان مترقبا حاجته فله القصر الى ثمانية عشر يوما . ومسافة القصر ثمانية واربعون ميلا . صلاة الجنازة : يكبر اربع تكبيرات يقرأ في الاولى الفاتحة، ويصلى على النبي بعد الثانية ، ويدعو للميت بعد الثالثة ، ويسلم بعد الرابعة . صلاة العيد : صلاة العيد ركعتان ، يكبر في الاولى ثلاثا بعد تكبيرة الاحرام وقبل القراءة . ويكبر ثلاثا بعد القراءة في الركعة الثانية - الحنفي . الوضوء : فروضه ( النية - غسل الوجه - غسل اليدين مع المرفقين - مسح بعض الرأس - غسل الرجلين مع الكعبين - الترتيب ) . سننه : ( التسمية - غسل الكفين - المضمضة - الاستنشاق - مسح الرأس - مسح الاذنين - تخليل اللحية الكثة - تخليل اصابع اليدين والرجلين - التثليث في غير الرأس - الموالاة ) . نواقضه : ( ما خرج من السبيلين - والنوم العميق - وزوال العقل ، ومس فرج الادمي ( ولمس المرأة الاجنبية ) ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0137.png"}, {"n": 138, "paras": ["الغسل : موجباته : ( دخول الحشفة في الفرج - خروج المني باحتلام وغيره - انقطاع دم الحيض او النفاس والولادة - الموت ) . فروضه : ( النية - تعميم الماء على جميع البدن - ويسن الدلك والوضوء قبل الغسل ) . التيمم : شروطه : ( فقد الماء - خوف الضرر من استعماله - دخول وقت الصلاة ) . فروضه : ( النية - مسح الوجه واليدين بصعيد طاهر ) . سننه : ( التسمية وتخفيف الغبار والموالاة ) . مبطلاته : ( ما ابطل الوضوء - ووجود الماء - زوال السبب ) .", "* الصوم حكمه : الصيام ركن من اركان الاسلام وفريضة على كل مكلف مطيق، ويجوز للمسافر والمريض الافطار وعليهما قضاء . والعاجز عن الصيام لكبر أو مرض لا يرجى له شفاء يفطر ويكفر عن كل مدا . حكمته : الصوم في حقيقته عملية تجنيد .. فكما تحتاج الامم كلها لتجنيد ابنائها وتدريبهم على احتمال الجهد والمشاق توقعا للاحتياج اليهم يوم الصراع .. كذلك فرض الاسلام هذا التجنيد ولكن على نطاق اوسع ، يشمل الروح والجسد في وقت واحد ، ويشمل الصغار والكبار والرجال والنساء . فهو تدريب لهم على الصراع الاكبر، الصراع الدائم .. صراع الحياة التي يمارسها الجميع وتقع تبعاتها على الجميع (١) .", "(١) راجع « مزايا العبادات في الاسلام » للاستاذ محمد قطب ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0138.png"}, {"n": 139, "paras": ["تعريفه : الامساك عن المفطرات من طلوع الفجر الى الغروب . مبطلاته : الجماع - وصول شيء الى الجوف عمدا - الانزال - تعمد القيء . مباحاته : الاغتسال - تناول حقنة الدواء في العرق ام في العضل - تقبيل الرجل لزوجته - بلع الريق - الشرب والاكل والجماع بين الافطار والامساك . صيام التطوع : يسن صيام ( عاشوراء - العشر من ذي الحجة - ثلاثة ايام من كل شهر - الاثنين والخميس - ستة ايام من شوال ) .", "* الزكاة", "حكمها وحكمتها : هي ركن من اركان الاسلام ، وهي فريضة عبادية فضلا عن كونها ضرورة اجتماعية واقتصادية لما تحققه من تكافل في المجتمع الاسلامي . قال تعالى : ( خذ من اموالهم صدقة تطهرهم وتزكيهم بها ) وقال صلى الله عليه وسلم : « ان الله فرض على اغنياء المسلمين في أموالهم بقدر الذي يسع فقراءهم . ولن يجهد الفقراء اذا جاعوا او عروا الا بما يصنع اغنياؤهم . الا وان الله يحاسبهم حسابا شديدا ويعذبهم عذابا أليما » . انصبتها : - نصاب الذهب عشرون دينارا ، ونصاب الفضة مائتا درهم ، وفيها ربع العشر ، اي بالمائة اثنان ونصف.", "- نصاب الابل ، اوله خمسة ، وفيها شاة من الضأن أو المعز ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0139.png"}, {"n": 140, "paras": ["- نصاب الغنم ، اوله اربعون وفيها شاة من الضأن او المعز .", "- نصاب البقر ، اوله ثلاثون فاذا بلغتها ففيها تبيع او تبيعه ( ما كان عمره سنة ) .", "- زكاة التجارة ، تثمن اموال التجارة اخر الحول بقيمتها بنقد البلد وتخرج زكاتها نقدا وهو ربع العشر، أي بالمائة اثنان ونصف .", "- زكان الزروع والثمار ، العشر فيما سقته الامطار ، ونصف العشر فيما سقي بالالات - ونصاب هذه الزكاة عند أكثر الفقهاء خمسة أوسق أي ٦٨٤ كيلوغراما .", "مصارفها : تصرف الزكاة للاصناف الثمانية المحددة في قوله تعالى ( انما الصدقات للفقراء والمساكين والعاملين عليها والمؤلفة قلوبهم وفي الرقاب والغارمين وفي سبيل الله وابن السبيل فريضة من الله والله عليم حكيم ) .", "* الحج", "حكمه : هو فرض في العمر مرة على كل مسلم بالغ عاقل مستطيع ذكرا كان او انثى . ودليل فرضيته قوله تعالى : ( ولله على الناس حج البيت من استطاع اليه سبيلا ) وقوله صلى الله عليه وسلم : « يا ايها الناس قد فرض عليكم الحج فحجوا » .", "حكمته : تحقق الفائدة من اجتماع المسلمين وما ينتج عنها من تشاور في الشؤون والقضايا المشتركة ، ووضع حلول للقضايا القائمة والطارئة ، وتحقيق الوحدة والتضامن."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0140.png"}, {"n": 141, "paras": ["وفيه تتحقق المساواة الانسانية ، حيث يقف الجميع على صعيد واحد ، وبزي واحد ، لا تمايز بينهم ولا تفاضل . وفيه يتحقق سمو الروح وانخلاع النفس من ترابيتها وشهواتها وتجردها لله عز وجل ومراقبتها له . وفي هذا ما فيه من اثر في ترويض النفس وتطهيرها من أوضارها وأوزارها . انواعه : يؤدي الحج بثلاث طرائق : الافراد وهو الاحرام من الميقات بالحج فقط . التمتع وهو الاحرام بالحج عند الصعود الى عرفات . القران وهو الاحرام من الميقات المكاني بالحج والعمرة معا ، والقارن يبقى محرما حتى يتم اعمال العمرة والحج . ارکانه : النية عند الاحرام والوقوف بعرفة والطواف بالبيت سبعا والسعي بين الصفا والمروة سبعا والحلق . واجباته : الاحرام من الميقات ورمي الجمار والمبيت بمزدلفة والمبيت في منى ايام التشريق وطواف الوداع . سننه : التلبية وطواف القدوم والجمع بين الليل والنهار في عرفة والغسل عند لبس الاحرام والذبح . محرماته : الجماع والتقبيل والاستمناء والتطيب وعقد النكاح ولبس المخيط وقتل الصيد ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0141.png"}, {"n": 142, "paras": ["كتب مقترحة للمطالعة حول موضوع ( النظام العبادي )", "- العبادة في الاسلام تأليف الدكتور يوسف القرضاوي", "- فقه الزكاة تأليف الدكتور يوسف القرضاوي", "- العبادات في الاسلام تأليف محمد اسماعيل عبده", "- روح الصلاة في الاسلام تأليف عفيف طبارة", "- الاسلام بين المادية والروحية تأليف محمد عبد الرؤوف بهنسي", "- ربانية لا رهبانية تأليف السيد ابي الحسن الندوي", "- مزايا العبادات في الاسلام تأليف محمد قطب", "- فلسفة الصوم واسراره تأليف المرحوم الدكتور مصطفى السباعي", "- رسالة العبادات تأليف جماعة من العلماء", "- آداب الحج واسراره تأليف احمد عبد الجليل", "- المناجاة تأليف الشهيد حسن البنا", "- المأثورات تأليف الشهيد حسن البنا", "- اقامة الحجة تأليف الامام اللكنوي الهندي", "- رسالة المسترشدين تأليف المحاسبي", "- روح الدين الاسلامي تأليف عفيف طبارة", "- الاسلام تأليف سعيد حوى"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0142.png"}, {"n": 143, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0143.png"}, {"n": 144, "paras": ["في النظام الاجتماعي *", "يستهدف النظام الاجتماعي في الاسلام دعم التماسك العائلي ، وتنظيم العلاقة بين افراد العائلة الواحدة ، والجوار الواحد والحي الواحد ، وتحقيق التعاون بينهم في سبيل اصلاح المجتمع وتنقيته من كل ما يفسد فكره وخلقه . بما في ذلك تحقيق التكافل المادي بين المواطنين ، الذي من شأنه توثيق الروابط وجعل المجتمع وحدة متماسكة يتجسد فيها قول الرسول صلى الله عليه وسلم : « مثل المؤمنين في توادهم وتراحمهم وتعاطفهم مثل الجسد اذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى» (١) . وتحقيقا لهذه الغاية يقرر الاسلام ما يلي :", "• اعتبار الفرد الصالح حجر الزاوية في بناء المجتمع الاسلامي . ولذلك عني الاسلام بتربيته وبناء عقليته ونفسيته على اساس من احكام الشرع ومتطلبات الفطرة من غير تفريط ولا افراط . ( ونفس وما سواها ، فألهمها فجورها وتقواها ، قد افلح من زكاها ، وقد خاب من دساها ) .", "• اعتبار الاسرة الخلية الاولى في كيان الدولة الاسلامية.", "(١) رواه مسلم واحمد ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0144.png"}, {"n": 145, "paras": ["والرجل والمرأة هما عنصراها اللذان تقوم بهما وتعتمد عليهما . ولذلك شرع الاسلام امورا كثيرة منها :", "- تنظيم غريزة النوع بالزواج واعتبار كل علاقة اخرى خطرا ماحقا يهدد كيان الامة : ( والذين هم لفروجهم حافظون، الا على ازواجهم او ما ملكت ايمانهم فانهم غير ملومين ) ولذلك حرم الاسلام الزنا واللواط والاستمناء ، وشجع الشباب على الزواج فقال صلى الله عليه وسلم : « يا معشر الشباب ، من استطاع منكم الباءة فليتزوج ، ومن لم يستطع فعليه بالصوم فانه له وجاء » (١) .", "- ضمان تحقيق الفضيلة في تعاون الزوجين امتثالا لقوله تعالى : ( وتعاونوا على البر والتقوى ولا تعاونوا على الاثم والعدوان ) .", "- ضمان حرية كل من الفريقين في اختيار شريكه . قال الرسول صلى الله عليه وسلم : « تخيروا لنطفكم فانكحوا الاكفاء وانكحوا اليهم » (٢) وقال : « لا تزوج الايم حتى تستأمر ، ولا البكر حتى تستأذن » . وقد روي ان المغيرة بن شعبة خطب امرأة ، فقال له النبي صلى الله عليه وسلم : « انظر اليها ، فانه احرى ان يؤدم بينكما » أي تحصل الموافقة والملاءمة .", "- ضمان حق المرأة في العمل فيما لا يتعارض مع مصلحة الاسرة او حدود الشرع ولا يؤدي الى ضرر خلقي او اجتماعي ، او يكلفها ما لا تطيق . ولقد كان نساء المسلمين يشاركن الرجال في الغزوات والحروب وفي بعض الاعمال والتجارة . فهذه ام حكيم بنت الحارث تخوض معركة بين الروم والمسلمين .", "(١) رواه البخاري ومسلم .", "(٢) حديث صحيح رواه ابن ماجه والبيهقي ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0145.png"}, {"n": 146, "paras": ["وهي عروس لم تفارقها رائحة العرس . ويستشهد زوجها على مرأى منها ، فلا تبكي ولا تنتحب ، وانما تشد عليها ثيابها ، وتنتزع عمود الفسطاط الذي شهد ليلة زفافها ، وتصرع به سبعة من الاعداء عند القنطرة التي لا تزال حتى اليوم معروفة باسم ( قنطرة ام حكيم ) .", "- ضمان تحقيق الفصل بين مجتمع النساء ومجتمع الرجال ومنع الاختلاط لغير حاجة يقدرها الشرع مصداقا لقوله تعالى: ( واذا سألتموهن متاعا فاسألوهن من وراء حجاب ذلكم اطهر لقلوبكم وقلوبهن ) وقوله صلى الله عليه وسلم : « ما خلا رجل بامرأة الا وكان الشيطان ثالثهما » (١) .", "- ضمان تحقيق قوامة الرجل على المرأة في قيادة الاسرة ورعاية شؤونها مصداقا لقوله تعالى ( الرجال قوامون على النساء بما فضل الله بعضهم على بعض وبما انفقوا من اموالهم) وقوله : ( ولهن مثل الذي عليهن بالمعروف وللرجال عليهن درجة ) .", "- ضمان تحقيق المساواة في الحقوق والواجبات .", "- ضمان تحقيق يسر المهور وتكاليف الزواج عملا بقوله صلى الله عليه وسلم : « ان اعظم النكاح بركة ايسره مئونه » وقوله : « خير الصداق ايسره » (٢) .", "• اعتبار المساواة الانسانية هي الصفة الاساسية للمجتمع المسلم . وان الناس يرجعون في نظر الاسلام الى اصل واحد لا فرق بين فرد واخر ، ولا ميزة له عليه الا بما", "(١) رواه البخاري .", "(٢) رواه ابن ماجه والحاكم ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0146.png"}, {"n": 147, "paras": ["يقدمه من خير لنفسه ومجتمعه . وهذا ما عبر عنه القرآن بقوله : (يا ايها الناس انا خلقناكم من ذكر وانثى وجعلناكم شعوبا وقبائل لتعارفوا ، ان اكرمكم عند الله اتقاكم ان الله عليم خبير) والذي عناه رسول الله صلى الله عليه وسلم قال : « ايها الناس : ان ربكم واحد . وان أباكم واحد . كلكم لادم وآدم من تراب . اكرمكم عند الله اتقاكم . وليس لعربي على عجمي، ولا لعجمي على عربي ولا لاحمر على ابيض ، ولا لابيض على احمر فضل الا بالتقوى . الا هل بلغت . اللهم فاشهد . ألا فليبلغ الشاهد منكم الغائب » .", "• اعتبار التكافل الاجتماعي واجبا شرعيا مقدسا في المجتمع المسلم . وان هذا التكافل ليس قاصرا على تأمين الغذاء والكساء والمسكن للفقراء والمساكين ، بل هو شامل لضمان حقوق الانسان الطبيعية ( حق الحياة والحرية والعلم والكرامة والتملك ) . والقاعدة الاساسية التي يصدر عنها مبدأ التكافل في الاسلام ، اعتبار افراد المجتمع اخوة ( انما المؤمنون اخوة ) وان عليهم ان يؤدوا واجبات الاخوة فيما بينهم « لا يؤمن احدكم حتى يحب لاخيه ما يحب لنفسه » (١) .", "• اعتبار الاخلاق الكريمة القوة الضابطة للطاقات ، والروح التي تشيع الخير والامن والفضيلة . وان الدولة المسؤول الاول عن تطهير المجتمع من الفساد واسبابه ، وان من واجبها ان تنشر الفضيلة وتحارب الرذيلة ، حتى تتحقق في المجتمع الغاية التي جاء من اجلها الاسلام « انما بعثت لاتمم مكارم الاخلاق » . وتحقيق ذلك انما يتم عن طريق الاهتمام بتركيز العقيدة في النفوس وتطبيق احكام الاسلام بصفة عامة. وبذلك يستشعر كل فرد مسؤولية صيانة المجتمع من الموبقات", "(١) رواه البخاري ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0147.png"}, {"n": 148, "paras": ["مصداقا لحديث الرسول صلى الله عليه وسلم : « ان من نفس ابن ادم الا عليها صدقة في كل يوم طلعت فيه الشمس . قيل: يا رسول الله من اين لنا صدقة نتصدق بها ؟ فقال : ان ابواب الخير لكثيرة ، التسبيح والتحميد والتكبير والتهليل ، والامر بالمعروف والنهي عن المنكر ، وتميط الاذى عن الطريق ، وتسمع الاصم وتهدي الاعمى ، وتدل المستدل على حاجته ، وتسعى بشدة ساقيك مع اللهفان المستغيث ، وتحمل بشدة ذراعيك مع الضعيف » ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0148.png"}, {"n": 149, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0149.png"}, {"n": 150, "paras": ["مراجع مقترحة للدراسة", "- المجتمع الانساني في ظل الاسلام تأليف محمد ابو زهرة", "- الاسلام والاسرة تأليف عوض معوض ابراهيم", "- المرأة بين الفقه والقانون تأليف الدكتور مصطفى السباعي", "- المرأة بين البيت والمجتمع تأليف البهي الخولي", "- النظام الاجتماعي في الاسلام تأليف تقي الدين نبهاني", "- الحجاب تأليف الاستاذ المودوي", "- اخلاقنا الاجتماعية تأليف الدكتور مصطفى السباعي", "- امراضنا الاجتماعية تأليف محمد احمد باشميل", "- في النفس والمجتمع تأليف الاستاذ محمد قطب", "- منهج التربية في الاسلام تأليف الاستاذ محمد قطب", "- معركة التقاليد تأليف الاستاذ محمد قطب", "- خلق المسلم تأليف الاستاذ محمد الغزالي", "- الاسلام تأليف سعيد حوى"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0150.png"}, {"n": 151, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0151.png"}, {"n": 152, "paras": ["(١٢) في النظام الاقتصادي", "ويستهدف النظام الاقتصادي في الاسلام تنمية الانتاج العام ومضاعفته لضمان اشباع حاجات الناس الاساسية وتمكينهم من تأمين حاجاتهم الكمالية من غير اسراف ولا تبذير، وصولا الى تقريب الشقة بين مختلف الطبقات بما من شأنه تحقيق العدالة والرخاء والرفاه لكل افراد المجتمع .", "ومن اجل ذلك قرر الاسلام ما يلي :", "١ - يد الانسان على الثروة يد عارضة ، والكون كله ملك لله تعالى : ( لله ملك السموات والارض ) ( وسخر لكم ما في الارض ) ( وسخر لكم ما في السموات ) ( وانفقوا مما جعلكم مستخلفين فيه ) .", "٢ - الملكية ثلاثة انواع : ملكية فردية - وملكية عامة - وملكية الدولة .", "٣ - الملكية الفردية مصونة في النظام الاقتصادي وكل ما اكتسبه الفرد عن طريق مشروع يصبح حقا له مصداقا لقوله صلى الله عليه وسلم : « من سبق الى ما لم يسبق اليه"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0152.png"}, {"n": 153, "paras": ["مسلم فهو احق به » (۱) وقوله : « من احيا ارضا مواتا فهي له » (۲) وتأكيدا على حرمة الملكية الفردية في الاسلام يقول الرسول صلى الله عليه وسلم «كل المسلم على المسلم حرام ، دمه وماله وعرضه » ويقول: « من مات دون ماله فهو شهيد .(۳) .", "٤ - الملكية العامة ، هي اذن الشارع للجماعة بالاشتراك في الانتفاع بالعين . ومن ذلك المراعي والاحراش والاحتطاب والمناجم ومنابع البترول والطرق والمياه مصداقا لحديث الرسول صلى الله عليه وسلم : « الناس شركاء في ثلاث في الماء والكلأ والنار » (٤) .", "ه - ملكية الدولة ، وهو ما تقتضي المصلحة العامة بتملكه أو ما تستهلكه الدولة في المصالح العامة كصناعة السفن والسلاح والطائرات وما شابهها .", "٦ - ضمان تهيئة وسائل العمل لكل فرد في الامة بما يضمن لكل فرد سكنا يأوي اليه ، ومعيشة تدفع عنه الامراض، وتكفل له ولاولاده الضمان الصحي والاجتماعي والثقافي .. هذا ما تشير اليه احاديث كثيرة للرسول صلى الله عليه وسلم ، منها قوله : « من ولي لنا عملا وليس له منزل فليتخذ له منزلا ، او ليست له زوجة فليتزوج ، او ليس له دابة فليتخذ دابة » (٥) .", "٧ - ضمان حق العامل في تناول الاجر المناسب مع كفاءته على ان لا يقل عن الحد الادنى لتكاليف المعيشة المتوسطة.", "(۱) رواه ابو داود .", "(۲) رواه ابو داود واحمد والترمذي .", "(۳) رواه ابو داود وابن ماجه .", "(٤) رواه احمد وابو داود .", "(٥) رواه احمد ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0153.png"}, {"n": 154, "paras": ["قال الرسول صلى الله عليه وسلم : « ثلاثة انا خصمهم يوم القيامة - منهم - ورجل استأجر اجيرا فلم يوفه أ ره » (۱) وقوله : « هم اخوانكم وخولكم ، جعلهم الله تحت ايديكم ، فمن كان اخوه تحت يده فليطعمه مما يأكل ويلبسه مما يلبس » وقوله : « من استأجر اجيرا فليعلمه أجره ، وقوله : « أعطوا الاجير أجره قبل ان يجف عرقه » (۲) .", "٨ - الزكاة بكل انواعها هي الحق الادنى في المال وتوجه في مصارفها المحدودة ( انما الصدقات للفقراء والمساكين والعاملين عليها والمؤلفة قلوبهم وفي الرقاب والغارمين وفي سبيل الله وابن السبيل ) .", "٩ - للدولة ان تفرض الضرائب العادلة على المواطنين اذا دعت الحاجة الى ذلك مصداقا لقوله صلى الله عليه وسلم : « ان في المال حقا سوى الزكاة » يقول الشاطبي : « انا اذا قررنا اماما مطاعا مفتقرا الى تكثير الجنود لسد حاجة الثغور وحماية الملك المتسع الاقطار ، وخلا بيت المال ، وارتفعت حاجات الجند الى ما لا يكفيهم ، فللامام اذا كان عدلا ان يوظف على الاغنياء ما يراه كافيا لهم ( اي للجنود ) في الحال » .", "١٠ - تحريم كل عمل يعود على المجتمع بالضرر او يقوم على الربا والاحتكار والغش . ولذلك حظر الاسلام امورا كثيرة منها : بيع الاشياء المحرمة ، وبيع الغرر ، والتلاعب بالاسعار ، والاحتكار ، والغش ، وتطفيف الكيل ، والربا ، والقاعدة الشرعية في ذلك كله ( لا ضرر ولا ضرار ) .", "(۱) و (۲) - رواهما ابن ماجه ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0154.png"}, {"n": 155, "paras": ["١١ - الحث على الانفاق في وجوه الخير وافتراض التكافل بين المواطنين . يقول الرسول صلى الله عليه وسلم : « المسلم اخو المسلم لا يظلمه ولا يسلمه من كان في حاجة اخيه كان الله في حاجته ، ومن فرج عن مسلم كربه فرج الله عنه بها كربة من كرب القيامة ، ومن ستر مسلما ستره الله يوم القيامة » .", "١٢ - تقرير مسؤولية الدولة في حماية هذه المبادىء استنادا لقوله صلى الله عليه وسلم « كلكم راع وكلكم مسؤول عن رعيته » ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0155.png"}, {"n": 156, "paras": ["كتب مقترحة للمطالعة حول موضوع ( النظام الاقتصادي )", "- أسس الاقتصاد بين الاسلام تأليف الاستاذ المودودي. والنظم المعاصرة", "- العدالة الاجتماعية في الاسلام تأليف الشهيد سيد قطب", "- اشتراكية الاسلام تأليف الدكتور مصطفى السباعي", "- النظام الاقتصادي في الاسلام تأليف تقي الدين النبهاني", "- الربا تأليف الاستاذ المودودي", "- نظم العمل في الاسلام تأليف جمال الدين عياد", "- المال والحكم في الاسلام تأليف الشهيد عبد القادر عودة", "- مشكلة الفقر وكيف عالجها تأليف يوسف القرضاوي الاسلام", "- الاسلام والاوضاع الاقتصادية تأليف محمد الغزالي", "- مشكلاتنا في ضوء الاسلام تأليف الشهيد حسن البنا", "- مصرع الفقر في الاسلام تأليف علي شحاتة", "- الاسلام يحارب الفقر تأليف محمد فتحي عثمان", "- الاسلام تأليف سعيد حوى", "- سلسلة مفاهيم اقتصادية عدة مؤلفين"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0156.png"}, {"n": 157, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0157.png"}, {"n": 158, "paras": ["(١٣) في النظام السياسي", "تتلخص نظرية الاسلام السياسية في النقاط التالية :", "١ - الامة الاسلامية واحدة .. والاقطار الاسلامية القائمة في العالم تعتبر كأنها قائمة في بلاد واحدة وتخضع لقيادة واحدة ( ان هذه امتكم امة واحدة وانا ربكم فاعبدون ) .", "٢ - العقيدة الاسلامية هي اساس الدولة بحيث تصدر عنها في كافة شؤونها .", "٣ - حمل الدعوة الاسلامية هو العمل الاصيل للدولة مصداقا لقوله تعالى : ( لقد أرسلنا رسلنا بالبينات وأنزلنا الكتاب والميزان ، ليقوم الناس بالقسط ، وأنزلنا الحديد فيه بأس شديد ومنافع للناس ) وقوله : ( الذين ان مكناهم في الارض اقاموا الصلاة واتوا الزكاة وامروا بالمعروف ونهوا عن المنكر ولله عاقبة الامور ) وقوله : ( كنتم خير امة اخرجت للناس ، تأمرون بالمعروف وتنهون عن المنكر وتؤمنون بالله ) .", "٤ - الحاكمية في الدولة الاسلامية لله ، والكتاب والسنة هي وحدها الادلة المعتبرة للاحكام الشرعية . قال تعالى : ( وما اختلفتم فيه من شيء فحكمه الى الله ذلكم الله ربي"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0158.png"}, {"n": 159, "paras": ["عليه توكلت واليه انيب ) وقوله : ( ان الحكم الا لله ) وقوله صلى الله عليه وسلم : « تركت فيكم شيئين لن تضلوا بعدي ما تمسكتم بهما ، كتاب الله وسنتي » (١) . ويروى ان رسول الله صلى الله عليه وسلم سأل حذيفة بن اليمان عندما ولاه على اليمن فقال : بماذا تحكم يا حذيفة ان عرض لك قضاء ؟ قال حذيفة : بكتاب الله قال : فان لم تجد ؟ قال : فبسنة رسول الله . قال : فان لم تجد ؟ قال : اجتهد رأيي لا آلو . فربت الرسول صلى الله عليه وسلم على كتفه وقال: «الحمد لله» .", "ه - الشورى في الدولة الاسلامية حق لجميع المسلمين على رئيس الدولة ، وان عليه ان يرجع اليهم وان لا ينفرد برأيه . قال تعالى : ( فبما رحمة من الله لنت لهم ، ولو كنت فظا غليظ القلب لانفضوا من حولك ، فاعف عنهم واستغفر لهم وشاورهم في الامر ، فاذا عزمت فتوكل على الله ) وقال : ( والذين استجابوا لربهم وأقاموا الصلاة وأمرهم شورى بينهم ومما رزقناهم ينفقون ) وقال الرسول صلى الله عليه وسلم : « ما خاب من استشار وما ضل من استخار » (٢) وقال : « المستشار مؤتمن » وقال : « ما تشاور قوم قط الا هدوا الى رشد أمرهم » .. أما نتيجة الشورى فانها غير ملزمة والله اعلم .", "٦ - الحاكم في الدولة الاسلامية مسؤول بين يدي الله ومن الناس . وهو الامام المكلف باقامة امر الله ، وان على الامة السمع والطاعة ما لم يأمر بمعصية . قال تعالى : ( يا ايها الذين امنوا اطيعوا الله واطيعوا الرسول واولي الامر منكم، فان تنازعتم في شيء فردوه الى الله والرسول ، ان كنتم", "(١) رواه الحاكم في مستدركه .", "(٢) رواه الطبراني في الاوسط ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0159.png"}, {"n": 160, "paras": ["تؤمنون بالله واليوم الآخر ، ذلك خير واحسن تأويلا ) وقال الرسول صلى الله عليه وسلم : « من اطاعني فقد اطاع الله ، ومن عصاني فقد عصى الله ، ومن يطع الامير فقد اطاعني ، ومن يعصي الامير فقد عصاني » (١) .", "٧ - محاسبة الحكام من قبل المسلمين حق من حقوقهم وفرض كفاية عليهم . وذلك المعبر عنه في قوله صلى الله عليه وسلم : « على المرء السمع والطاعة فيما احب وكره الا ان يؤمر بمعصية ، فاذا امر بمعصية فلا سمع ولا طاعة » (٢) وقوله: « الدين النصيحة ، قلنا : لمن ؟ قال : لله ولكتابه ولرسوله ولائمة المسلمين وعامتهم » (٣) وقوله : « اذا رأيت امتي تهاب ان تقول للظالم يا ظالم فقد تودع منها » وقوله : « افضل الجهاد كلمة حق عند سلطان جائر » (٤) وقوله: « لا طاعة لمخلوق في معصية الخالق » (٥) .", "٨ - تتمتع الطوائف غير الاسلامية بالحقوق العامة التي يتمتع بها المسلمون وعليهم ما على المسلمين من واجبات . ولهم استقلالهم الذاتي في الاحوال الشخصية وبعض القضايا الخاصة والقاعدة الشرعية في ذلك ( لهم مالنا وعليهم ما علينا ) مصداقا لقوله صلى الله عليه وسلم : « من اذى ذميا فقد اذاني ومن", "(١) متفق عليه .", "(٢) متفق عليه .", "(٣) رواه مسلم .", "(٤) رواه ابن ماجه واحمد .", "(٥) رواه الشيخان ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0160.png"}, {"n": 161, "paras": ["اذاني كنت خصمه يوم القيامة ، وقوله : « الا من ظلم معاهدا او انتصفه او كلفه فوق طاقته او اخذ منه شيئا بغير طيب نفس ، فانا حجيجه يوم القيامة ، ولقد روى عمر بن الحسن عن ابراهيم رحمهما الله ان رجلا من المسلمين قتل رجلا من اهل الذمة . فرفع ذلك الى رسول الله صلى الله عليه وسلم ، فقال: « انا أحق من وفى بذمته » ثم أمر بقتل المسلم ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0161.png"}, {"n": 162, "paras": ["كتب مقترحة للمطالعة حول موضوع ( النظام السياسي في الاسلام )", "- نظرية الاسلام السياسية تأليف الاستاذ المودودي", "- النظام السياسي في الاسلام تأليف تقي الدين نبهاني", "- نظام الحكم في الاسلام تأليف تقي الدين نبهاني", "- النظام السياسي في الاسلام تأليف الدكتور عبد الكريم عثمان", "- الشورى في الاسلام تأليف الدكتور محمود بابلي", "- الاسلام واوضاعنا السياسية تأليف عبد القادر عودة", "- منهج الاسلام في الحكم تأليف محمد أسد", "- المال والحكم في الاسلام تأليف عبد القادر عودة", "- الاسلام والاستبداد السياسي تأليف محمد الغزالي", "- الاسلام واوضاعنا القانونية تأليف عبد القادر عودة", "- التشريع الجنائي في الاسلام تأليف عبد القادر عودة", "- العقوبة في الفقه الاسلامي تأليف احمد فتحي بهنسي", "- القانون الاسلامي تأليف الاستاذ المودودي", "- مشكلاتنا في ضوء الاسلام تأليف الشهيد حسن البنا", "- الدين والدولة في الاسلام تأليف الدكتور مصطفى السباعي", "- الفرد والدولة في الشريعة الاسلامية تأليف الدكتور عبد الكريم زيدان", "- احكام الذميين والمستأمنين تأليف الدكتور عبد الكريم زيدان", "- نظام السلم والحرب في الاسلام تأليف الدكتور مصطفى السباعي", "- الاسلام تأليف الاستاذ سعيد حوى"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0162.png"}, {"n": 163, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0163.png"}, {"n": 164, "paras": ["المبحث الرابع", ". التنظيم الحركي الاسلامي ضرورة والعمل فيه واجب"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0164.png"}, {"n": 165, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0165.png"}, {"n": 166, "paras": ["(١٤) التنظيم الحركي ضرورة والانخراط فيه واجب", "في هذه الحلقة ينبغي ان يعالج الداعية موضوع العمل لاستئناف الحياة الاسلامية واقامة الحكم الاسلامي ، مؤكدا على انه واجب شرعي ، وانه - اي العمل لاستئناف الحياة الاسلامية واقامة الحكم الاسلامي - يفرض وجود تنظيم حركي او الانضواء في تنظيم حركي . وبامكان الداعية تناول هذا الموضوع من خلال النقاط التالية :", "عمل الرسول كان حركيا وليس فرديا", "ان مما يؤكد ضرورة اقامة تنظيم حركي للاسلام كسبيل لاستئناف الحياة الاسلامية واقامة الحكم الاسلامي ، النهج الذي اعتمده الرسول صلى الله عليه وسلم في تحضيرة لاقامة الدولة الاسلامية .", "فالرسول صلى الله عليه وسلم لم يعتمد اسلوب العمل الفردي ، وانما حرص من اول يوم على اقامة تنظيم حركي كان يختار عناصره اختيارا وينتقي افراده انتقاء ليكون قوة الدفع"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0166.png"}, {"n": 167, "paras": ["في المسيرة الاسلامية التي لم يطل عليها الزمن حتى كانت ملء عين العالم وسمعه وبصره .. ( راجع السيرة النبوية في العهد المكي ) .", "العمل الجماعي واجب شرعي", "ويمكن القول كذلك بأن العمل الجماعي للاسلام واجب شرعي ، ذلك ان العمل لاستئناف الحياة الاسلامية واجب شرعي ، وان هذا الواجب لا يتحقق الا بقيام تنظيم جماعي ، فتصبح بالتالي الجماعية في العمل للاسلام هي الاخرى واجبا شرعيا .", "ولقد ورد في القرآن والسنة كثير من النصوص تدعه الى التعاون والتجمع والتزام الصف الواحد .. ففي القرآن الكريم جاء قوله تعالى : ( ولتكن منكم امة يدعون الى الخير ويأمرون بالمعروف وينهون عن المنكر ) وقوله : ( كنتم خير امة اخرجت للناس تأمرون بالمعروف وتنهون عن المنكر وتؤمنون بالله ) وقوله : ( فلولا نفر من كل فرقة منهم طائفة ليتفقهوا في الدين ولينذروا قومهم اذا رجعوا اليهم لعلهم يحذرون ) وقوله : ( سنشد عضدك بأخيك ونجعل لكما سلطانا فلا يصلون اليكما بآياتنا انتما ومن اتبعكما الغالبون ) وقوله : ( وتعاونوا على البر والتقوى ) .", "وفي الحديث الشريف جاء قوله صلى الله عليه وسلم : « عليكم بالجماعة فان الجماعة رحمة والفرقة عذاب » وقوله : « من فرق ليس منا ، يد الله مع الجماعة وانما يأكل الذئب من الغنم القاصية (١) وقوله : « عليك بجماعة المسلمين وامامهم » .", "(١) رواه الطبراني في الكبير ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0167.png"}, {"n": 168, "paras": ["قال حذيفة : فان لم يكن لهم جماعة ولا امام ؟ قال : ولو ان تعض على جذع نخلة حتى يدركك الموت وانت على ذلك ، وقوله : « من مات وهو مفارق للجماعة فانه يموت ميتة جاهلية » (١) .", "* التنظيم والبيعة والامارة", "ونقطة اخرى كذلك يمكن اعتبارها دليلا على ضرورة التنظيم الحركي للاسلام ، وهي ان العمل كل عمل لا بد له في حكم الاسلام - من تنظيم ، وان كل تنظيم لا بد وان يقوم على رأسه قائد يطاع بالمعروف . ومن هنا جاءت نصوص شرعية عديدة توجب اتخاذ امير او قائد ينزل الجميع عند رأيه ، حرصا على وحدة الكلمة وانتظام الصف وانضباطه . والدعوة الى اتخاذ امور تعني بداهة وجود تنظيم وجماعة اذ لا مبرر لوجود امير من غير امارة وهذا ما اشار اليه الرسول صلى الله عليه وسلم بقوله « ان كنتم ثلاثة فأمروا احدكم » وقوله : « من خلع يدا من طاعة لقي الله يوم القيامة ولا حجة له، ومن مات في عنقه بيعة مات ميتة جاهلية » .", "اهداف الاسلام الضخمة تفرض وجود تنظيم حركي", "ثم ان على الداعية ان يبين للمدعو ان الطريق لاستئناف الحياة الاسلامية واقامة الدولة الاسلامية لا يتحققان بمجرد الوعظ والارشاد ، او بتحريك اللسان بالكلام والقلم بالكتابة .. بل ان ذلك ليحتاج الى تحضير كافة المستلزمات والمتطلبات العلمية والمادية والفنية والبشرية التي يحتاجها هذا الهدف الضخم ..", "(١) رواه مسلم ."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0168.png"}, {"n": 169, "paras": ["فالاسلام دعوة هدم وبناء .. هدم المجتمع الجاهلي برمته واقامة المجتمع الاسلامي مكانه .. وعملية الهدم هذه تتطلب من التكاليف ما يعجز عن القيام بأعبائها الافراد .. بل لا يقوى على النهوض بها ، مع الجهد الشاق الا تنظيم حركي يكون في مستوى المعركة المنتظرة .", "ثم ان طريق العمل الاسلامي مفروشة بالاشواك محفوفة بالمخاطر ، فالعقبات التي تعترض الطريق كثيرة .. والقوى التي تتربص بالاسلام واهله كبيرة .. والمشكلات التي خلفتها الحضارات والفلسفات المادية تتطلب جهودا جبارة على كل صعيد ..", "وهذا ما يفرض وجود تنظيم حركي كما يفرض على كل من آمن بالاسلام على انه منهج ان يكون من نواة هذا التنظيم وطليعته ومن الداعين اليه والعاملين على دعمه وتطويره وتنميته .."], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0169.png"}, {"n": 170, "paras": ["تطلب جميع منشوراتنا من : الشركة المتحدة للتوزيع بيروت - شارع سوريا - بناية صمدي وصالحة هاتف : ٨١٥١١٢ - ٢١٩٠٣٩ ص.ب : ٧٤٦٠ برقيا : بيوشران"], "img": "../../../_ocr-work/libocr/yakan-kayfa-nadu/pages/0170.png"}]};
